; ============================================================
; DK Screen Recorder for AutoHotkey v2
; Companion to DK_Screenshot_Clipboard.ahk.
;
; Records a monitor or a window to an .mp4 with ffmpeg (gdigrab), showing a
; live on-screen REC indicator plus the shared bottom-left OSD messages.
;
; Stopping ffmpeg is the tricky part on Windows: sending "q" on stdin or a hard
; kill both leave a CORRUPT file (no moov atom). The only reliable stop is a
; console CTRL_BREAK, which makes ffmpeg finalize a playable file. A persistent
; console-ctrl handler (DKRecConsoleCtrlHandler) keeps THIS script alive through
; that same signal. Both behaviours were verified before this module shipped.
;
; Multi-clip session (pause / resume):
;   Pause finalizes the current .mp4 and keeps the same target ready.
;   Resume starts a NEW clip (new file). Full stop ends the session.
;   So one "swoop" can produce many clips without re-picking the monitor.
;
; Files are written to:  %USERPROFILE%\Videos\DK Screen Recordings
; Settings (optional):   Screen_Recorder_Settings.ini  (next to this script)
;   [Recorder]
;   Framerate=30
;   Preset=veryfast          ; ffmpeg x264 preset (ultrafast..medium)
;   CRF=23                   ; quality: lower = better/bigger (18-28 typical)
;   OutputDir=               ; blank = Videos\DK Screen Recordings
;   Target=1080              ; 1080 | primary | under_mouse | <monitor index 1..N>
; ============================================================

global DKRecActive           := false
global DKRecPaused           := false
global DKRecPid              := 0
global DKRecStartTick        := 0
global DKRecOutFile          := ""
global DKRecTargetLabel      := ""
global DKRecIndicatorGui     := ""
global DKRecIndicatorTimeCtl := ""
global DKRecChordLast        := 0
global DKRecFfmpegPath       := ""
global DKRecSettingsFile     := A_ScriptDir "\Screen_Recorder_Settings.ini"
global DKRecEnumAccum        := []

; Last capture target so pause/resume reuses the same region without re-aiming.
global DKRecLastX            := 0
global DKRecLastY            := 0
global DKRecLastW            := 0
global DKRecLastH            := 0
global DKRecLastLabel        := ""
global DKRecLastMonIndex     := 0
global DKRecClipCount        := 0

; Console-ctrl handler so the CTRL_BREAK we aim at ffmpeg cannot kill this script.
global DKRecCtrlCallback := CallbackCreate(DKRecConsoleCtrlHandler, "Fast", 1)

DKRecConsoleCtrlHandler(ctrlType) {
    ; 0 = CTRL_C, 1 = CTRL_BREAK -> claim as handled so we are not terminated.
    ; Everything else (close/logoff/shutdown) passes through untouched.
    if (ctrlType = 0 || ctrlType = 1)
        return 1
    return 0
}

; ------------------------------------------------------------
; Public entry points (bound to arrow chords in Main_Tree)
; ------------------------------------------------------------

; Up + Left  -> preferred monitor (default: 1080-class screen).
; Idle  : start recording
; Rec   : full stop (save current clip, end session)
; Paused: full stop (end session without a new clip)
DKRecTogglePreferredMonitor() {
    if DKRecChordDebounced()
        return
    global DKRecActive, DKRecPaused
    if DKRecActive || DKRecPaused {
        DKRecStop(true)
        return
    }
    if !DKRecResolvePreferredMonitor(&x, &y, &w, &h, &label, &monIdx) {
        DKRecMessage("Screen Recorder", "Could not find preferred monitor")
        return
    }
    DKRecStart(x, y, w, h, label, monIdx)
}

; Up + Right  -> pause / resume multi-clip session on the same target.
; Idle  : start preferred monitor (same as Up+Left)
; Rec   : pause  -> finalize clip, keep target, show PAUSED
; Paused: resume -> new clip, same region
DKRecTogglePauseResume() {
    if DKRecChordDebounced()
        return
    global DKRecActive, DKRecPaused
    if DKRecActive {
        DKRecPause()
        return
    }
    if DKRecPaused {
        DKRecResume()
        return
    }
    ; Not in a session yet — start preferred monitor so one chord can begin a run.
    if !DKRecResolvePreferredMonitor(&x, &y, &w, &h, &label, &monIdx) {
        DKRecMessage("Screen Recorder", "Could not find preferred monitor")
        return
    }
    DKRecStart(x, y, w, h, label, monIdx)
}

; Legacy name kept so older includes / hotkeys still work.
DKRecToggleMonitorUnderMouse() {
    DKRecTogglePreferredMonitor()
}

; Down + Right  -> record the window the mouse is over (start / stop toggle)
DKRecToggleWindowUnderMouse() {
    if DKRecChordDebounced()
        return
    global DKRecActive, DKRecPaused
    if DKRecActive || DKRecPaused {
        DKRecStop(true)
        return
    }
    if !DKRecGetWindowRectUnderMouse(&x, &y, &w, &h, &title) {
        DKRecMessage("Screen Recorder", "No window under the mouse")
        return
    }
    DKRecStart(x, y, w, h, title, 0)
}

; Started from the screenshot panel buttons.
DKRecStartMonitorIndex(n) {
    global DKRecActive, DKRecPaused
    if DKRecActive || DKRecPaused {
        DKRecStop(true)
        return
    }
    if !DKRecLogicalMonitorRect(n, &x, &y, &w, &h) {
        DKRecMessage("Screen Recorder", "Could not read monitor geometry")
        return
    }
    DKRecStart(x, y, w, h, "Monitor " n, n)
}

global DKRecGui := ""

DKShowRecorderPanelFromArrows() {
    DKShowRecorderPanel()
}

DKShowRecorderPanel() {
    global DKRecGui
    if IsObject(DKRecGui) {
        try DKRecGui.Destroy()
        DKRecGui := ""
    }

    g := Gui("+AlwaysOnTop +ToolWindow", "DK Screen Recorder")
    g.BackColor := "111318"
    g.MarginX := 18
    g.MarginY := 16
    g.SetFont("s15 bold cFFFFFF", "Segoe UI")
    g.AddText("xm w500 Center", "RECORD VIDEO")
    g.SetFont("s9 norm c9AA4B2", "Segoe UI")
    g.AddText("xm y+4 w500 Center", "Uses NVENC PCI GPU. Saves to Desktop\Screen Recordings.")

    g.SetFont("s11 bold cFFFFFF", "Segoe UI")
    monitorCount := MonitorGetCount()
    buttonWidth := monitorCount >= 3 ? 156 : 242
    Loop monitorCount {
        idx := A_Index
        xopt := (idx = 1) ? "xm y+16" : "x+16 yp"
        g.AddButton(xopt " w" buttonWidth " h40", "Monitor " idx)
            .OnEvent("Click", ((n, *) => DKCloseRecGuiAndStart(n)).Bind(idx))
    }

    g.AddButton("xm y+12 w500 h40", "Cancel").OnEvent("Click", (*) => DKCloseRecGui())
    g.OnEvent("Escape", (*) => DKCloseRecGui())
    g.OnEvent("Close", (*) => DKCloseRecGui())
    DKRecGui := g
    g.Show("AutoSize Center")
}

DKCloseRecGuiAndStart(n) {
    DKCloseRecGui()
    DKRecStartMonitorIndex(n)
}

DKCloseRecGui() {
    global DKRecGui
    if IsObject(DKRecGui) {
        try DKRecGui.Destroy()
    }
    DKRecGui := ""
}

DKRecStartActiveWindow(hwnd := 0) {
    global DKRecActive, DKRecPaused
    if DKRecActive || DKRecPaused {
        DKRecStop(true)
        return
    }
    if !hwnd
        hwnd := WinExist("A")
    if !hwnd || !DKRecLogicalRectForHwnd(hwnd, &x, &y, &w, &h) {
        DKRecMessage("Screen Recorder", "No active window to record")
        return
    }
    title := ""
    try title := WinGetTitle("ahk_id " hwnd)
    DKRecStart(x, y, w, h, (title = "" ? "Window" : title), 0)
}

; ------------------------------------------------------------
; Preferred target (1080 lock)
; ------------------------------------------------------------

; Target=1080 (default) picks the monitor closest to 1920x1080 (your main
; 1080-class screen), not whatever the mouse is over.
; Target=primary  -> AHK primary monitor
; Target=under_mouse -> old mouse-under behavior
; Target=2        -> fixed monitor index (1-based, AHK order)
DKRecResolvePreferredMonitor(&x, &y, &w, &h, &label, &monIdx) {
