        mo

; DK clipboard-first screenshot panel for AutoHotkey v2.
; Nothing is written to disk. Use any app's Paste command to use the capture.

global DKShotGui := ""
global DKShotTargetHwnd := 0
global DKShotChordBusy := false
global DKShotArrowBusy := false
global DKShotArrowLast := 0

DKScreenshotChordHold() {
    global DKShotChordBusy
    if DKShotChordBusy
        return
    DKShotChordBusy := true
    started := A_TickCount
    while GetKeyState("LButton", "P") && GetKeyState("RButton", "P") {
        if (A_TickCount - started >= 1000) {
            DKShowScreenshotPanel()
            break
        }
        Sleep 25
    }
    DKShotChordBusy := false
}

DKShowScreenshotPanel() {
    global DKShotGui, DKShotTargetHwnd
    if IsObject(DKShotGui) {
        try DKShotGui.Destroy()
        DKShotGui := ""
    }

    DKShotTargetHwnd := WinExist("A")
    g := Gui("+AlwaysOnTop +ToolWindow", "DK Screenshot — Clipboard Only")
    g.BackColor := "111318"
    g.MarginX := 18
    g.MarginY := 16
    g.SetFont("s15 bold cFFFFFF", "Segoe UI")
    g.AddText("xm w500 Center", "SCREENSHOT TO CLIPBOARD")
    g.SetFont("s9 norm c9AA4B2", "Segoe UI")
    g.AddText("xm y+4 w500 Center", "Nothing is saved. Paste with Ctrl+V when ready.")

    g.SetFont("s11 bold cFFFFFF", "Segoe UI")
    g.AddButton("xm y+16 w242 h44", "Draw Rectangle").OnEvent("Click", (*) => DKShotRectangle())
    g.AddButton("x+16 yp w242 h44", "Active Window").OnEvent("Click", (*) => DKShotActiveWindow())

    monitorCount := MonitorGetCount()
    buttonWidth := monitorCount >= 3 ? 156 : 242
    Loop monitorCount {
        idx := A_Index
        xopt := (idx = 1) ? "xm y+12" : "x+16 yp"
        g.AddButton(xopt " w" buttonWidth " h40", "Monitor " idx)
            .OnEvent("Click", ((n, *) => DKShotMonitor(n)).Bind(idx))
    }

    g.AddButton("xm y+12 w242 h40", "All Monitors").OnEvent("Click", (*) => DKShotAllMonitors())
    g.AddButton("x+16 yp w242 h40", "Cancel").OnEvent("Click", (*) => DKCloseShotGui())
    g.OnEvent("Escape", (*) => DKCloseShotGui())
    g.OnEvent("Close", (*) => DKCloseShotGui())
    DKShotGui := g
    g.Show("AutoSize Center")
}

DKCloseShotGui() {
    global DKShotGui
    if IsObject(DKShotGui) {
        try DKShotGui.Destroy()
    }
    DKShotGui := ""
}

DKShotRectangle() {
    DKCloseShotGui()
    Sleep 120
    ; Windows snipping overlay returns the selected rectangle to the clipboard.
    Send "#+s"
}

DKShotActiveWindow() {
    global DKShotTargetHwnd
    hwnd := DKShotTargetHwnd
    DKCloseShotGui()
    if !hwnd || !WinExist("ahk_id " hwnd)
        return
    try WinActivate("ahk_id " hwnd)
    try WinWaitActive("ahk_id " hwnd, , 1.0)
    Sleep 100
    Send "!{PrintScreen}"
    DKShotNotice("Window copied")
}

DKShotWindowUnderMouse() {
    global DKShotArrowBusy, DKShotArrowLast
    ; Both key-order hotkeys may fire for one chord. Debounce to one capture.
    if DKShotArrowBusy || (A_TickCount - DKShotArrowLast < 350)
        return
    DKShotArrowBusy := true
    DKShotArrowLast := A_TickCount
    try {
        MouseGetPos &mouseX, &mouseY, &childHwnd
        if !childHwnd
            throw Error("No window under mouse")
        ; Convert controls/child windows to their owning top-level window.
        hwnd := DllCall("GetAncestor", "Ptr", childHwnd, "UInt", 2, "Ptr")
        if !hwnd
            hwnd := childHwnd

        ; DWM extended bounds include the real visible frame without oversized shadows.
        rect := Buffer(16, 0)
        hr := DllCall("dwmapi\DwmGetWindowAttribute", "Ptr", hwnd, "UInt", 9
            , "Ptr", rect.Ptr, "UInt", rect.Size, "Int")
        if (hr = 0) {
            left := NumGet(rect, 0, "Int"), top := NumGet(rect, 4, "Int")
            right := NumGet(rect, 8, "Int"), bottom := NumGet(rect, 12, "Int")
        } else {
            WinGetPos &left, &top, &width, &height, "ahk_id " hwnd
            right := left + width, bottom := top + height
        }
        if (right <= left || bottom <= top)
            throw Error("Window has no visible area")
        DKCopyScreenRect(left, top, right - left, bottom - top)
        DKShotNotice("Window under mouse copied")
    } catch as err {
        DKShotNotice("Window capture failed")
    }
    DKShotArrowBusy := false
}

DKShowScreenshotPanelFromArrows() {
    global DKShotArrowBusy, DKShotArrowLast
    if DKShotArrowBusy || (A_TickCount - DKShotArrowLast < 350)
        return
    DKShotArrowBusy := true
    DKShotArrowLast := A_TickCount
    DKShowScreenshotPanel()
    DKShotArrowBusy := false
}

DKShotMonitor(index) {
    DKCloseShotGui()
    try {
        MonitorGet(index, &left, &top, &right, &bottom)
        DKCopyScreenRect(left, top, right - left, bottom - top)
        DKShotNotice("Monitor " index " copied")
    } catch as err {
        DKShotNotice("Capture failed")
    }
}

DKShotAllMonitors() {
    DKCloseShotGui()
    count := MonitorGetCount()
    MonitorGet(1, &left, &top, &right, &bottom)
    Loop count {
        MonitorGet(A_Index, &l, &t, &r, &b)
        left := Min(left, l), top := Min(top, t)
        right := Max(right, r), bottom := Max(bottom, b)
    }
    try {
        DKCopyScreenRect(left, top, right - left, bottom - top)
        DKShotNotice("All monitors copied")
    } catch as err {
        DKShotNotice("Capture failed")
    }
}

DKCopyScreenRect(x, y, width, height) {
    ; Copy the selected screen rectangle as CF_BITMAP. The clipboard owns hBitmap
    ; after SetClipboardData succeeds, so it must not be deleted by this script.
    screenDC := DllCall("GetDC", "Ptr", 0, "Ptr")
    memoryDC := DllCall("CreateCompatibleDC", "Ptr", screenDC, "Ptr")
    hBitmap := DllCall("CreateCompatibleBitmap", "Ptr", screenDC, "Int", width, "Int", height, "Ptr")
    oldBitmap := DllCall("SelectObject", "Ptr", memoryDC, "Ptr", hBitmap, "Ptr")
    ok := DllCall("BitBlt", "Ptr", memoryDC, "Int", 0, "Int", 0, "Int", width, "Int", height
        , "Ptr", screenDC, "Int", x, "Int", y, "UInt", 0x40CC0020, "Int")
    DllCall("SelectObject", "Ptr", memoryDC, "Ptr", oldBitmap)
    DllCall("DeleteDC", "Ptr", memoryDC)
    DllCall("ReleaseDC", "Ptr", 0, "Ptr", screenDC)
    if !ok {
        DllCall("DeleteObject", "Ptr", hBitmap)
        throw Error("BitBlt failed")
    }

    if !DllCall("OpenClipboard", "Ptr", A_ScriptHwnd, "Int") {
        DllCall("DeleteObject", "Ptr", hBitmap)
        throw Error("Clipboard busy")
    }
    DllCall("EmptyClipboard")
    owned := DllCall("SetClipboardData", "UInt", 2, "Ptr", hBitmap, "Ptr")
    DllCall("CloseClipboard")
    if !owned {
        DllCall("DeleteObject", "Ptr", hBitmap)
        throw Error("SetClipboardData failed")
    }

    ; Also save to Desktop\Screen Recordings
    outDir := A_Desktop "\Screen Recordings"
    if !DirExist(outDir)
        DirCreate(outDir)
    outFile := outDir "\Screenshot_" FormatTime(, "yyyyMMdd_HHmmss") ".png"
    Run('cmd.exe /c `"ffmpeg -y -f gdigrab -offset_x ' x ' -offset_y ' y ' -video_size ' width 'x' height ' -i desktop -vframes 1 `"' outFile '`"`"', , "Hide")
}

DKShotNotice(message) {
    ToolTip message " — clipboard only"
    SetTimer () => ToolTip(), -1400
}

from pycaw.pycaw import AudioUtilities

# JLab render (Headphones) and capture (Headset)
RENDER_KEY = "{0.0.0.00000000}.{4d0f1ec6-32ad-4eb4-8693-06477ddc42f4}"
CAPTURE_KEY = "{0.0.1.00000000}.{3cf95cca-7042-4ce3-b23b-58da95edf768}"

render_dev = None
capture_dev = None
for d in AudioUtilities.GetAllDevices():
    idd = (d.id or '').lower()
    fn = (d.FriendlyName or '').lower()
    if 'jlab' not in fn:
        continue
    print(repr(d.FriendlyName), '|', d.id)
    if RENDER_KEY in idd:
        render_dev = d
    elif CAPTURE_KEY in idd:
        capture_dev = d

# fallback: if no capture matched but there's a jlab endpoint with 0.0.1 prefix
if not capture_dev:
    for d in AudioUtilities.GetAllDevices():
        if 'jlab' in (d.FriendlyName or '').lower() and '0.0.1.' in (d.id or '').lower():
            capture_dev = d

assert render_dev, 'No JLab render device'
print('Picking render:', render_dev.FriendlyName)
AudioUtilities.SetDefaultDevice(render_dev.id)
print('-> Playback default set to JLab')

if capture_dev:
    print('Picking capture:', capture_dev.FriendlyName)
    AudioUtilities.SetDefaultDevice(capture_dev.id)
    print('-> Capture default set to JLab')
else:
    print('(No JLab mic endpoint; capture left unchanged)')

# Audio Switcher Script
# Toggles default audio device between JLab earbuds and default PC speakers/mic

Add-Type -TypeDefinition @'
using System.Runtime.InteropServices;
[Guid("5CDF2C82-841E-4546-9722-0CF74078229A"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
interface IPolicyConfig {
    void SetDefaultEndpoint(string deviceId, int role);
}
[ComImport, Guid("233164C8-1B2C-4C8D-BC94-661F914C4A47")]
class PolicyConfigClient {}

public class AudioSwitcher {
    public static void SetDefault(string deviceId) {
        IPolicyConfig config = (IPolicyConfig)new PolicyConfigClient();
        config.SetDefaultEndpoint(deviceId, 0); // eConsole
        config.SetDefaultEndpoint(deviceId, 1); // eMultimedia
        config.SetDefaultEndpoint(deviceId, 2); // eCommunications
    }
}
'@

function Get-AudioDevices {
    $endpoints = Get-PnpDevice -Class AudioEndpoint -ErrorAction SilentlyContinue | Where-Object { $_.Status -eq 'OK' }
    return $endpoints
}

Write-Host "Audio Switcher helper ready."

# Keep Hermes TTS on the monitor. The LG TV is always on but has no
# speakers Windows can use — HDMI audio steals the default and speech
# vanishes even though Kokoro is still generating.
$nircmd = "C:\adb\nircmd.exe"
$want = "HSG1131"
$lgAudioId = "SWD\MMDEVAPI\{0.0.0.00000000}.{F423D99D-7B40-486C-B303-B3A0B58A292E}"
$log = "~\Desktop\speaker-pin.log"
$py = "~\AppData\Local\hermes\hermes-agent\venv\Scripts\python.exe"

function Get-DefaultOutName {
    try {
        & $py -c "import sounddevice as sd; print(sd.query_devices(kind='output')['name'])" 2>$null
    } catch {
        return ""
    }
}

while ($true) {
    $lg = Get-PnpDevice -InstanceId $lgAudioId -ErrorAction SilentlyContinue
    if ($lg -and $lg.Status -eq "OK") {
        try {
            Disable-PnpDevice -InstanceId $lgAudioId -Confirm:$false -ErrorAction Stop
            Add-Content -Path $log -Value ("{0} re-disabled LG TV audio endpoint" -f (Get-Date -Format o))
        } catch {
            Add-Content -Path $log -Value ("{0} could not disable LG TV audio: {1}" -f (Get-Date -Format o), $_.Exception.Message)
        }
    }

    $now = Get-DefaultOutName
    if ($now -and ($now -notmatch [regex]::Escape($want))) {
        & $nircmd setdefaultsounddevice $want 0
        & $nircmd setdefaultsounddevice $want 1
        & $nircmd setdefaultsounddevice $want 2
        Add-Content -Path $log -Value ("{0} stole default -> '{1}' ; pinned back to {2}" -f (Get-Date -Format o), $now.Trim(), $want)
    }
    Start-Sleep -Seconds 4
}

