    valves = {"default_player": "vlc", "torbox_token": "", "tmdb_token": ""}

    c = sqlite3.connect(str(DB))
    row = c.execute("SELECT id FROM tool WHERE id=?", (TOOL_ID,)).fetchone()
    if row:
        c.execute(
            """UPDATE tool SET user_id=?, name=?, content=?, specs=?, meta=?, valves=?, updated_at=?
               WHERE id=?""",
            (
                USER_ID,
                "AI Media Player",
                content,
                json.dumps(SPECS),
                json.dumps(meta),
                json.dumps(valves),
                NOW,
                TOOL_ID,
            ),
        )
        print("updated tool", TOOL_ID)
    else:
        c.execute(
