                content,
                json.dumps(SPECS),
                json.dumps(meta),
                json.dumps(valves),
                NOW,
                NOW,
            ),
        )
        print("created tool", TOOL_ID)

    # Attach to user UI defaults
    urow = c.execute("SELECT settings FROM user WHERE id=?", (USER_ID,)).fetchone()
    settings = {}
    if urow and urow[0]:
        try:
            settings = json.loads(urow[0]) if isinstance(urow[0], str) else (urow[0] or {})
        except Exception:
            settings = {}
    ui = settings.get("ui") if isinstance(settings.get("ui"), dict) else {}
    for key in ("tools", "toolIds"):
        current = ui.get(key) if isinstance(ui.get(key), list) else []
        ui[key] = list(dict.fromkeys(list(current) + [TOOL_ID]))
    settings["ui"] = ui
    current = settings.get("toolIds") if isinstance(settings.get("toolIds"), list) else []
    settings["toolIds"] = list(dict.fromkeys(list(current) + [TOOL_ID]))
    c.execute("UPDATE user SET settings=? WHERE id=?", (json.dumps(settings), USER_ID))
    print("patched user settings toolIds")

    # Keep CUA filter, but also force the media tool onto every chat
    frow = c.execute("SELECT valves FROM function WHERE id=?", ("force_cua_tools",)).fetchone()
    if frow:
        try:
            fvalves = json.loads(frow[0]) if isinstance(frow[0], str) else (frow[0] or {})
        except Exception:
            fvalves = {}
        ids = [x.strip() for x in str(fvalves.get("tool_ids") or "server:0").split(",") if x.strip()]
        if TOOL_ID not in ids:
            ids.append(TOOL_ID)
        fvalves["tool_ids"] = ",".join(ids)
        fvalves["enabled"] = True
        fvalves["force_native_fc"] = True
        c.execute(
            "UPDATE function SET valves=?, is_active=1, is_global=1, updated_at=? WHERE id=?",
            (json.dumps(fvalves), NOW, "force_cua_tools"),
        )
        print("updated force_cua_tools valves", fvalves.get("tool_ids"))

    # Attach to known workspace models
    for mid in ("brianna-desktop-deepseek", "deepseek-v4-flash-desktop"):
        mrow = c.execute("SELECT meta FROM model WHERE id=?", (mid,)).fetchone()
        if not mrow:
            continue
        try:
            meta_obj = json.loads(mrow[0]) if isinstance(mrow[0], str) else (mrow[0] or {})
        except Exception:
            meta_obj = {}
        for key in ("toolIds", "defaultToolIds"):
            current = meta_obj.get(key) if isinstance(meta_obj.get(key), list) else []
            meta_obj[key] = list(dict.fromkeys(list(current) + [TOOL_ID]))
        c.execute("UPDATE model SET meta=?, updated_at=? WHERE id=?", (json.dumps(meta_obj), NOW, mid))
        print("attached to model", mid, meta_obj.get("toolIds"))

    c.commit()
    verify = c.execute("SELECT id, name FROM tool WHERE id=?", (TOOL_ID,)).fetchone()
    print("verify", verify)
    c.close()
    print("done — reload Open WebUI Workspace > Tools if the tool does not appear immediately")


