class DATA_BLOB(ctypes.Structure):
    _fields_ = [("cbData", wintypes.DWORD), ("pbData", ctypes.POINTER(ctypes.c_byte))]


def _unprotect(value: str) -> str:
    if not value or not isinstance(value, str):
        return ""
    value = value.strip()
    if ":" not in value:
        return value
    prefix, encoded = value.split(":", 1)
    if prefix not in ("plain", "dpapi"):
        return value
    raw = base64.urlsafe_b64decode(encoded.encode("ascii"))
    if prefix == "plain":
        return raw.decode("utf-8").strip()
    buf = ctypes.create_string_buffer(raw)
    in_blob = DATA_BLOB(len(raw), ctypes.cast(buf, ctypes.POINTER(ctypes.c_byte)))
    out_blob = DATA_BLOB()
    if not ctypes.windll.crypt32.CryptUnprotectData(
        ctypes.byref(in_blob), None, None, None, None, 0, ctypes.byref(out_blob)
    ):
        raise ctypes.WinError()
    try:
        return ctypes.string_at(out_blob.pbData, out_blob.cbData).decode("utf-8").strip()
    finally:
        ctypes.windll.kernel32.LocalFree(out_blob.pbData)


def _http(
    method: str,
    url: str,
    *,
    headers: dict | None = None,
    json_body=None,
    form: dict | None = None,
    timeout: int = 45,
):
    data = None
    hdrs = {"User-Agent": "DK-AI-Media/2.0", "Accept": "application/json"}
    if headers:
        hdrs.update(headers)
    if json_body is not None:
        data = json.dumps(json_body).encode("utf-8")
        hdrs["Content-Type"] = "application/json"
    elif form is not None:
        data = urllib.parse.urlencode(form).encode("utf-8")
        hdrs["Content-Type"] = "application/x-www-form-urlencoded"
    req = urllib.request.Request(url, data=data, method=method, headers=hdrs)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as resp:
            raw = resp.read().decode("utf-8", "replace")
            return json.loads(raw) if raw.strip().startswith(("{", "[")) else {"raw": raw}
    except urllib.error.HTTPError as exc:
        raw = exc.read().decode("utf-8", "replace")
        raise RuntimeError(f"HTTP {exc.code} {url}: {raw[:300]}") from exc


def _unwrap(payload):
    if isinstance(payload, dict) and "data" in payload:
        return payload.get("data")
    return payload


def _human(n: int) -> str:
    n = float(n or 0)
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if n < 1024:
            return f"{n:.1f} {unit}"
        n /= 1024
    return f"{n:.1f} PB"


def _quality(text: str) -> str:
    t = text.lower()
    for q in ("2160p", "1080p", "720p", "480p"):
        if q in t:
            return q
    if "4k" in t or "uhd" in t:
        return "2160p"
    return "unknown"


def _rejected(text: str) -> bool:
    t = text.lower()
    return any(re.search(rf"\b{re.escape(w)}\b", t) for w in REJECT)


def _lang_penalty(text: str) -> int:
    t = text.lower()
    if re.search(r"\b(hindi|tamil|telugu|kannada|malayalam|spanish|french|german|italian|korean|japanese|chinese|russian)\b", t) and not re.search(r"\b(english|eng|en)\b", t):
        return 20
    return 0


def _parse_query(text: str) -> dict:
    raw = (text or "").strip()
    m = re.match(
        r"(?is)^\s*(?:please\s+)?(?:play|watch|put\s+on|start)\s+(.+?)\s*$",
        raw,
    )
    body = m.group(1).strip(" .!?") if m else raw
    hint = None
    if re.match(r"(?i)^(tv|show|series)\s+", body):
        hint = "tv"
        body = re.sub(r"(?i)^(tv|show|series)\s+", "", body).strip()
    elif re.match(r"(?i)^(movie|film)\s+", body):
        hint = "movie"
        body = re.sub(r"(?i)^(movie|film)\s+", "", body).strip()
    season = episode = None
    se = re.search(r"(?i)\bs(\d{1,2})\s*e(\d{1,3})\b", body)
    if se:
        season, episode = int(se.group(1)), int(se.group(2))
        body = (body[: se.start()] + body[se.end() :]).strip(" -–,")
    else:
        se2 = re.search(r"(?i)\bseason\s*(\d{1,2})\s*(?:episode|ep\.?)\s*(\d{1,3})\b", body)
        if se2:
            season, episode = int(se2.group(1)), int(se2.group(2))
            body = (body[: se2.start()] + body[se2.end() :]).strip(" -–,")
    title = re.sub(r"\s+", " ", body).strip(" \"'")
    if season or episode:
        hint = hint or "tv"
    return {
        "title": title,
        "media_hint": hint,
        "season": season or (1 if hint == "tv" else None),
        "episode": episode or (1 if hint == "tv" else None),
    }


