# Kokoro TTS Watchdog - keeps the TTS server alive
# Checks port 8880 every 60 seconds, restarts server if down.
$port = 8880
$log = "~\Kokoro-FastAPI\kf_server.log"
$err = "~\Kokoro-FastAPI\kf_server.err"
$venv = "~\Kokoro-FastAPI\.venv\Scripts\uvicorn.exe"
$wd = "~\Kokoro-FastAPI"

while ($true) {
    $conn = Test-NetConnection -ComputerName 127.0.0.1 -Port $port -WarningAction SilentlyContinue
    if (-not $conn.TcpTestSucceeded) {
        try {
            Start-Process -FilePath $venv `
                -ArgumentList 'api.src.main:app','--host','0.0.0.0','--port','8880' `
                -WorkingDirectory $wd -WindowStyle Hidden `
                -RedirectStandardOutput $log -RedirectStandardError $err
            Add-Content -Path "~\Desktop\watchdog.log" -Value "$(Get-Date) - Kokoro TTS was down, restarted."
        } catch {
            Add-Content -Path "~\Desktop\watchdog.log" -Value "$(Get-Date) - RESTART FAILED: $_"
        }
    }
    Start-Sleep -Seconds 60
}

