const NEXUS_CONTROL = "http://127.0.0.1:8792";

function nexusControl(method, route, body, timeoutMs) {
  return new Promise((resolve) => {
    const payload = body === undefined ? null : Buffer.from(JSON.stringify(body), "utf8");
    const req = http.request(
      {
        hostname: "127.0.0.1",
        port: 8792,
        path: route,
        method: method || "GET",
        headers: payload
          ? {
              "Content-Type": "application/json",
              "Content-Length": String(payload.length),
              Accept: "application/json"
            }
          : { Accept: "application/json" }
      },
      (res) => {
        const chunks = [];
        res.on("data", (c) => chunks.push(c));
        res.on("end", () => {
          const raw = Buffer.concat(chunks).toString("utf8");
          let data = {};
          try { data = raw ? JSON.parse(raw) : {}; } catch (_) {
            data = { raw };
          }
          resolve({
            ok: (res.statusCode || 0) >= 200 && (res.statusCode || 0) < 300,
            status: res.statusCode,
            ...data
          });
        });
      }
    );
    req.setTimeout(timeoutMs || 12000, () => {
      req.destroy();
      resolve({ ok: false, error: "NEXUS control timed out (is the NEXUS browser running?)" });
    });
    req.on("error", (e) =>
      resolve({ ok: false, error: String(e.message || e), offline: true })
    );
    if (payload) req.write(payload);
    req.end();
  });
}

