"use strict";

const fs = require("fs");
const http = require("http");
const path = require("path");
const { spawn } = require("child_process");

const BASE = __dirname;
const kokoroClient = require(path.join(BASE, "kokoro-client.js"));
const config = JSON.parse(
  fs.readFileSync(path.join(BASE, "brianna-gateway.json"), "utf8").replace(/^\uFEFF/, "")
);
const args = new Set(process.argv.slice(2).map((item) => item.toLowerCase()));
const gatewayBase = "http://127.0.0.1:" + config.gateway.port;
const antigravityBase =
  "http://" + config.antigravity.host + ":" + config.antigravity.port;
const lockPath = path.join(BASE, ".gateway-launcher.lock");
const servicePath = path.join(BASE, "brianna-services.json");
const logDir = path.join(BASE, "logs");

function request(method, urlString, timeout) {
  return new Promise((resolve) => {
    const url = new URL(urlString);
    const req = http.request(
      {
        hostname: url.hostname,
        port: url.port,
        path: url.pathname + url.search,
        method
      },
      (res) => {
        const chunks = [];
        res.on("data", (chunk) => chunks.push(Buffer.from(chunk)));
        res.on("end", () => {
          const raw = Buffer.concat(chunks).toString("utf8");
          let data = null;
          try { data = raw ? JSON.parse(raw) : {}; } catch (_) {}
          resolve({ ok: (res.statusCode || 0) < 400, status: res.statusCode, data });
        });
      }
    );
    req.setTimeout(timeout || 2000, () => {
      req.destroy();
      resolve({ ok: false, error: "timeout" });
    });
    req.on("error", (error) => resolve({ ok: false, error: error.message }));
    req.end();
  });
}

const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function waitFor(url, expectedService, timeoutMs) {
  const end = Date.now() + timeoutMs;
  while (Date.now() < end) {
    const result = await request("GET", url, 2500);
    if (
      result.ok &&
      (!expectedService || (result.data && result.data.service === expectedService))
    ) return result;
    await delay(500);
  }
  return { ok: false, error: "service did not become ready" };
}

function startDetached(executable, childArgs, logName) {
  fs.mkdirSync(logDir, { recursive: true });
  const out = fs.openSync(path.join(logDir, logName + ".log"), "a");
  const err = fs.openSync(path.join(logDir, logName + ".error.log"), "a");
  const child = spawn(executable, childArgs, {
    cwd: BASE,
    detached: true,
    windowsHide: true,
    stdio: ["ignore", out, err]
  });
  child.unref();
  fs.closeSync(out);
  fs.closeSync(err);
  return child.pid;
}

function savePids(update) {
  let current = {};
  try { current = JSON.parse(fs.readFileSync(servicePath, "utf8")); } catch (_) {}
  fs.writeFileSync(
    servicePath,
    JSON.stringify({ ...current, ...update, updatedAt: new Date().toISOString() }, null, 2),
    "utf8"
  );
}

function acquireLock() {
  try {
    const fd = fs.openSync(lockPath, "wx");
    fs.writeFileSync(fd, String(process.pid), "utf8");
    fs.closeSync(fd);
    return true;
  } catch (_) {
    try {
      const age = Date.now() - fs.statSync(lockPath).mtimeMs;
      if (age > 120000) {
        fs.unlinkSync(lockPath);
        return acquireLock();
      }
    } catch (_) {}
    return false;
  }
}

function releaseLock() {
  try { fs.unlinkSync(lockPath); } catch (_) {}
}

/**
 * Open the DK NEXUS dashboard Chrome app — SINGLETON.
 * Every gateway restart used to spawn another --app=http://127.0.0.1:8090 window
 * (Dell saw ~6 "DK NEXUS" copies). Dedicated profile + skip-if-running fixes that.
 */
function openDashboard() {
  const chromeCandidates = [
    "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe",
    "C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe"
  ];
  const chrome = chromeCandidates.find((candidate) => fs.existsSync(candidate));
  const url = gatewayBase;
  const profileDir = path.join(BASE, "chrome-dknexus-profile");
  try { fs.mkdirSync(profileDir, { recursive: true }); } catch (_) {}

  // If a dashboard app process is already alive, do not open another copy.
  try {
    const { execFileSync } = require("child_process");
    const check = execFileSync(
      "powershell.exe",
      [
        "-NoProfile",
        "-Command",
        "$n=0; Get-CimInstance Win32_Process -Filter \"Name='chrome.exe'\" -EA SilentlyContinue | ForEach-Object { " +
          "if ($_.CommandLine -and ($_.CommandLine -like '*chrome-dknexus-profile*' -or " +
          "($_.CommandLine -like '*--app=http://127.0.0.1:8090*' -and $_.CommandLine -notlike '*/ears*'))) { $n++ } }; " +
          "Write-Output $n"
      ],
      { windowsHide: true, timeout: 8000 }
    )
      .toString()
      .trim();
    if (Number(check) > 0) {
      console.log("DK NEXUS dashboard already open — not launching another copy.");
      return;
    }
  } catch (_) {}

  if (chrome) {
    spawn(
      chrome,
      [
        "--user-data-dir=" + profileDir,
        "--no-first-run",
        "--no-default-browser-check",
        "--app=" + url,
        "--start-maximized"
      ],
      { detached: true, windowsHide: false, stdio: "ignore" }
    ).unref();
    return;
  }
  spawn("cmd.exe", ["/d", "/c", "start", "", url], {
    detached: true,
    windowsHide: true,
    stdio: "ignore"
  }).unref();
}

