"use strict";

const fs = require("fs");
const http = require("http");
const os = require("os");
const path = require("path");
const { execFile, spawn } = require("child_process");

const BASE = __dirname;
const CONFIG_PATH = path.join(BASE, "brianna-gateway.json");
let startPromise = null;

function readConfig(config) {
  if (config) return config;
  return JSON.parse(fs.readFileSync(CONFIG_PATH, "utf8").replace(/^\uFEFF/, ""));
}

function ttsConfig(config) {
  const root = readConfig(config);
  const cfg = root.tts || {};
  return {
    enabled: cfg.enabled !== false,
    host: String(cfg.host || "127.0.0.1"),
    port: Number(cfg.port || 8092),
    python: String(cfg.python || ""),
    script: String(cfg.script || ""),
    model: String(cfg.model || ""),
    voices: String(cfg.voices || ""),
    defaultVoice: String(cfg.default_voice || "af_heart"),
    speed: Number(cfg.speed || 1.0),
    wakeTimeoutMs: Number(cfg.wake_timeout_ms || 20000),
    playScript: String(cfg.play_script || path.join(BASE, "play-wav.ps1"))
  };
}

function request(method, route, options) {
  const opts = options || {};
  const cfg = ttsConfig(opts.config);
  const payload = opts.body === undefined
    ? null
    : Buffer.from(JSON.stringify(opts.body), "utf8");
  return new Promise((resolve, reject) => {
    const req = http.request(
      {
        hostname: cfg.host,
        port: cfg.port,
        path: route,
        method,
        headers: payload
          ? {
              Accept: opts.accept || "application/json",
              "Content-Type": "application/json",
              "Content-Length": String(payload.length)
            }
          : { Accept: opts.accept || "application/json" }
      },
      (res) => {
        const chunks = [];
        let size = 0;
        res.on("data", (chunk) => {
          size += chunk.length;
          if (size > (opts.maxBytes || 20_000_000)) {
            req.destroy(new Error("Kokoro response exceeded safety limit"));
            return;
          }
          chunks.push(Buffer.from(chunk));
        });
        res.on("end", () => {
          const data = Buffer.concat(chunks);
          if ((res.statusCode || 0) >= 200 && (res.statusCode || 0) < 300) {
            return resolve({
              ok: true,
              status: res.statusCode,
              contentType: String(res.headers["content-type"] || ""),
              data
            });
          }
          let message = "Kokoro HTTP " + res.statusCode;
          try {
            const parsed = JSON.parse(data.toString("utf8"));
            message = String(parsed.error || message);
          } catch (_) {}
          const error = new Error(message);
          error.status = res.statusCode;
          reject(error);
        });
      }
    );
    req.setTimeout(opts.timeoutMs || 10000, () => {
      req.destroy(new Error("Kokoro request timed out"));
    });
    req.on("error", reject);
    if (payload) req.write(payload);
    req.end();
  });
}

async function health(config, timeoutMs) {
  try {
    const response = await request("GET", "/health", {
      config,
      timeoutMs: timeoutMs || 1500,
      maxBytes: 100_000
    });
    const data = JSON.parse(response.data.toString("utf8"));
    return {
      ok: Boolean(data && data.ok && data.service === "brianna-kokoro-tts"),
      ...data
    };
  } catch (error) {
    return { ok: false, ready: false, error: String(error.message || error) };
  }
}

const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

async function waitForReady(config, timeoutMs) {
  const end = Date.now() + timeoutMs;
  let last = null;
  while (Date.now() < end) {
    last = await health(config, 1500);
    if (last.ok) return last;
    await delay(250);
  }
  return last || { ok: false, error: "Kokoro did not become ready" };
}

async function start(config) {
  const cfg = ttsConfig(config);
  if (!cfg.enabled) throw new Error("Kokoro service is disabled");
  const current = await health(config);
  if (current.ok) return { ...current, changed: false };
  if (!cfg.python || !fs.existsSync(cfg.python)) {
    throw new Error("Kokoro Python is missing: " + cfg.python);
  }
  if (!cfg.script || !fs.existsSync(cfg.script)) {
    throw new Error("Kokoro service script is missing: " + cfg.script);
  }

  fs.mkdirSync(path.join(BASE, "logs"), { recursive: true });
  const stdout = fs.openSync(path.join(BASE, "logs", "kokoro-tts.log"), "a");
  const stderr = fs.openSync(path.join(BASE, "logs", "kokoro-tts.error.log"), "a");
  const args = [
    cfg.script,
    "--host", cfg.host,
    "--port", String(cfg.port)
  ];
  if (cfg.model) args.push("--model", cfg.model);
  if (cfg.voices) args.push("--voices", cfg.voices);
  const child = spawn(cfg.python, args, {
    cwd: path.dirname(cfg.script),
    detached: true,
    windowsHide: true,
    stdio: ["ignore", stdout, stderr]
  });
  child.unref();
  fs.closeSync(stdout);
  fs.closeSync(stderr);

  const ready = await waitForReady(config, cfg.wakeTimeoutMs);
  if (!ready.ok) {
    throw new Error(ready.error || "Kokoro service failed to start");
  }
  return { ...ready, changed: true, spawnedPid: child.pid };
}

async function ensureReady(config) {
  const cfg = ttsConfig(config);
  if (!cfg.enabled) {
    return { ok: false, ready: false, changed: false, disabled: true, error: "Kokoro service is disabled" };
  }
  const current = await health(config);
  if (current.ok) return { ...current, changed: false };
  if (!startPromise) {
    startPromise = start(config).finally(() => {
      startPromise = null;
    });
  }
  return startPromise;
}

async function synthesize(text, options) {
  const opts = options || {};
  const config = opts.config;
  const cfg = ttsConfig(config);
  const clean = String(text || "").trim().slice(0, 4000);
  if (!clean) return { ok: false, error: "Nothing to say" };
  try {
    const ready = await ensureReady(config);
    const started = Date.now();
    const response = await request("POST", "/synthesize", {
      config,
      timeoutMs: opts.timeoutMs || 90000,
      accept: "audio/wav",
      maxBytes: 20_000_000,
      body: {
        text: clean,
        voice: String(opts.voice || cfg.defaultVoice),
        speed: Number(opts.speed || cfg.speed)
      }
    });
    if (response.data.length < 500) throw new Error("Kokoro returned empty audio");
    return {
      ok: true,
      audio: response.data,
      mime: "audio/wav",
      engine: "kokoro-service",
      voice: String(opts.voice || cfg.defaultVoice),
      speed: Number(opts.speed || cfg.speed),
      serviceStarted: ready.changed === true,
      synthesisMs: Date.now() - started
    };
  } catch (error) {
    return { ok: false, error: String(error.message || error) };
  }
}

async function shutdown(config, reason) {
  const before = await health(config);
  if (!before.ok) return { ok: true, changed: false, state: "sleeping" };
  try {
    await request("POST", "/shutdown", {
      config,
      timeoutMs: 3000,
      maxBytes: 100_000,
      body: { reason: String(reason || "requested").slice(0, 100) }
    });
    return { ok: true, changed: true, state: "sleeping", pid: before.pid };
  } catch (error) {
    return {
      ok: false,
      busy: Number(error.status) === 409,
      error: String(error.message || error)
    };
  }
}

