        [pscustomobject]@{ win = $_; score = ($n + $bonus) }
      } | Where-Object { $_.score -gt 0 } | Sort-Object score -Descending
      if ($scored) { $hit = $scored[0].win }
    }
  }

  if (-not $hit) {
    @{
      ok = $false
      error = "No open window matching '$Title'."
      hint = "Pick one of openWindows below by its real title and call window_move again. Do not use a shell command for this."
      openWindows = @($all | Where-Object { $_.x -gt -30000 } | ForEach-Object { $_.title })
    } | ConvertTo-Json -Depth 4 -Compress
    exit 1
  }

  $m = $mons[$Monitor]
  $hwnd = [IntPtr]$hit.handle

  # Restore first if minimized, or the move lands on an invisible window.
  if ($hit.minimized) { [void][WinCtl]::ShowWindow($hwnd, 9) }  # SW_RESTORE
  # Exit maximized state so SetWindowPos can place on a single monitor
  [void][WinCtl]::ShowWindow($hwnd, 9)  # SW_RESTORE

  if ($Fill) {
    # Entire monitor (slight inset avoids multi-monitor edge bleed)
    $pad = 0
    $x = $m.x + $pad
    $y = $m.y + $pad
    $w = $m.w - (2 * $pad)
    $h = $m.h - (2 * $pad)
  } elseif ($TopLeft) {
    # Keep the window's size, but place it at the top left
    $w = [Math]::Min($hit.w, $m.w)
    $h = [Math]::Min($hit.h, $m.h)
    if ($hit.w -gt $m.w - 40) { $w = $m.w - 40; $h = [Math]::Min($hit.h, $m.h - 40) }
    $x = $m.x
    $y = $m.y
  } else {
    # Keep the window's size; centre it on the target monitor.
    $w = [Math]::Min($hit.w, $m.w)
    $h = [Math]::Min($hit.h, $m.h)
    # If window is wider than one monitor, force single-monitor width
    if ($hit.w -gt $m.w - 40) { $w = $m.w - 40; $h = [Math]::Min($hit.h, $m.h - 40) }
    $x = $m.x + [int](($m.w - $w) / 2)
    $y = $m.y + [int](($m.h - $h) / 2)
  }

  # SWP_NOACTIVATE (0x0010) | SWP_NOZORDER (0x0004) — move without stealing focus.
  $moved = [WinCtl]::SetWindowPos($hwnd, [IntPtr]::Zero, $x, $y, $w, $h, 0x0014)
  if ($Fill -and $moved) {
    # Maximize on that monitor after placement
    [void][WinCtl]::ShowWindow($hwnd, 3)  # SW_MAXIMIZE
  }

  @{
    ok = [bool]$moved
    window = $hit.title
    monitor = $Monitor
    filled = [bool]$Fill
    placedAt = "$x,$y ${w}x${h}"
  } | ConvertTo-Json -Compress
  exit 0
}

@{ ok = $false; error = "Unknown action '$Action'. Use list or move." } | ConvertTo-Json -Compress

