"""
Brianna push-to-talk hotkey (Alexa-button style).

Default: F8
  1) Pauses media (show/TV audio quiet so she can hear you)
  2) Arms high-sensitivity listen for ~12s
  3) Short spoken ack ("Yeah?") so you know she's ready

Run at login / with Brianna start:
  python brianna-ptt-hotkey.py
"""
from __future__ import annotations

import json
import os
import sys
import time
import urllib.error
import urllib.request

BASE = os.path.dirname(os.path.abspath(__file__))
LOG = os.path.join(BASE, "logs", "brianna-ptt-hotkey.log")
PID_FILE = os.path.join(BASE, "brianna-ptt-hotkey.pid")
# Change with env BRIANNA_PTT_KEY e.g. f8, f9, pause, ctrl+shift+b
HOTKEY = (os.environ.get("BRIANNA_PTT_KEY") or "f8").strip().lower()
GATEWAY = "http://127.0.0.1:8090"


def log(msg: str) -> None:
    line = time.strftime("%Y-%m-%d %H:%M:%S") + " " + str(msg)
    try:
        os.makedirs(os.path.dirname(LOG), exist_ok=True)
        with open(LOG, "a", encoding="utf-8") as f:
            f.write(line + "\n")
    except Exception:
        pass
    print(line, flush=True)


def post_ptt() -> dict:
    url = GATEWAY.rstrip("/") + "/ptt"
    body = json.dumps({"source": "hotkey", "key": HOTKEY}).encode("utf-8")
    req = urllib.request.Request(
        url, data=body, headers={"Content-Type": "application/json"}, method="POST"
    )
    try:
        with urllib.request.urlopen(req, timeout=8) as resp:
            raw = resp.read().decode("utf-8", errors="replace")
            try:
                return json.loads(raw)
            except Exception:
                return {"ok": True, "raw": raw}
    except urllib.error.HTTPError as e:
        return {"ok": False, "error": f"HTTP {e.code}: {e.read()[:200]}"}
    except Exception as e:
        return {"ok": False, "error": str(e)}


def main() -> int:
    try:
        with open(PID_FILE, "w", encoding="ascii") as f:
            f.write(str(os.getpid()))
    except Exception:
        pass

    try:
        from pynput import keyboard
    except ImportError:
        log("ERROR: pynput missing — pip install pynput")
        return 2

    # Map simple names to pynput keys
    special = {
        "f8": keyboard.Key.f8,
        "f9": keyboard.Key.f9,
        "f10": keyboard.Key.f10,
        "f7": keyboard.Key.f7,
        "pause": keyboard.Key.pause,
        "scroll_lock": keyboard.Key.scroll_lock,
    }
    if HOTKEY not in special and not HOTKEY.startswith("ctrl"):
        log(f"unknown key {HOTKEY!r}, using f8")
        key_target = keyboard.Key.f8
        key_label = "F8"
    elif HOTKEY in special:
        key_target = special[HOTKEY]
        key_label = HOTKEY.upper()
    else:
        key_target = keyboard.Key.f8
        key_label = "F8"

    busy = {"t": 0.0}

    def fire():
        now = time.time()
        if now - busy["t"] < 0.8:
            return  # debounce
        busy["t"] = now
        log(f"PTT {key_label} → pause + arm speech")
        result = post_ptt()
        if result.get("ok"):
            log(
                f"armed until {result.get('armedUntil')} pause={result.get('paused')} "
                f"speak={result.get('spoken', {}).get('ok')}"
            )
        else:
            log(f"PTT failed: {result.get('error')}")

    def on_press(key):
        try:
            if key == key_target:
                fire()
        except Exception as e:
            log(f"on_press error: {e}")

    log(f"Brianna PTT hotkey listening: {key_label} (pause media + talk to her)")
    log("Keep this process running in the background.")
    with keyboard.Listener(on_press=on_press) as listener:
        listener.join()
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main() or 0)
    finally:
        try:
            if os.path.exists(PID_FILE):
                os.remove(PID_FILE)
        except Exception:
            pass

import time, numpy as np
import pyaudiowpatch as pyaudio

# Try pycaw for volume
try:
    from comtypes import CLSCTX_ALL
    from pycaw.pycaw import AudioUtilities, IAudioEndpointVolume, ISimpleAudioVolume
    print("pycaw ok")
    devices = AudioUtilities.GetAllDevices()
    for d in devices:
        try:
            name = d.FriendlyName or ""
            if d.state and "Microphone" in str(getattr(d, "data_flow", "")) or True:
                pass
            print("DEV", name, "id", getattr(d, "id", None))
        except Exception as e:
            print("dev err", e)
except Exception as e:
    print("pycaw fail", e)

p = pyaudio.PyAudio()
wasapi = p.get_host_api_info_by_type(pyaudio.paWASAPI)["index"]
print("default in:", p.get_default_input_device_info())

cands = []
for i in range(p.get_device_count()):
    info = p.get_device_info_by_index(i)
    if info.get("hostApi") != wasapi: continue
    if info.get("maxInputChannels", 0) <= 0: continue
    if info.get("isLoopbackDevice"): continue
    cands.append((i, info.get("name"), int(info.get("maxInputChannels")), int(info.get("defaultSampleRate",0))))

print("INPUTS:")
for c in cands:
    print(" ", c)

def measure(idx, ch, rate=48000, secs=1.2):
    try:
        s = p.open(format=pyaudio.paInt16, channels=ch, rate=rate, input=True, input_device_index=idx, frames_per_buffer=960)
    except Exception as e:
        return f"open fail {e}"
    vals=[]
    t_end=time.time()+secs
    while time.time()<t_end:
        raw=s.read(960, exception_on_overflow=False)
        x=np.frombuffer(raw,dtype=np.int16).astype(np.float32)/32768.0
        if ch>1:
            n=(len(x)//ch)*ch
            x=x[:n].reshape(-1,ch)
            # per channel
            for c in range(ch):
                vals.append(float(np.sqrt(np.mean(x[:,c]**2)+1e-12)))
        else:
            vals.append(float(np.sqrt(np.mean(x**2)+1e-12)))
    s.close()
    a=np.array(vals)
    return f"mean={a.mean():.6f} p95={np.percentile(a,95):.6f} max={a.max():.6f}"

for i,name,ch,rate in cands:
    # try 48k stereo/mono
    for try_ch in ([1,2] if ch>=2 else [1]):
        for try_rate in [48000, 16000, int(rate) or 48000]:
            try:
                r = measure(i, try_ch, try_rate, 0.8)
                print(f"[{i}] ch={try_ch} rate={try_rate} {name}: {r}")
                break
            except Exception as e:
                print(f"[{i}] ch={try_ch} rate={try_rate} FAIL {e}")
