# Brianna ears — always the live gateway mic UI (never dead NEXUS :8791).
# Safe to call multiple times: reuses healthy window, replaces dead/wrong ones.
param(
  [string]$EarsUrl = "http://127.0.0.1:8090/ears",
  [string]$ProfileDir = "~\AppData\Local\NEXUS_Automation_Browser\chrome-ears-profile",
  [int]$WaitSeconds = 45
)

$ErrorActionPreference = "Continue"

function Test-EarsHealthy {
  try {
    $r = Invoke-WebRequest -Uri $EarsUrl -UseBasicParsing -TimeoutSec 2
    return ($r.StatusCode -ge 200 -and $r.StatusCode -lt 400)
  } catch {
    return $false
  }
}

function Get-EarsChromePids {
  Get-CimInstance Win32_Process -ErrorAction SilentlyContinue | Where-Object {
    $_.Name -eq "chrome.exe" -and
    $_.CommandLine -and
    $_.CommandLine -match "chrome-ears-profile"
  }
}

# Wait for gateway /ears
$deadline = (Get-Date).AddSeconds($WaitSeconds)
while ((Get-Date) -lt $deadline) {
  if (Test-EarsHealthy) { break }
  Start-Sleep -Milliseconds 400
}
if (-not (Test-EarsHealthy)) {
  Write-Host "ears: gateway not serving $EarsUrl yet"
  exit 1
}

# Close ears windows pointed at the dead :8791 (or missing /ears)
$toKill = @()
foreach ($p in Get-EarsChromePids) {
  $cmd = [string]$p.CommandLine
  $good = ($cmd -match "8090/ears") -or ($cmd -match "8090/ears'")
  $bad = ($cmd -match "8791") -or (-not $good -and $cmd -match "app=http")
  if ($bad -or -not $good) {
    $toKill += $p.ProcessId
  }
}
# If we already have a correct ears app process, keep it
$hasGood = $false
foreach ($p in Get-EarsChromePids) {
  if ([string]$p.CommandLine -match "8090/ears") { $hasGood = $true; break }
}
if ($hasGood) {
  Write-Host "ears: already on $EarsUrl"
  exit 0
}

foreach ($id in ($toKill | Select-Object -Unique)) {
  Stop-Process -Id $id -Force -ErrorAction SilentlyContinue
}

$chrome = @(
  "C:\Program Files\Google\Chrome\Application\chrome.exe",
  "C:\Program Files (x86)\Google\Chrome\Application\chrome.exe"
) | Where-Object { Test-Path $_ } | Select-Object -First 1

if (-not $chrome) {
  Write-Host "ears: Chrome missing"
  exit 2
}

New-Item -ItemType Directory -Path $ProfileDir -Force | Out-Null
# Status-only UI (Windows AEC does real listening). Do NOT pass:
#   --unsafely-treat-insecure-origin-as-secure  → yellow "unsupported command-line flag" bar
#   --use-fake-ui-for-media-stream              → same class of warning; not needed without Chrome mic
$args = @(
  "--user-data-dir=$ProfileDir",
  "--no-first-run",
  "--no-default-browser-check",
  "--disable-features=InfiniteSessionRestore",
  "--app=$EarsUrl",
  "--window-size=460,560",
  "--window-position=60,60"
)
Start-Process -FilePath $chrome -ArgumentList $args
Write-Host "ears: opened $EarsUrl"
exit 0

