"use strict";
const params=new URLSearchParams(location.search),ticket=params.get("ticket")||"",title=params.get("title")||"Mini Player",container=params.get("container")||"",space=params.get("space")||"",provider=params.get("provider")||"",windowId=params.get("window_id")||`${Date.now()}-${Math.random().toString(36).slice(2,9)}`;
const video=document.querySelector("#video"),status=document.querySelector("#status"),message=document.querySelector("#message"),pinButton=document.querySelector("#pinTop");
document.title=`[AIO-MINI:${windowId}] Dell's AIO — ${title}`;document.querySelector("#title").textContent=title;document.querySelector("#container").textContent=container;document.querySelector("#source").textContent=`${provider.toUpperCase()} · ${space.toUpperCase()}`;
const channel=("BroadcastChannel" in window)?new BroadcastChannel("dells-aio-control"):null;
let pinned=true;
async function post(event,extra={}){if(!ticket)return;try{await fetch("/api/player/event",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({event,ticket,position:video.currentTime||0,duration:video.duration||0,...extra})})}catch{}}
async function setPinned(value,retry=true){pinned=!!value;pinButton.textContent=pinned?"Pinned on top":"Pin on top";pinButton.classList.toggle("active",pinned);try{const r=await fetch("/api/window/topmost",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({window_id:windowId,pinned})});const data=await r.json();if(retry&&(!data.windows_updated)){setTimeout(()=>setPinned(pinned,false),650)}}catch{status.textContent="Could not change always-on-top state."}}
const resumePosition=parseFloat(params.get("resume")||"0");
const nextEpisodeStr=params.get("next_episode");
let nextEpisode=null;
try{ if(nextEpisodeStr) nextEpisode=JSON.parse(nextEpisodeStr); }catch{}

if(ticket){
  video.src=`/api/stream/${encodeURIComponent(ticket)}`;
  video.load();
  if(resumePosition > 0) {
    video.currentTime = resumePosition;
  }
  video.play().catch(()=>{status.textContent="Press Play to begin."});
}else{
  message.textContent="No stream ticket was supplied.";
  status.textContent="Cannot play";
}
video.addEventListener("playing",()=>{message.style.display="none";status.textContent="Playing";post("playing")});
video.addEventListener("pause",()=>{if(!video.ended){status.textContent="Paused";post("pause")}});
video.addEventListener("waiting",()=>{status.textContent="Buffering…";post("waiting")});
video.addEventListener("ended",()=>{
  status.textContent="Finished";
  post("ended");
  if(nextEpisode) {
    // Backend episode objects use season_number/episode_number; also accept short keys.
    const showId = nextEpisode.tmdb_id || nextEpisode.show_id || params.get("tmdb_id") || "";
    const season = nextEpisode.season_number ?? nextEpisode.season;
    const episode = nextEpisode.episode_number ?? nextEpisode.episode;
    if(!showId || season == null || episode == null){
      status.textContent="Next episode data incomplete.";
      return;
    }
    status.textContent="Loading next episode...";
    setTimeout(() => {
      fetch("/api/catalog/play", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          media_type: "tv",
          tmdb_id: String(showId),
          season: Number(season),
          episode: Number(episode)
        })
      }).then(r=>r.json()).then(data => {
        if(data.ok && data.ticket) {
          const newParams = new URLSearchParams(location.search);
          newParams.set("ticket", data.ticket);
          newParams.set("title", data.title || "");
          newParams.set("container", data.container_title || "");
          newParams.set("tmdb_id", String((data.catalog && data.catalog.tmdb_id) || showId));
          if(data.resume_position) newParams.set("resume", data.resume_position);
          else newParams.delete("resume");
          if(data.next_episode){
            const ne = Object.assign({}, data.next_episode, {
              tmdb_id: (data.next_episode.tmdb_id || (data.catalog && data.catalog.tmdb_id) || showId)
            });
            newParams.set("next_episode", JSON.stringify(ne));
          } else newParams.delete("next_episode");
          location.search = newParams.toString();
        } else {
          status.textContent = (data && data.error) || "No next episode found.";
        }
      }).catch(err => {
        status.textContent="Error playing next episode.";
      });
    }, 2000);
  }
});
video.addEventListener("error",()=>{message.style.display="grid";message.textContent="This mini player could not decode the stream (often MKV/x265). Close this window and use Open externally (VLC) on the main player.";status.textContent="Playback error";post("error",{error:"Compact browser player could not decode stream."});if(ticket){fetch("/api/player/external",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({ticket})}).catch(()=>{})}});
setInterval(()=>{if(!video.paused&&!video.ended)post("time")},5000);
document.querySelector("#closeWindow").onclick=()=>window.close();
document.querySelector("#mute").onclick=e=>{video.muted=!video.muted;e.currentTarget.textContent=video.muted?"Unmute":"Mute"};
pinButton.onclick=()=>setPinned(!pinned);
channel?.addEventListener("message",e=>{if(e.data?.type==="stop-all"){video.pause();video.removeAttribute("src");video.load();window.close()}});
window.addEventListener("beforeunload",()=>post("stopped"));
setTimeout(()=>setPinned(true,true),250);

/* ── TV mode, added 2026-07-26 ───────────────────────────────────────────
   Two things were missing for actually watching something:
   1. the window forgot its size every time, so it reopened tiny;
   2. the header and footer sat on screen permanently, which is the "giant UI"
      problem in miniature.
   Geometry is now saved to localStorage (shared with the opener, same origin)
   and the chrome fades out after two idle seconds, returning on mouse move. */

function saveGeometry(){
  try{
    localStorage.setItem("dkPopoutGeometry", JSON.stringify({
      w: Math.max(320, window.outerWidth  || 960),
      h: Math.max(200, window.outerHeight || 540),
      x: Math.max(0,   window.screenX     || 0),
      y: Math.max(0,   window.screenY     || 0)
    }));
  }catch{}
}
let geoTimer=null;
window.addEventListener("resize",()=>{clearTimeout(geoTimer);geoTimer=setTimeout(saveGeometry,400)});
window.addEventListener("beforeunload",saveGeometry);
setInterval(saveGeometry,5000);   // also catches a window that was only moved

let idleTimer=null;
function showChrome(){
  document.body.classList.remove("chrome-hidden");
  clearTimeout(idleTimer);
  idleTimer=setTimeout(()=>{
    // Never hide while paused - you want the controls when you've stopped.
    if(!video.paused && !video.ended) document.body.classList.add("chrome-hidden");
  },2000);
}
["mousemove","mousedown","keydown","touchstart"].forEach(ev=>
  window.addEventListener(ev,showChrome,{passive:true}));
video.addEventListener("pause",()=>{document.body.classList.remove("chrome-hidden");clearTimeout(idleTimer)});
video.addEventListener("playing",showChrome);
showChrome();

// Double-click the picture for real fullscreen; Esc leaves as usual.
video.addEventListener("dblclick",()=>{
  if(document.fullscreenElement) document.exitFullscreen().catch(()=>{});
  else document.documentElement.requestFullscreen().catch(()=>{});
});

// F = fullscreen, Space = play/pause, M = mute.
window.addEventListener("keydown",e=>{
  const k=e.key.toLowerCase();
  if(k==="f"){e.preventDefault();video.dispatchEvent(new Event("dblclick"))}
  else if(k===" "){e.preventDefault();video.paused?video.play():video.pause()}
  else if(k==="m"){e.preventDefault();video.muted=!video.muted;
    document.querySelector("#mute").textContent=video.muted?"Unmute":"Mute"}
});

// Brianna voice fullscreen via AIO event bus
let __popEvtSince=0;
async function pollFullscreenEvents(){
  tr

# Brianna — cast / project the current PC screen
# Actions: connect | clone | extend | external | pc | stop
# Before cast: press HOME twice on the living-room TV (ADB) so Nest cam / apps
# don't block cast or mirror.
param(
  [ValidateSet("connect", "clone", "extend", "external", "pc", "stop", "status")]
  [string]$Action = "connect",
  [switch]$SkipHome
)

$ErrorActionPreference = "Continue"

function Get-TvSerial {
  $default = "192.168.1.157:5555"
  $cfgPath = "~\Desktop\Automation Creation Station\_System_Core\Active Scripts\Python Scripts\Cromcast_remote\remote_config.json"
  try {
    if (Test-Path $cfgPath) {
      $cfg = Get-Content -Raw $cfgPath | ConvertFrom-Json
      if ($cfg.last_ip) {
        $ip = [string]$cfg.last_ip
        if ($ip -match ':') { return $ip }
        return ($ip + ":5555")
      }
    }
  } catch {}
  return $default
}

function Find-Adb {
  foreach ($c in @(
    "C:\adb\adb.exe",
    "~\AppData\Local\Android\Sdk\platform-tools\adb.exe"
  )) {
    if (Test-Path $c) { return $c }
  }
  $w = Get-Command adb -ErrorAction SilentlyContinue
  if ($w) { return $w.Source }
  return $null
}

function Send-TvHomeKeys {
  # Nest cam / Google Home full-screen often blocks cast until back on launcher.
  # Dell: hit Home a couple of times before cast.
  param([int]$Times = 2, [int]$GapMs = 700)
  $adb = Find-Adb
  if (-not $adb) {
    return @{ ok = $false; skipped = $true; reason = "adb not found" }
  }
  $serial = Get-TvSerial
  try {
    & $adb connect $serial 2>$null | Out-Null
    Start-Sleep -Milliseconds 300
  } catch {}
  $sent = 0
  for ($i = 0; $i -lt $Times; $i++) {
    # KEYCODE_HOME = 3
    $null = & $adb -s $serial shell input keyevent 3 2>&1
    if ($LASTEXITCODE -eq 0) { $sent++ }
    Start-Sleep -Milliseconds $GapMs
  }
  # Brief settle so cast stack can attach
  Start-Sleep -Milliseconds 500
  return @{
    ok     = ($sent -gt 0)
    sent   = $sent
    serial = $serial
    reason = if ($sent -gt 0) { "home x$sent" } else { "adb home failed" }
  }
}

function Get-DisplaySummary {
  Add-Type -AssemblyName System.Windows.Forms -ErrorAction SilentlyContinue
  $screens = [System.Windows.Forms.Screen]::AllScreens
  $list = @()
  $i = 0
  foreach ($s in $screens) {
    $list += [PSCustomObject]@{
      index   = $i
      primary = $s.Primary
      width   = $s.Bounds.Width
      height  = $s.Bounds.Height
      x       = $s.Bounds.X
      y       = $s.Bounds.Y
      device  = $s.DeviceName
    }
    $i++
  }
  return $list
}

function Open-ConnectFlyout {
  # Win+K — Windows Connect / cast UI (pick TV / wireless display)
  $src = @'
using System;
using System.Runtime.InteropServices;
public static class BriannaWinK {
  [DllImport("user32.dll")]
  public static extern void keybd_event(byte bVk, byte bScan, uint dwFlags, UIntPtr dwExtraInfo);
  const int KEYEVENTF_KEYUP = 0x0002;
  const byte VK_LWIN = 0x5B;
  const byte VK_K = 0x4B;
  public static void Press() {
    keybd_event(VK_LWIN, 0, 0, UIntPtr.Zero);
    keybd_event(VK_K, 0, 0, UIntPtr.Zero);
    keybd_event(VK_K, 0, KEYEVENTF_KEYUP, UIntPtr.Zero);
    keybd_event(VK_LWIN, 0, KEYEVENTF_KEYUP, UIntPtr.Zero);
  }
}
'@
  try {
    if (-not ("BriannaWinK" -as [type])) { Add-Type -TypeDefinition $src -ErrorAction Stop }
    [BriannaWinK]::Press()
    return @{ ok = $true; method = "win+k" }
  } catch {
    # Fallback: project settings page
    try {
      Start-Process "ms-settings:project"
      return @{ ok = $true; method = "ms-settings:project" }
    } catch {
      return @{ ok = $false; error = $_.Exception.Message }
    }
  }
}

function Invoke-DisplaySwitch([string]$mode) {
  # /internal = PC only, /clone = duplicate, /extend, /external = second only
  $exe = "$env:SystemRoot\System32\DisplaySwitch.exe"
  if (-not (Test-Path $exe)) { return @{ ok = $false; error = "DisplaySwitch.exe missing" } }
  Start-Process -FilePath $exe -ArgumentList $mode -WindowStyle Hidden
  Start-Sleep -Milliseconds 800
  return @{ ok = $true; mode = $mode }
}

$displays = @(Get-DisplaySummary)
$count = $displays.Count

$result = [ordered]@{
  ok       = $true
  action   = $Action
  displays = $count
  monitors = $displays
  tvHome   = $null
}

# Leave Nest cam / apps before cast or connect (not needed for stop/status/pc)
$needsHome = ($Action -in @("connect", "clone", "extend", "external")) -and (-not $SkipHome)
if ($needsHome) {
  $result.tvHome = Send-TvHomeKeys -Times 2 -GapMs 750
}

switch ($Action) {
  "status" {
    $result.message = if ($count -gt 1) {
      "You have $count displays. LG TV is usually the second one for casting/mirror."
    } else {
      "Only one display is active. Use connect (Win+K) to cast wirelessly."
    }
  }
  "connect" {
    $fly = Open-ConnectFlyout
    $result.ok = [bool]$fly.ok
    $result.method = $fly.method
    $homeNote = if ($result.tvHome -and $result.tvHome.ok) { " Hit Home on the TV first." } else { "" }
    $result.message = if ($fly.ok) {
      "Opened Windows Connect — pick your TV or cast device." + $homeNote
    } else {
      "Could not open Connect: $($fly.error)"
    }
    if (-not $fly.ok) { $result.error = $fly.error }
  }
  "clone" {
    # Duplicate current screen onto all displays (true "cast what I see")
    $homeBit = if ($result.tvHome -and $result.tvHome.ok) {
      " (left Nest/apps with Home x$($result.tvHome.sent))"
    } elseif ($result.tvHome -and $result.tvHome.skipped) {
      ""
    } elseif ($result.tvHome) {
      " (could not send Home to TV — if Nest cam is up, press Home twice on the remote first)"
    } else { "" }

    if ($count -lt 2) {
      $fly = Open-ConnectFlyout
      $result.ok = [bool]$fly.ok
      $result.fallback = "connect"
      $result.message = "Only one display is connected, so I opened Cast/Connect instead. Pick the TV." + $homeBit
    } else {
      $sw = Invoke-DisplaySwitch "/clone"
      $result.ok = [bool]$sw.ok
      $result.message = if ($sw.ok) {
        "Mirroring your screen to the TV (duplicate display)." + $homeBit
      } else {
        "Clone failed: $($sw.error)"
      }
      if (-not $sw.ok) { $result.error = $sw.error }
    }
  }
  "extend" {
    $sw = Invoke-DisplaySwitch "/extend"
    $result.ok = [bool]$sw.ok
    $result.message = if ($sw.ok) { "Displays extended — desktop spans PC and TV." } else { $sw.error }
  }
  "external" {
    $sw = Invoke-DisplaySwitch "/external"
    $result.ok = [bool]$sw.ok
    $result.message = if ($sw.ok) { "Using second display only." } else { $sw.error }
  }
  "pc" {
    $sw = Invoke-DisplaySwitch "/internal"
    $result.ok = [bool]$sw.ok
    $result.message = if ($sw.ok) { "Back to this PC only — casting stopped." } else { $sw.error }
  }
  "stop" {
    # Prefer extend (keep TV usable) then connect UI not needed
    if ($count -ge 2) {
      $sw = Invoke-DisplaySwitch "/extend"
      $result.ok = [bool]$sw.ok
      $result.message = if ($sw.ok) {
        "Stopped mirror mode — back to extended displays."
      } else { $sw.error }
    } else {
      $sw = Invoke-DisplaySwitch "/internal"
      $result.ok = [bool]$sw.ok
      $result.message = if ($sw.ok) { "Casting stopped — PC screen only." } else { $sw.error }
    }
  }
}

$result | ConvertTo-Json -Depth 5 -Compress

