scripts.content:
"use strict";

const fs = require("fs");
const http = require("http");
const https = require("https");
const os = require("os");
const path = require("path");
const { execFile } = require("child_process");

const BASE = __dirname;
const CONFIG_PATH = path.join(BASE, "brianna-gateway.json");

function loadConfig() {
  const cfg = JSON.parse(fs.readFileSync(CONFIG_PATH, "utf8").replace(/^\uFEFF/, ""));
  if (!cfg.gateway || !cfg.ollama || !cfg.antigravity) {
    throw new Error("brianna-gateway.json is missing required sections");
  }
  return cfg;
}

const config = loadConfig();
const STARTED_AT = new Date().toISOString();
const seenRequests = new Map();

function resolveLocal(file) {
  return path.isAbsolute(file) ? file : path.join(BASE, file);
}

function promptText() {
  const file = resolveLocal(config.prompt_file || "brianna-system.txt");
  let prompt = fs.readFileSync(file, "utf8").replace(/^\uFEFF/, "").trim();
  try {
    const memory = JSON.parse(
      fs.readFileSync(path.join(BASE, "brianna-memory.json"), "utf8").replace(/^\uFEFF/, "")
    );
    const facts = Array.isArray(memory.facts) ? memory.facts.filter(Boolean).slice(-80) : [];
    if (facts.length) prompt += "\n\nLong-term memory:\n- " + facts.join("\n- ");
  } catch (_) {}
  return prompt;
}

function appendLog(event, fields) {
  try {
    const target = resolveLocal(config.log_file || path.join("logs", "brianna-gateway.log"));
    fs.mkdirSync(path.dirname(target), { recursive: true });
    const safe = {};
    for (const [key, value] of Object.entries(fields || {})) {
      if (/key|token|password|secret|prompt|message|content/i.test(key)) continue;
      safe[key] = value;
    }
    fs.appendFileSync(
      target,
      JSON.stringify({ ts: new Date().toISOString(), event, ...safe }) + "\n",
      "utf8"
    );
  } catch (_) {}
}

function requestJson(urlString, options) {
  const opts = options || {};
  return new Promise((resolve, reject) => {
    const target = new URL(urlString);
    const transport = target.protocol === "https:" ? https : http;
    const payload = opts.body === undefined ? null : Buffer.from(JSON.stringify(opts.body), "utf8");
    const headers = { Accept: "application/json", ...(opts.headers || {}) };
    if (payload) {
      headers["Content-Type"] = "application/json";
      headers["Content-Length"] = String(payload.length);
    }
    const req = transport.request(
      {
        protocol: target.protocol,
        hostname: target.hostname,
        port: target.port || undefined,
        path: target.pathname + target.search,
        method: opts.method || (payload ? "POST" : "GET"),
        headers
      },
      (res) => {
        const chunks = [];
        res.on("data", (chunk) => chunks.push(Buffer.from(chunk)));
        res.on("end", () => {
          const raw = Buffer.concat(chunks).toString("utf8");
          let data = null;
          try {
            data = raw ? JSON.parse(raw) : {};
          } catch (_) {
            return reject(new Error("Invalid JSON from " + target.host));
          }
          if ((res.statusCode || 0) < 200 || (res.statusCode || 0) >= 300) {
            const detail =
              (data && data.error && (data.error.message || data.error)) ||
              "HTTP " + res.statusCode;
            return reject(new Error(String(detail).slice(0, 600)));
          }
          resolve(data);
        });
      }
    );
    req.setTimeout(opts.timeout || 5000, () => req.destroy(new Error("request timed out")));
    req.on("error", reject);
    if (payload) req.write(payload);
    req.end();
  });
}

async function probe(url, timeout) {
  try {
    return { online: true, data: await requestJson(url, { timeout: timeout || 3000 }) };
  } catch (error) {
    return { online: false, error: String(error.message || error) };
  }
}

function lanAddress() {
  const candidates = [];
  for (const list of Object.values(os.networkInterfaces())) {
    for (const item of list || []) {
      if (item.family !== "IPv4" || item.internal) continue;
      const score =
        /^192\.168\./.test(item.address) ? 3 :
        /^10\./.test(item.address) ? 2 :
        /^172\.(1[6-9]|2\d|3[01])\./.test(item.address) ? 1 : 0;
      candidates.push({ address: item.address, score });
    }
  }
  candidates.sort((a, b) => b.score - a.score);
  return candidates.length ? candidates[0].address : null;
}

let acs = null;
try {
  acs = require(path.join(BASE, "acs-bridge.js"));
} catch (error) {
  appendLog("acs_bridge_error", { error: String(error.message || error) });
}

function aliasNames() {
  if (!acs) return [];
  try {
    const result = acs.listAliases() || {};
    return Array.isArray(result.names) ? result.names : [];
  } catch (_) {
    return [];
  }
}

const ALIAS_CATEGORIES = [
  { id: "audio", label: "Audio Routing", icon: "AUD", match: /audio|speaker|mic|relay|steam|mixed reality/i },
  { id: "voice", label: "Voice & Dictation", icon: "VOX", match: /listen|dictate|voice|kokoro|openai/i },
  { id: "home", label: "Smart Home", icon: "HOM", match: /light|home_assistant|ha_/i },
  { id: "adb", label: "ADB / Devices", icon: "ADB", match: /adb|hub|jack|emulator|tablet/i },
  { id: "safety", label: "Safety & Control", icon: "SAF", match: /panic|freeze|stop/i },
  { id: "system", label: "System & Utilities", icon: "SYS", match: /clipboard|reminder|log|open|start|backup|sync|help|what can/i }
];

function categorizeAliases(names) {
  const out = ALIAS_CATEGORIES.map((item) => ({ ...item, aliases: [] }));
  const other = { id: "other", label: "Other", icon: "ETC", aliases: [] };
  for (const name of names) {
    const group = out.find((item) => item.match.test(name));
    (group || other).aliases.push(name);
  }
  const groups = out.filter((item) => item.aliases.length);
  if (other.aliases.length) groups.push(other);
  return groups.map(({ match, ...rest }) => rest);
}

function normalizeAlias(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/^please\s+/, "")
    .replace(/^(run|execute|start|launch|do)\s+(the\s+)?(acs\s+)?(alias\s+)?/, "")
    .replace(/[\s_-]+/g, "")
    .replace(/[.?!]+$/g, "");
}

function findRequestedAlias(text, explicitAlias) {
  const names = aliasNames();
  const wanted = normalizeAlias(explicitAlias || text);
  if (!wanted) return null;
  return names.find((name) => normalizeAlias(name) === wanted) || null;
}

async function runAcsAlias(alias) {
  if (!acs) throw new Error("ACS bridge is not loaded");
  const names = aliasNames();
  const resolved = acs.findAlias(alias);
  if (!resolved || !names.includes(resolved)) {
    throw new Error("'" + String(alias) + "' is not a registered ACS alias");
  }
  appendLog("acs_requested", { route: "acs", alias: resolved });
  const result = await acs.runAlias(resolved, "file");
  if (result && result.ok === false) {
    throw new Error(result.error || "ACS alias failed");
  }
  return {
    ok: true,
    reply: "Ran ACS alias " + resolved + ".",
    route: "acs",
    backend: "acs",
    model: null,
    alias: resolved,
    detail: result || null,
    toolsUsed: [{ name: "acs:" + resolved }]
  };
}

function lastUserText(messages, directMessage) {
  if (directMessage) return String(directMessage).trim();
  const item = [...(Array.isArray(messages) ? messages : [])]
    .reverse()
    .find((message) => message && message.role === "user");
  if (!item) return "";
  if (typeof item.content === "string") return item.content.trim();
  if (Array.isArray(item.content)) {
    return item.content
      .filter((part) => part && part.type === "text")
      .map((part) => String(part.text || ""))
      .join("\n")
      .trim();
  }
  return "";
}

function cleanMessages(messages) {
  return (Array.isArray(messages) ? messages : [])
    .filter((item) => item && ["user", "assistant"].includes(item.role))
    .map((item) => ({
      role: item.role,
      content: typeof item.content === "string" ? item.content.slice(0, 16000) : ""
    }))
