function Find-NirCmd {
    foreach ($c in @("C:\adb\nircmd.exe","C:\Windows\nircmd.exe",(Join-Path $PSScriptRoot "nircmd.exe"))) {
        if (Test-Path -LiteralPath $c) { return (Resolve-Path -LiteralPath $c).Path }
    }
    $w = Get-Command "nircmd.exe" -ErrorAction SilentlyContinue
    if ($w) { return $w.Source }
    return $null
}

# Always target LG TV for Brianna voice (Dell request)
$nir = Find-NirCmd
$targetName = "LG TV"
if ($nir) {
    # roles: 0=console 1=multimedia 2=communications
    foreach ($role in 0,1,2) {
        & $nir setdefaultsounddevice $targetName $role 2>$null | Out-Null
    }
    Start-Sleep -Milliseconds 200
}

$player = [System.Media.SoundPlayer]::new($resolved)
try {
    $player.Load()
    $player.PlaySync()
    Write-Output "OK default=$targetName"
} finally {
    $player.Dispose()
}

