"use strict";

const fs = require("fs");
const http = require("http");
const https = require("https");
const os = require("os");
const { execFile } = require("child_process");
const kokoroClient = require("./kokoro-client.js");

const GB = 1024 * 1024 * 1024;

function number(value, fallback) {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function requestJson(urlString, options) {
  const opts = options || {};
  return new Promise((resolve, reject) => {
    const target = new URL(urlString);
    const transport = target.protocol === "https:" ? https : http;
    const payload = opts.body === undefined
      ? null
      : Buffer.from(JSON.stringify(opts.body), "utf8");
    const headers = { Accept: "application/json", ...(opts.headers || {}) };
    if (payload) {
      headers["Content-Type"] = "application/json";
      headers["Content-Length"] = String(payload.length);
    }
    const req = transport.request(
      {
        protocol: target.protocol,
        hostname: target.hostname,
        port: target.port || undefined,
        path: target.pathname + target.search,
        method: opts.method || (payload ? "POST" : "GET"),
        headers
      },
      (res) => {
        const chunks = [];
        res.on("data", (chunk) => chunks.push(Buffer.from(chunk)));
        res.on("end", () => {
          const raw = Buffer.concat(chunks).toString("utf8");
          let data = {};
          try {
            data = raw ? JSON.parse(raw) : {};
          } catch (_) {
            return reject(new Error("Invalid JSON from " + target.host));
          }
          if ((res.statusCode || 0) < 200 || (res.statusCode || 0) >= 300) {
            return reject(new Error(String(data.error || "HTTP " + res.statusCode).slice(0, 500)));
          }
          resolve(data);
        });
      }
    );
    req.setTimeout(opts.timeout || 10000, () => req.destroy(new Error("request timed out")));
    req.on("error", reject);
    if (payload) req.write(payload);
    req.end();
  });
}

function runFile(executable, args, timeout) {
  return new Promise((resolve) => {
    execFile(
      executable,
      args,
      { timeout: timeout || 5000, windowsHide: true },
      (error, stdout, stderr) => resolve({
        ok: !error,
        stdout: String(stdout || ""),
        stderr: String(stderr || ""),
        error: error ? String(error.message || error) : null
      })
    );
  });
}

function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function createResourceManager(options) {
  const opts = options || {};
  const rootConfig = opts.config || {};
  const policy = rootConfig.resources || {};
  const ollamaPolicy = policy.ollama || {};
  const msiPolicy = policy.msi || {};
  const ttsPolicy = rootConfig.tts || {};
  const appendLog = typeof opts.appendLog === "function" ? opts.appendLog : () => {};
  const ollamaBase = String(
    (rootConfig.ollama && rootConfig.ollama.url) || "http://127.0.0.1:11434"
  ).replace(/\/$/, "");
  const managedModels = [...new Set(
    (Array.isArray(ollamaPolicy.managed_models) && ollamaPolicy.managed_models.length
      ? ollamaPolicy.managed_models
      : [
          rootConfig.ollama && rootConfig.ollama.local_model,
          rootConfig.ollama && rootConfig.ollama.vision_model
        ])
      .filter(Boolean)
