  )];

  const settings = {
    enabled: policy.enabled !== false,
    pollMs: Math.max(15000, number(policy.poll_seconds, 30) * 1000),
    nearFreeGb: Math.max(0.5, number(policy.near_critical_free_gb, 3)),
    nearFreePercent: Math.max(3, number(policy.near_critical_free_percent, 20)),
    criticalFreeGb: Math.max(0.25, number(policy.critical_free_gb, 2)),
    criticalFreePercent: Math.max(1, number(policy.critical_free_percent, 12.5)),
    nearSamples: Math.max(2, Math.round(number(policy.near_critical_samples, 2))),
    cooldownMs: Math.max(60000, number(policy.action_cooldown_minutes, 5) * 60000),
    msiRefreshMs: Math.max(60000, number(msiPolicy.refresh_minutes, 5) * 60000),
    ttsShutdownOnCritical: ttsPolicy.shutdown_on_critical !== false
  };

  const state = {
