    activeRequests: 0,
    pressureLevel: "normal",
    profile: "NORMAL",
    pressureSamples: 0,
    pendingPressure: false,
    operation: null,
    observedLoadedAt: {},
    msi: {
      sdkRoot: String(
        msiPolicy.sdk_root || "C:\\Program Files (x86)\\MSI\\MSI Center"
      ),
      sdkDetected: false,
      centralServerRunning: false,
      protectedFromSleep: true,
      lastSampleAt: null,
      error: null
    }
  };

  let timer = null;
  let lastAutomaticActionAt = 0;
  let lastMsiRefreshAt = 0;

  function memorySnapshot() {
    const total = os.totalmem();
    const free = os.freemem();
    return {
      totalGb: Number((total / GB).toFixed(2)),
      freeGb: Number((free / GB).toFixed(2)),
      usedPercent: Number(((1 - free / total) * 100).toFixed(1)),
      freePercent: Number(((free / total) * 100).toFixed(1))
    };
  }


  let lastCpus = os.cpus();
  function getCpuUsage() {
    const cpus = os.cpus();
    let idle = 0;
    let total = 0;
    for (let i = 0; i < cpus.length; i++) {
      for (let type in cpus[i].times) {
        total += cpus[i].times[type] - lastCpus[i].times[type];
      }
      idle += cpus[i].times.idle - lastCpus[i].times.idle;
    }
