    if (total === 0) return 0;
    return Math.round(100 - (100 * idle / total));
  }

  async function getThermal() {
    return new Promise((resolve) => {
      execFile("powershell.exe", ["-NoProfile", "-Command", "(Get-WmiObject MSAcpi_ThermalZoneTemperature -Namespace 'root/wmi' -ErrorAction SilentlyContinue).CurrentTemperature"], { timeout: 3000, windowsHide: true }, (error, stdout) => {
