scripts.content:
"use strict";

(() => {
  const q = document.getElementById("q");
  const sendButton = document.getElementById("send");
  const output = document.getElementById("out");
  const subtitle = document.querySelector(".sub");
  let busy = false;
  let connected = false;
  let recognition = null;
  let listening = false;

  const style = document.createElement("style");
  style.textContent = [
    ".gw-status{display:inline-flex;align-items:center;gap:5px;margin-left:7px}",
    ".gw-dot{width:7px;height:7px;border-radius:50%;display:inline-block;background:var(--off);box-shadow:0 0 8px currentColor}",
    ".gw-status.on .gw-dot{background:var(--on)}",
    ".gw-chat-row{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:9px}",
    ".gw-route{color:var(--blue);font-size:10px;letter-spacing:.5px;margin-bottom:3px}"
  ].join("");
  document.head.appendChild(style);

  const status = document.createElement("span");
  status.className = "gw-status";
  status.innerHTML = '<span class="gw-dot"></span><span class="gw-text">CHECKING</span>';
  subtitle.appendChild(status);

  const chatRow = document.createElement("div");
  chatRow.className = "gw-chat-row";
  sendButton.parentNode.insertBefore(chatRow, sendButton);
  chatRow.appendChild(sendButton);

  const micButton = document.createElement("button");
  micButton.id = "gw-mic";
  micButton.textContent = "MIC: OFF";
  chatRow.appendChild(micButton);

  function setConnection(ok, detail) {
    connected = Boolean(ok);
    status.classList.toggle("on", connected);
    status.querySelector(".gw-text").textContent = connected ? "CONNECTED" : "OFFLINE";
    status.title = detail || "";
  }

  function appendLine(className, text) {
    const line = document.createElement("div");
    line.className = className;
    line.textContent = text;
    output.appendChild(line);
    output.scrollTop = output.scrollHeight;
    return line;
  }

  function requestId() {
    if (globalThis.crypto && typeof globalThis.crypto.randomUUID === "function") {
      return globalThis.crypto.randomUUID();
    }
    return Date.now().toString(36) + "-" + Math.random().toString(36).slice(2);
  }

  async function postChat(payload) {
    const response = await api("/api/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    const result = await response.json();
    if (!response.ok) throw new Error(result.error || "Gateway HTTP " + response.status);
    return result;
  }

  async function gatewaySend() {
    const text = q.value.trim();
    if (!text || busy) return;

    busy = true;
    sendButton.disabled = true;
    q.value = "";
    convo.push({ role: "user", content: text });
    appendLine("you", "you: " + text);
    const thinking = appendLine("her", "…");
    const id = requestId();

    try {
      let result = await postChat({ messages: convo, requestId: id });
      if (result.requires_approval) {
        const reason = result.approval_reason || "This action needs approval.";
        if (window.confirm(reason + "\n\nApprove this request?")) {
          result = await postChat({
            messages: convo,
            requestId: id + "-approved",
            approved: true,
            route: result.route
          });
        }
      }

      thinking.remove();
      if (result.error || !result.reply) {
        appendLine("her", result.error || "Brianna returned no reply.");
      } else {
        appendLine(
          "gw-route",
          "BRIANNA · " + String(result.route || result.backend || "gateway").toUpperCase()
        );
        appendLine("her", result.reply);
        convo.push({ role: "assistant", content: result.reply });
      }
      setConnection(true);
    } catch (error) {
      thinking.remove();
      appendLine("her", "failed: " + error.message);
      setConnection(false, error.message);
    } finally {
      busy = false;
      sendButton.disabled = false;
      output.scrollTop = output.scrollHeight;
    }
  }

  sendButton.onclick = gatewaySend;
  q.addEventListener(
    "keydown",
    (event) => {
      if (event.key !== "Enter") return;
      event.preventDefault();
      event.stopImmediatePropagation();
      gatewaySend();
    },
    true
  );

  const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (Recognition) {
    recognition = new Recognition();
    recognition.lang = "en-US";
    recognition.interimResults = true;
    recognition.continuous = false;
    recognition.onstart = () => {
      listening = true;
      micButton.textContent = "MIC: LISTENING";
      micButton.className = "on";
    };
    recognition.onresult = (event) => {
      let text = "";
      for (let i = event.resultIndex; i < event.results.length; i += 1) {
        text += event.results[i][0].transcript;
      }
      q.value = text.trim();
    };
    recognition.onerror = (event) => {
      toast("Microphone: " + event.error);
    };
    recognition.onend = () => {
      listening = false;
      micButton.textContent = "MIC: OFF";
      micButton.className = "";
    };
    micButton.onclick = () => {
      if (listening) recognition.stop();
      else recognition.start();
    };
  } else {
    micButton.textContent = "MIC UNAVAILABLE";
    micButton.disabled = true;
    micButton.title = "This browser does not provide Web Speech Recognition.";
  }

  async function checkConnection() {
    if (!navigator.onLine) {
      setConnection(false, "Browser is offline");
      return;
    }
    try {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), 5000);
      const response = await api("/api/health", { signal: controller.signal });
      clearTimeout(timer);
      const result = await response.json();
      setConnection(response.ok && result.service === "brianna-gateway");
      if (connected) loadAliases();
    } catch (error) {
      setConnection(false, error.message);
    }
  }

  window.addEventListener("online", checkConnection);
  window.addEventListener("offline", () => setConnection(false, "Browser is offline"));
  document.addEventListener("visibilitychange", () => {
    if (!document.hidden) checkConnection();
  });
  checkConnection();
  setInterval(checkConnection, 20000);
})();

# /// script
# requires-python = ">=3.10"
# dependencies = ["mcp>=1.2.0", "requests"]
# ///
"""
Antigravity <-> Dell's AIO MCP bridge.

Exposes Dell's AIO (the local media/automation hub running on
http://127.0.0.1:43177) as a set of MCP tools, so the Antigravity IDE
can call directly into it as an MCP client -- play titles, add magnets,
launch PlayTorrio/ADB Studio, run Brianna automation actions, etc.

This mirrors the existing OpenWebUI_CUA_Bridge, but runs the opposite
direction: instead of Brianna driving a GUI-automation daemon, this lets
an external MCP client (Antigravity) call directly into Dell's AIO's
already-existing HTTP API.

Run it directly with uv (no manual pip install needed):

    uv run "antigravity_aio_mcp_server.py"

Register it in Antigravity:
  1. In the editor's agent side panel, click "..." -> MCP Servers -> Manage MCP Servers -> View raw config.
  2. That opens C:\\Users\\Dell\\.gemini\\antigravity\\mcp_config.json
  3. Add an entry (see antigravity_mcp_config.snippet.json in this folder for the exact block).
  4. Save, then reload MCP servers in Antigravity. Dell's AIO must already be running
     (Run_Dells_AIO.cmd) for these tools to succeed -- this bridge does not start it for you.
"""

from __future__ import annotations

import requests
from mcp.server.fastmcp import FastMCP

AIO_BASE = "http://127.0.0.1:43177"
TIMEOUT = 20

mcp = FastMCP("dells-aio")


def _get(path: str, **params) -> dict:
    r = requests.get(f"{AIO_BASE}{path}", params=params, timeout=TIMEOUT)
    r.raise_for_status()
    return r.json()


def _post(path: str, payload: dict | None = None) -> dict:
    r = requests.post(f"{AIO_BASE}{path}", json=payload or {}, timeout=TIMEOUT)
    r.raise_for_status()
    return r.json()


@mcp.tool()
def aio_status() -> dict:
    """Get Dell's AIO service health/status (confirms the AIO server is up)."""
    return _get("/api/status")


@mcp.tool()
def aio_play_title(query: str) -> dict:
    """Search Dell's AIO catalog for a movie or TV title by name and start
    playing it in the embedded player (mirrors what asking Brianna to
    'play <title>' does)."""
    return _post("/api/brianna/play", {"query": query})


@mcp.tool()
def aio_add_magnet(magnet: str, space: str = "general") -> dict:
    """Add a magnet link to TorBox via Dell's AIO. `space` is 'general'
    (TorBox General library) or 'private' (TorBox Adult library)."""
    return _post("/api/magnet", {"magnet": magnet, "space": space})


@mcp.tool()
def aio_open_playtorrio() -> dict:
    """Launch the PlayTorrio desktop app (torrent/WebTorrent streaming
    media center) from Dell's AIO."""
    return _post("/api/macros/open-playtorrio")


@mcp.tool()
def aio_open_adb_studio() -> dict:
    """Launch the DK ADB Automation Studio from Dell's AIO."""
    return _post("/api/macros/open-studio")


@mcp.tool()
def aio_reveal_path(path: str) -> dict:
    """Open Windows Explorer to a given file or folder path via Dell's AIO."""
    return _post("/api/macros/reveal", {"path": path})


@mcp.tool()
def aio_brianna_assistant(action: str, message: str = "") -> dict:
    """Run a named Brianna automation action (the same action registry
    Brianna's voice/text assistant uses -- e.g. 'open_adb_studio',
    'heal_all', or any other registered action id) with an optional
    natural-language note/argument."""
    return _post("/api/brianna/assistant", {"action": action, "message": message})


@mcp.tool()
def aio_brianna_chat(message: str) -> dict:
    """Send a chat message to Brianna's local LLM brain and get a text reply."""
    return _post("/api/brianna/chat", {"message": message})


@mcp.tool()
def aio_activity() -> dict:
    """List current transfer/download activity (TorBox adds, local
    downloads in progress) tracked by Dell's AIO."""
    return _get("/api/activity")


if __name__ == "__main__":
    mcp.run(transport="stdio")

# DK NEXUS — Brianna speech with a volume guard.
#
# Why the guard exists: on 2026-07-21 unsolicited speech at 1am woke the
# household and the entire voice stack got disabled. Speaking is not just
# "make sound" — it has to check how loud, and what time it is, first.
#
#   .\brianna-speak.ps1 -Text "hello"
#   .\brianna-speak.ps1 -Text "hello" -Force      (ignore quiet hours)
param(
  [Parameter(Mandatory = $true)][string]$Text,
  [string]$Voice = "en_US-libritts_r-medium",
  [double]$LengthScale = 1.2,    # >1 = slower. 1.2 is a relaxed pace.
  [int]$MaxVolume = 55,          # ceiling: never speak louder than this
  [int]$QuietStartHour = -1,     # -1 = read from brianna-config.json (default 22 / 10pm)
  [int]$QuietEndHour = -1,       # -1 = read from brianna-config.json (default 8 / 8am)
  [switch]$Force
)

# Quiet hours live in brianna-config.json so there is ONE place to change them.
# Explicit -QuietStartHour / -QuietEndHour still win if passed.
if ($QuietStartHour -lt 0 -or $QuietEndHour -lt 0) {
  $qs = 22; $qe = 8
  try {
    $cfgPath = Join-Path $PSScriptRoot 'brianna-config.json'
    if (Test-Path $cfgPath) {
      $cfg = Get-Content $cfgPath -Raw | ConvertFrom-Json
      if ($null -ne $cfg.quietHours) {
        if ($null -ne $cfg.quietHours.start) { $qs = [int]$cfg.quietHours.start }
        if ($null -ne $cfg.quietHours.end)   { $qe = [int]$cfg.quietHours.end }
      }
      if ($null -ne $cfg.voice -and -not $PSBoundParameters.ContainsKey('Voice')) { $Voice = [string]$cfg.voice }
      if ($null -ne $cfg.lengthScale -and -not $PSBoundParameters.ContainsKey('LengthScale')) { $LengthScale = [double]$cfg.lengthScale }
      if ($null -ne $cfg.maxVolume -and -not $PSBoundParameters.ContainsKey('MaxVolume')) { $MaxVolume = [int]$cfg.maxVolume }
    }
  } catch {}
  if ($QuietStartHour -lt 0) { $QuietStartHour = $qs }
  if ($QuietEndHour -lt 0)   { $QuietEndHour = $qe }
}

$ErrorActionPreference = "Stop"
$VoiceDir = "~\.local\share\piper-voices"
$TmpWav = Join-Path $env:TEMP "brianna_speak.wav"

