$hour = (Get-Date).Hour
$inQuietHours = if ($QuietStartHour -gt $QuietEndHour) {
  ($hour -ge $QuietStartHour) -or ($hour -lt $QuietEndHour)
} else {
  ($hour -ge $QuietStartHour) -and ($hour -lt $QuietEndHour)
}
if ($inQuietHours -and -not $Force) {
  Say-Status "BLOCKED: quiet hours ($QuietStartHour`:00-$QuietEndHour`:00). It is $hour`:00. Use -Force to override."
  exit 0
}

# ── Guard 3: check the volume BEFORE making any sound ─────────────────────
#
# We deliberately do NOT change the system volume. An earlier version lowered it
# and restored it, but Windows quantises the volume scalar and rounds upward, so
# every utterance nudged the master volume up ~2%. Over a chatty afternoon that
# walked from 58% to 68% on its own — the slow-motion version of the 1am problem.
#
# Instead we read the volume and attenuate Piper's own output to compensate.
# Nothing global is touched, so nothing can drift.
$attenuation = 1.0
try {
  if ([Vol]::Muted()) {
    Say-Status "BLOCKED: system audio is muted — speaking would be pointless."
    exit 0
  }
  $current = [math]::Round([Vol]::Level() * 100)
  Say-Status "volume check: system at $current%"
  if ($current -gt $MaxVolume) {
    $attenuation = [math]::Round($MaxVolume / $current, 3)
    Say-Status "  above $MaxVolume% ceiling - attenuating speech to $([math]::Round($attenuation * 100))% (system volume untouched)"
  }
} catch {
  Say-Status "  volume check unavailable: $($_.Exception.Message)"
}

# ── Synthesize and speak ──────────────────────────────────────────────────
$model = Join-Path $VoiceDir "$Voice.onnx"
if (-not (Test-Path $model) -or -not (Test-Path "$model.json")) {
  Say-Status "ERROR: voice '$Voice' not installed (need both .onnx and .onnx.json)"
  exit 1
}

try {
  $sw = [Diagnostics.Stopwatch]::StartNew()
  $Text | & python -m piper --model $model --length-scale $LengthScale --volume $attenuation --output_file $TmpWav 2>&1 | Out-Null
  $sw.Stop()

  if (Test-Path $TmpWav) {
    Say-Status "spoke in $($sw.ElapsedMilliseconds) ms  [$Voice, ls $LengthScale, vol $attenuation]"
    (New-Object Media.SoundPlayer $TmpWav).PlaySync()
  } else {
    Say-Status "ERROR: piper produced no audio"
  }
}
finally {
  # Nothing to restore — system volume was never modified. That is the point.
}
if ($Voice -like "Microsoft*") {
    Say-Status "Using native Windows TTS ($Voice)..."
    Add-Type -AssemblyName System.Speech
    $synth = New-Object System.Speech.Synthesis.SpeechSynthesizer
    $synth.SelectVoice($Voice)

    # Map length scale to SAPI Rate (-10 to 10)
    # Default 1.0 = Rate 0. LengthScale 1.2 = slower = Rate -2
    $rate = [math]::Round((1.0 - $LengthScale) * 10)
    if ($rate -lt -10) { $rate = -10 }
    if ($rate -gt 10) { $rate = 10 }
    $synth.Rate = $rate
    $synth.Volume = [math]::Round($attenuation * 100)

    $sw = [Diagnostics.Stopwatch]::StartNew()
    $synth.Speak($Text)
    $sw.Stop()
    Say-Status "spoke natively in $($sw.ElapsedMilliseconds) ms  [$Voice, ls $LengthScale -> rate $rate, vol $attenuation]"
    exit 0
}

$model = Join-Path $VoiceDir "$Voice.onnx"
if (-not (Test-Path $model) -or -not (Test-Path "$model.json")) {
  Say-Status "ERROR: voice '$Voice' not installed (need both .onnx and .onnx.json)"
  exit 1
