# Open WebUI ↔ CUA bridge
# Ensures cua-driver serve is up, then runs mcpo so Open WebUI can call desktop tools.
# Port: 127.0.0.1:8765  →  Settings → Tools → http://127.0.0.1:8765

$ErrorActionPreference = "Stop"
$BridgeRoot = Split-Path -Parent $MyInvocation.MyCommand.Path
$LogDir = $BridgeRoot
$CuaCandidates = @(
    "~\.cua-driver\packages\current\cua-driver.exe",
    "~\.cua-driver\packages\releases\0.12.2-x86_64-pc-windows-msvc\cua-driver.exe"
)
$Cua = $CuaCandidates | Where-Object { Test-Path $_ } | Select-Object -First 1
if (-not $Cua) {
    Write-Error "cua-driver.exe not found under ~\.cua-driver"
    exit 1
}

# Prefer Hermes uvx if present
$Uvx = @(
    "~\AppData\Local\hermes\bin\uvx.exe",
    "uvx.exe"
) | Where-Object { Get-Command $_ -ErrorAction SilentlyContinue } | Select-Object -First 1
if (-not $Uvx) {
    # Get-Command on bare name (PS 5.1 compatible — no ?.)
    $cmd = Get-Command uvx -ErrorAction SilentlyContinue
    if ($cmd) { $Uvx = $cmd.Source }
}
if (-not $Uvx) {
    Write-Error "uvx not found. Install uv (https://github.com/astral-sh/uv) so mcpo can run."
    exit 1
}

function Test-PortListen([int]$Port) {
    return [bool](Get-NetTCPConnection -LocalPort $Port -State Listen -ErrorAction SilentlyContinue)
}

function Ensure-CuaServe {
    try { $status = & $Cua status 2>&1 | Out-String } catch { $status = $_.ToString() }
    if ($status -match "daemon is running") {
        Write-Host "[OK] cua-driver daemon already running"
        return
    }
    Write-Host "[..] starting cua-driver serve (unrestricted)..."
    Start-Process -FilePath $Cua -ArgumentList @(
        "serve",
        "--permission-mode", "unrestricted",
        "--dangerously-bypass-approvals",
        "--no-overlay"
    ) -WindowStyle Hidden
    Start-Sleep -Seconds 2
    try { $status2 = & $Cua status 2>&1 | Out-String } catch { $status2 = $_.ToString() }
    if ($status2 -notmatch "daemon is running") {
        Write-Error "Failed to start cua-driver serve:`n$status2"
        exit 1
    }
    Write-Host "[OK] cua-driver serve started"
}

function Ensure-Mcpo {
    if (Test-PortListen 8765) {
        Write-Host "[OK] mcpo already listening on 127.0.0.1:8765"
        return
    }
    $outLog = Join-Path $LogDir "mcpo.log"
    $errLog = Join-Path $LogDir "mcpo.log.err"
    Write-Host "[..] starting mcpo → $Cua mcp"
    Start-Process -FilePath $Uvx -ArgumentList @(
        "mcpo",
        "--host", "127.0.0.1",
        "--port", "8765",
        "--",
        $Cua,
        "mcp"
    ) -RedirectStandardOutput $outLog -RedirectStandardError $errLog -WindowStyle Hidden
    $deadline = (Get-Date).AddSeconds(45)
    while ((Get-Date) -lt $deadline) {
        if (Test-PortListen 8765) { break }
        Start-Sleep -Milliseconds 500
    }
    if (-not (Test-PortListen 8765)) {
        Write-Error "mcpo did not open port 8765. Check $errLog"
        exit 1
    }
    Write-Host "[OK] mcpo listening on http://127.0.0.1:8765"
}

Ensure-CuaServe
Ensure-Mcpo

Write-Host ""
Write-Host "Bridge ready for Open WebUI:"
Write-Host "  Tool server URL : http://127.0.0.1:8765"
Write-Host "  OpenAPI docs    : http://127.0.0.1:8765/docs"
Write-Host "  Open WebUI      : http://127.0.0.1:8080"
Write-Host ""
Write-Host "In Open WebUI: enable Global Tools → CUA Desktop (cua-driver),"
Write-Host "use Native function calling, and type /brianna-desktop for the agent rules."

