"""
Keep latest 3 of duplicate/backup scripts under ACS media + plugin trees.
- Inside *BACKUP* folders: keep 3 newest .py/.pyw only
- Loose backup-named files (backup/before_/.bak): group by (parent_dir, normalized_stem), keep 3
- Named backup sibling folders (_backup_*, *Backup_*): keep 3 newest folders of same family
Live entrypoints without backup markers are never deleted unless >3 identical basenames
  in non-backup dirs of the SAME parent project (then keep 3 newest).
"""
from __future__ import annotations

import re
from datetime import datetime
from pathlib import Path
from send2trash import send2trash

ROOTS = [
    Path(r"~\Desktop\Automation Creation Station\Plugins\DK Video Player"),
    Path(r"~\Desktop\Automation Creation Station\_System_Core\Media Control"),
    Path(r"~\Desktop\Automation Creation Station\_System_Core\Active Scripts\Both_ Simultaneously"),
    Path(r"~\Desktop\Automation Creation Station\Plugins\DK Media Library Plugin"),
    Path(r"~\Desktop\Automation Creation Station\_System_Core\Active Scripts\Python Scripts\Video editor"),
    Path(r"~\Desktop\Automation Creation Station\Plugins\DK One Button ACS Autopilot"),
    Path(r"~\Desktop\Automation Creation Station\_System_Core\Active Scripts\Dells_AIO"),
    Path(r"~\Desktop\Active Scripts\Python Scripts\Wall clock"),
    Path(r"~\Desktop\Automation Creation Station\_System_Core\Active Scripts\Python Scripts\Wall clock"),
]

KEEP_N = 3
SKIP_DIR_PARTS = {"__pycache__", "venv", "venv311", ".venv", "site-packages", "node_modules", "Chatterbox-TTS-Server", "python_embedded"}

BACKUP_DIR_RE = re.compile(r"(backup|backups|_backups|rd_pro_backups|patch_backups|sound_fix)", re.I)
BACKUP_FILE_RE = re.compile(
    r"(backup|before_|after_|\.bak|_bak|\.failed|legacy-backup|permanent_cache|\.backup)",
    re.I,
)
DATE_RE = re.compile(
    r"(_?\d{4}-\d{2}-\d{2}([_\-T]\d{2}[-:]\d{2}[-:]\d{2})?)"
    r"|(_?\d{8}[_\-]?\d{6})"
    r"|(_?\d{8})"
)


def is_skipped(path: Path) -> bool:
    return any(p in SKIP_DIR_PARTS for p in path.parts)


def is_backup_dir(path: Path) -> bool:
    return any(BACKUP_DIR_RE.search(p) for p in path.parts)


def normalize_stem(name: str) -> str:
    stem = Path(name).stem
    # strip multi-suffix like .pyw.backup_x
    while True:
        lower = stem.lower()
        if lower.endswith((".py", ".pyw", ".bak")):
            stem = stem.rsplit(".", 1)[0]
            continue
        break
    s = stem
    s = DATE_RE.sub("", s)
    s = re.sub(r"(?i)[_\-\.]?(backup|bak|before|after|old|copy|temp|tmp|failed|patch|legacy)([_\-\.].*)?$", "", s)
    s = re.sub(r"(?i)_before_.*$", "", s)
    s = re.sub(r"(?i)[_\-\.]v\d+$", "", s)
    s = s.strip("._- ")
    return (s or stem).lower()


def mtime(p: Path) -> float:
    try:
        return p.stat().st_mtime
    except OSError:
        return 0.0


def size(p: Path) -> int:
    try:
        return p.stat().st_size
    except OSError:
        return 0


def recycle(path: Path, log: list[str]) -> bool:
    try:
        if path.exists():
            send2trash(str(path))
            log.append(f"OK {path}")
            return True
    except Exception as e:
        log.append(f"FAIL {path} :: {e}")
    return False


def keep_newest(files: list[Path], n: int = KEEP_N) -> list[Path]:
    ordered = sorted(files, key=lambda p: (mtime(p), size(p)), reverse=True)
    return ordered[n:]


def main() -> int:
    log: list[str] = []
    to_delete: list[Path] = []
    seen: set[str] = set()

    def mark(paths: list[Path]):
        for p in paths:
            key = str(p.resolve()) if p.exists() else str(p)
            if key not in seen:
                seen.add(key)
                to_delete.append(p)

    # --- Pass 1: inside backup directories, keep 3 newest scripts ---
    backup_dirs: set[Path] = set()
    for root in ROOTS:
        if not root.exists():
            continue
        for d in root.rglob("*"):
            if not d.is_dir() or is_skipped(d):
                continue
            if BACKUP_DIR_RE.search(d.name) or is_backup_dir(d):
                # only leaf-ish backup folders that actually hold files
                backup_dirs.add(d)

    for d in sorted(backup_dirs, key=lambda p: len(p.parts), reverse=True):
        scripts = [
            p for p in d.rglob("*")
            if p.is_file()
            and not is_skipped(p)
            and (
                p.suffix.lower() in {".py", ".pyw"}
                or ".py" in p.name.lower()
                or p.suffix.lower() in {".json", ".txt", ".log", ".bak"}
            )
        ]
        # Prefer trimming scripts hard; for mixed content keep 3 newest of ALL files if folder is pure backup
        if not scripts:
            continue
        # If this is a dedicated backup folder (name matches), keep 3 newest files total
        if BACKUP_DIR_RE.search(d.name):
            # group by normalized stem so different tools don't wipe each other wrongly inside same dump folder
            groups: dict[str, list[Path]] = {}
            for p in scripts:
                if p.suffix.lower() not in {".py", ".pyw"} and not re.search(r"\.pyw?(\.|$)", p.name, re.I):
                    # non-script junk in backup folder: delete if older than top 3 overall? 
                    # Delete all non-scripts older, keep only scripts' latest 3 per stem
                    continue
                key = normalize_stem(p.name)
                groups.setdefault(key, []).append(p)
            for key, files in groups.items():
                if len(files) > KEEP_N:
                    mark(keep_newest(files, KEEP_N))
            # non-python debris in backup folders: keep none if we have scripts, else keep 3
            debris = [
                p for p in d.iterdir()
                if p.is_file() and p.suffix.lower() not in {".py", ".pyw"}
            ]
            # delete all loose debris reports in backup folders older, keep 0 for txt/log in BACKUP dirs
            for p in debris:
                if p.suffix.lower() in {".txt", ".log", ".md"} or "report" in p.name.lower():
                    mark([p])

    # --- Pass 2: loose backup-named scripts next to live code ---
    loose: list[Path] = []
    for root in ROOTS:
        if not root.exists():
            continue
        for p in root.rglob("*"):
            if not p.is_file() or is_skipped(p):
                continue
            if p.suffix.lower() not in {".py", ".pyw"} and not re.search(r"\.pyw?(\.|$)", p.name, re.I):
                # still catch .pyw.backup_*
                if not re.search(r"\.pyw?\.", p.name, re.I):
                    continue
            if is_backup_dir(p.parent) and BACKUP_DIR_RE.search(p.parent.name):
                continue  # handled in pass 1
            if BACKUP_FILE_RE.search(p.name) or DATE_RE.search(p.name):
                # date in name alone is weak; require backup-ish or before_
                if BACKUP_FILE_RE.search(p.name) or re.search(r"before_|_backup|backup_", p.name, re.I):
                    loose.append(p)

    # Group loose by (grandparent or parent project, normalized stem)
    groups: dict[tuple[str, str], list[Path]] = {}
    for p in loose:
        # use parent folder name as namespace so Dells_AIO app.py backups don't mix with others
        ns = p.parent.name.lower()
        if is_backup_dir(p.parent):
            ns = p.parent.parent.name.lower() + "/" + p.parent.name.lower()
        key = (ns, normalize_stem(p.name))
        groups.setdefault(key, []).append(p)

    for key, files in groups.items():
        if len(files) > KEEP_N:
            mark(keep_newest(files, KEEP_N))

    # --- Pass 3: duplicate live Player*/DK_TORBOX* across sibling dirs: keep 3 newest ---
    live_dupe_names = {
        "player.pyw", "player.py", "dk_torbox_player.pyw",
        "player_dk_kodi_library_mode_big_buttons.pyw",
        "dk_media_library.pyw",
    }
    live_map

