"""
DK Command Center — clean navigation UI.
Browse Library categories, search Python catalog, open folders, launch scripts,
start/stop downloads organizer, sweep desktop clutter into Vaults.
"""
from __future__ import annotations

import json
import os
import subprocess
import sys
import threading
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from paths import (
    CC_ROOT,
    CATALOG_FILE,
    DESKTOP,
    LIBRARY,
    LOG_DIR,
    SYSTEM,
    VAULTS,
    load_settings,
    ensure_dirs,
)

from PyQt6.QtCore import Qt, QSize, QTimer
from PyQt6.QtGui import QFont, QAction, QColor, QPalette, QIcon
from PyQt6.QtWidgets import (
    QApplication,
