"""


def open_path(path: Path) -> None:
    if not path.exists():
        QMessageBox.warning(None, "Missing", f"Path not found:\n{path}")
        return
    if path.is_dir():
        subprocess.Popen(["explorer", str(path)])
    else:
        os.startfile(str(path))  # type: ignore[attr-defined]


def launch_python(path: Path) -> None:
    if not path.exists():
        QMessageBox.warning(None, "Missing", f"Script not found:\n{path}")
        return
    flags = subprocess.CREATE_NEW_CONSOLE if sys.platform == "win32" else 0  # type: ignore
    subprocess.Popen([sys.executable, str(path)], cwd=str(path.parent), creationflags=flags)


def organizer_running() -> int | None:
    lock = LOG_DIR / "organizer.lock"
    if not lock.exists():
        return None
    try:
        pid = int(lock.read_text(encoding="utf-8").strip())
    except Exception:
        return None
    r = subprocess.run(["tasklist", "/FI", f"PID eq {pid}"], capture_output=True, text=True)
    if str(pid) in r.stdout:
        return pid
    return None


def start_organizer() -> None:
    if organizer_running():
        return
    script = SYSTEM / "downloads_organizer.py"
    flags = subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0  # type: ignore
    # Prefer new console so user can see logs if needed - use minimized console
    subprocess.Popen(
        [sys.executable, str(script)],
        cwd=str(SYSTEM),
        creationflags=subprocess.CREATE_NEW_CONSOLE if sys.platform == "win32" else 0,  # type: ignore
    )


def stop_organizer() -> None:
    pid = organizer_running()
    if not pid:
        return
    subprocess.run(["taskkill", "/PID", str(pid), "/F"], capture_output=True)
    lock = LOG_DIR / "organizer.lock"
    lock.unlink(missing_ok=True)


class NavWindow(QMainWindow):
    def __init__(self):
