FILTER_CODE = r'''
"""
Force CUA desktop tools onto every chat.
Priority: high — injects tool_ids so models cannot claim they have no tools.
"""

from pydantic import BaseModel, Field
from typing import Optional


class Filter:
    class Valves(BaseModel):
        priority: int = Field(default=0, description="Lower = earlier")
        tool_ids: str = Field(
            default="server:0",
            description="Comma-separated tool ids (server:0 = CUA Desktop)",
        )
        force_native_fc: bool = Field(default=True, description="Force native function calling")
        enabled: bool = Field(default=True)

    class UserValves(BaseModel):
        pass

    def __init__(self):
        self.valves = self.Valves()

    def inlet(self, body: dict, __user__: Optional[dict] = None) -> dict:
        if not self.valves.enabled:
            return body

        ids = [x.strip() for x in str(self.valves.tool_ids).split(",") if x.strip()]
        if not ids:
            return body

        # Always ensure CUA tools are present
        existing = body.get("tool_ids") or []
        if not isinstance(existing, list):
            existing = []
        for tid in ids:
            if tid not in existing:
                existing.append(tid)
        body["tool_ids"] = existing

        # Native function calling
        if self.valves.force_native_fc:
            params = body.get("params") or {}
            if not isinstance(params, dict):
                params = {}
            params["function_calling"] = "native"
            body["params"] = params

        # Nudge features open
        features = body.get("features") or {}
        if not isinstance(features, dict):
            features = {}
        # leave web_search as user chose; do not force off
        body["features"] = features

        return body
'''


