def op_to_path(name: str) -> str:
    """Open WebUI uses OpenAPI operationId like tool_start_session_post."""
    n = str(name or "")
    m = re.match(r"^tool_(.+)_post$", n)
    if m:
        return m.group(1)
    m = re.match(r"^tool_(.+)$", n)
    if m:
        return m.group(1)
    return n


def call_cua(name: str, arguments):
    path = op_to_path(name)
    args = arguments
    if isinstance(args, str):
        try:
            args = json.loads(args) if args.strip() else {}
        except Exception:
            args = {}
    if not isinstance(args, dict):
        args = {}
    status, body = http("POST", f"{MCPO}/{path}", args, timeout=60)
    return path, status, body


