def chat(messages, model="deepseek-v4-flash", tools=None, tool_ids=None, max_rounds=4):
    """Run chat; if model returns tool_calls, execute via CUA and continue."""
    for round_i in range(max_rounds):
        body = {
            "model": model,
            "messages": messages,
            "stream": False,
            "temperature": 0.2,
        }
        if tools is not None:
            body["tools"] = tools
            body["tool_choice"] = "auto"
        if tool_ids is not None:
            body["tool_ids"] = tool_ids
            body["params"] = {"function_calling": "native"}

        s, resp = http("POST", f"{WEBUI}/api/chat/completions", body, headers=auth(), timeout=240)
        print(f"\n-- round {round_i+1} status {s}")
        if s != 200:
            print(str(resp)[:500])
            return False, str(resp)

        # SSE/dict handling
        if not isinstance(resp, dict):
            print("non-dict", str(resp)[:300])
            return False, str(resp)

        msg = resp["choices"][0]["message"]
        content = (msg.get("content") or "").strip()
        tool_calls = msg.get("tool_calls") or []
        print("content:", content[:250])
        print("tool_calls:", len(tool_calls), [tc["function"]["name"] for tc in tool_calls])

        if not tool_calls:
            return True, content

        messages.append(
            {
                "role": "assistant",
                "content": msg.get("content") or "",
                "tool_calls": tool_calls,
            }
        )
        for tc in tool_calls:
            fn = tc["function"]["name"]
            args = tc["function"].get("arguments") or "{}"
            path, st, result = call_cua(fn, args)
            print(f"  exec {fn} -> /{path} {st} :: {str(result)[:160]}")
            if st != 200:
                result = {"error": f"tool {path} failed: {result}"}
            messages.append(
                {
                    "role": "tool",
                    "tool_call_id": tc.get("id") or fn,
                    "name": fn,
                    "content": result if isinstance(result, str) else json.dumps(result),
                }
            )
    return False, "max rounds"


