import sys, json, urllib.request, urllib.parse, re, html

def search_web(query):
    try:
        req = urllib.request.Request('https://lite.duckduckgo.com/lite/',
                                     data=urllib.parse.urlencode({'q': query}).encode(),
                                     headers={'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64)'})
        res = urllib.request.urlopen(req, timeout=10).read().decode(errors='ignore')
        snippets = re.findall(r'class=\'result-snippet\'[^>]*>(.*?)</td>', res, re.I|re.S)
        if not snippets: return "No results found."
        text = "\n- ".join([html.unescape(re.sub(r'<[^>]+>', '', s).strip()) for s in snippets[:6]])
        return f"Search Results:\n- {text}"
    except Exception as e:
        return f"Search failed: {e}"

def send(msg):
    sys.stdout.write(json.dumps(msg) + "\n")
    sys.stdout.flush()

for line in sys.stdin:
    line = line.strip()
    if not line: continue
    try:
        req = json.loads(line)
        method = req.get("method")

        if method == "initialize":
            send({"jsonrpc": "2.0", "id": req.get("id"), "result": {
                "protocolVersion": "2024-11-05",
                "capabilities": {"tools": {}},
                "serverInfo": {"name": "duckduckgo", "version": "1.0.0"}
            }})
        elif method == "tools/list":
            send({"jsonrpc": "2.0", "id": req.get("id"), "result": {
                "tools": [{
                    "name": "search_web",
                    "description": "Search the web for up-to-date information, news, or facts.",
                    "inputSchema": {
                        "type": "object",
                        "properties": {"query": {"type": "string", "description": "The search query"}},
                        "required": ["query"]
                    }
                }]
            }})
        elif method == "tools/call":
            args = req.get("params", {}).get("arguments", {})
            query = args.get("query", "")
            out = search_web(query)
            send({"jsonrpc": "2.0", "id": req.get("id"), "result": {
                "content": [{"type": "text", "text": str(out)}]
            }})
    except Exception:
        pass

