    if (!root) return;
    root.replaceChildren();
    for (const fact of featureFacts(item, details)) {
      const chip = document.createElement("span");
      chip.textContent = fact;
      root.appendChild(chip);
    }
  }

  function bindFeatureActions(item) {
    const play = byId("dkMediaFeaturePlay");
    const details = byId("dkMediaFeatureDetails");
    if (play) {
