    mediaState.activeFeature = item;

    const hero = byId("dkMediaFeature");
    const title = byId("dkMediaFeatureTitle");
    const overview = byId("dkMediaFeatureOverview");

    if (hero) {
      const backdrop = item.backdrop || item.poster || "";
      hero.style.backgroundImage = backdrop
        ? `linear-gradient(90deg,rgba(2,7,19,.98) 0%,rgba(2,7,19,.9) 31%,rgba(2,7,19,.24) 68%,rgba(2,7,19,.1) 100%),url("${escapeCssUrl(backdrop)}")`
        : "linear-gradient(90deg,rgba(2,7,19,.98),rgba(2,7,19,.28)),linear-gradient(145deg,#08152c,#030711)";
    }
    if (title) title.textContent = item.title || "Featured";
    if (overview) {
      overview.textContent = item.overview || "Open the details to learn more about this title.";
    }

    renderFacts(item, null);
    bindFeatureActions(item);
