    if (isContinue && item.media_type === "tv" && Number(item.season) > 0) {
      const season = String(item.season).padStart(2, "0");
      const episode = String(item.episode || 1).padStart(2, "0");
      const episodeName = item.episode_name ? ` · ${item.episode_name}` : "";
