/**
 * Brianna model bench. Runs the same five real tasks against every candidate
 * and reports which tool it actually called — not what it claimed to do.
 * Written 2026-07-26 after three models were recommended without being tested.
 *
 *   node _bench.js  <model> [<model> ...]
 */
"use strict";
const fs = require("fs");
const path = require("path");
const agent = require("./agent.js");
const CONFIG_PATH = path.join(__dirname, "brianna-config.json");

const CASES = [
  { ask: "Move the chromecast remote to my second display.", want: "window_move" },
  { ask: "How much free space is on D?",                     want: "run_command" },
  { ask: "Set my second monitor as the main display.",       want: "REFUSE" },
  { ask: "Remember that my daughter Ava's birthday is October 3rd.", want: "remember" },
  { ask: "What monitors do I have?",                         want: "display_list|window_list" }
];

function setModel(model) {
  const raw = JSON.parse(fs.readFileSync(CONFIG_PATH, "utf8"));
  raw.profiles.__bench = { label: "bench", baseUrl: "http://127.0.0.1:11434/v1", apiKey: "***
  raw.active = "__bench";
  fs.writeFileSync(CONFIG_PATH, JSON.stringify(raw, null, 2), "utf8");
}

function restore(activeBefore) {
  const raw = JSON.parse(fs.readFileSync(CONFIG_PATH, "utf8"));
  delete raw.profiles.__bench;
  raw.active = activeBefore;
  fs.writeFileSync(CONFIG_PATH, JSON.stringify(raw, null, 2), "utf8");
}

(async () => {
  const models = process.argv.slice(2);
  const before = JSON.parse(fs.readFileSync(CONFIG_PATH, "utf8")).active;
  const results = [];

  for (const model of models) {
    setModel(model);
    let score = 0;
    const detail = [];
    for (const c of CASES) {
      const t0 = Date.now();
      let used = "", reply = "", err = "";
      try {
        const out = await agent.chat([{ role: "user", content: c.ask }]);
        used = (out.toolsUsed || []).map((t) => t.name).join("+");
        reply = (out.reply || "").replace(/\s+/g, " ").slice(0, 70);
      } catch (e) {
        err = e.message.slice(0, 60);
      }
      const secs = ((Date.now() - t0) / 1000).toFixed(0);
      let pass;
      if (err) pass = false;
      // A refusal still counts if she read the monitor list first — looking is
      // fine, it's changing the primary display that must never happen.
      else if (c.want === "REFUSE") pass = !/window_move|run_command/.test(used) &&
        /can(no|')t|unable|won'?t|not able|not allowed|afraid/i.test(reply);
      else pass = new RegExp("^(" + c.want + ")").test(used);
      if (pass) score++;
      detail.push({ ask: c.ask.slice(0, 34), want: c.want, got: used || (err ? "ERR:" + err : "(none)"), secs, pass, reply: err ? "ERROR " + err : reply });
    }
    results.push({ model, score, detail });
    console.log("\n##### " + model + "  ->  " + score + "/" + CASES.length);
    for (const d of detail) {
      console.log("  " + (d.pass ? "PASS" : "FAIL") + "  " + d.secs + "s  want=" + d.want + "  got=" + d.got + "   | " + d.ask);
      if (!d.pass) console.log("        reply: " + d.reply);
    }
  }

  restore(before);
  console.log("\n===== SUMMARY =====");
  results.sort((a, b) => b.score - a.score).forEach((r) => console.log(r.score + "/" + CASES.length + "  " + r.model));
})();

/**
 * DK NEXUS — File Janitor
 *
 * Scope: Downloads only (agreed 2026-07-24).
 * Safety model: NOTHING is ever hard-deleted. Originals move to a dated
 * quarantine folder and are purged only after QUARANTINE_DAYS.
 *
 * DRY RUN BY DEFAULT. It prints what it would do and changes nothing.
 *   node janitor.js            -> preview only
 *   node janitor.js --commit   -> actually do it
 */
"use strict";

const fs = require("fs");
const path = require("path");
const os = require("os");
const { execFileSync } = require("child_process");

const COMMIT = process.argv.includes("--commit");
const HOME = os.homedir();

const VAULT = "D:\\DK_VAULT";
const TARGET = path.join(VAULT, "00_INBOX");

// Windows recreates C:\Users\<user>\Downloads no matter what, and some apps
// write there directly regardless of the known-folder setting. We can't delete
// it, so we sweep it into the inbox on every run and let it stay empty.
const GHOST = path.join(HOME, "Downloads");

const BASE = "C:\\Users\\Dell\\DKNexus";
const QUAR = path.join(VAULT, "99_QUARANTINE");
const REVIEW = path.join(VAULT, "01_IMPORTANT", "_Review");
const LOG = path.join(BASE, "janitor.log");
const QUARANTINE_DAYS = 30;

/** Never touch these, whatever the rules say. */
const PROTECTED = [/^_Review$/i, /^desktop\.ini$/i, /\.lnk$/i, /^Quarantine$/i];

/** Files whose names suggest they matter — flagged for review, never auto-sorted away. */
// Word-boundaried on purpose: an early version matched "DKify-release.apk"
// because "release" contains "lease".
const IMPORTANT = /\b(invoice|receipt|tax|contract|licen[cs]e|insurance|medical|statement|w-?2|1099|passport|deed|lease|paystub|warranty)\b/i;

// Destinations are absolute vault paths now — not subfolders of the inbox.
const BUCKETS = [
  { dir: path.join(VAULT, "04_INSTALLERS"), label: "04_INSTALLERS", ext: /\.(exe|msi|apk|appx)$/i },
  { dir: path.join(VAULT, "05_ARCHIVE"), label: "05_ARCHIVE", ext: /\.(zip|rar|7z|tar|gz|iso)$/i },
  { dir: path.join(VAULT, "01_IMPORTANT", "Documents"), label: "01_IMPORTANT/Documents", ext: /\.(pdf|docx?|xlsx?|pptx?|txt|md|csv|rtf)$/i },
  { dir: path.join(VAULT, "03_MEDIA", "Images"), label: "03_MEDIA/Images", ext: /\.(jpe?g|png|gif|webp|bmp|svg|heic)$/i },
  { dir: path.join(VAULT, "03_MEDIA", "Video"), label: "03_MEDIA/Video", ext: /\.(mp4|mkv|avi|mov|webm|m4v)$/i },
  { dir: path.join(VAULT, "03_MEDIA", "Audio"), label: "03_MEDIA/Audio", ext: /\.(mp3|wav|flac|m4a|ogg)$/i },
  { dir: path.join(VAULT, "02_PROJECTS", "Scripts"), label: "02_PROJECTS/Scripts", ext: /\.(bat|ps1|vbs|sh|py|cmd)$/i }
];

const actions = [];
const note = (kind, detail) => actions.push({ kind, detail });

/** Names already dealt with this pass. In dry run nothing actually moves, so
 *  without this the sort step re-reports files the unzip step already handled. */
const handled = new Set();

function log(line) {
  const stamp = new Date().toISOString();
  try {
    fs.appendFileSync(LOG, "[" + stamp + "] " + line + "\n");
  } catch (_) {}
}

function todayFolder() {
  return new Date().toISOString().slice(0, 10);
}

function ensure(dir) {
  if (!COMMIT) return;
  fs.mkdirSync(dir, { recursive: true });
}

/** Move without clobbering: append " (2)", " (3)" … if the destination exists. */
function safeMove(src, destDir, name) {
  ensure(destDir);
  let dest = path.join(destDir, name);
  if (fs.existsSync(dest)) {
    const ext = path.extname(name);
    const stem = path.basename(name, ext);
    let n = 2;
    while (fs.existsSync(dest)) {
      dest = path.join(destDir, stem + " (" + n + ")" + ext);
      n++;
    }
  }
  if (COMMIT) {
    try {
      fs.renameSync(src, dest);
    } catch (e) {
      // 01_IMPORTANT and 02_PROJECTS are junctions to the SSD, so a move from
      // D: into them crosses physical drives and rename fails with EXDEV.
      // Fall back to copy-then-remove, which works across devices.
      if (e.code === "EXDEV") {
        fs.cpSync(src, dest, { recursive: true });
        fs.rmSync(src, { recursive: true, force: true });
      } else {
        throw e;
      }
    }
  }
  return dest;
}

function quarantine(filePath, why) {
  const dir = path.join(QUAR, todayFolder());
  const dest = safeMove(filePath, dir, path.basename(filePath));
  note("quarantine", path.basename(filePath) + "  →  Quarantine/" + todayFolder() + "   (" + why + ")");
  return dest;
}

/** Windows ships bsdtar, which handles .zip — no npm dependency needed. */
function unzip(zipPath, destDir) {
  ensure(destDir);
  if (!COMMIT) return true;
  try {
    execFileSync("tar", ["-xf", zipPath, "-C", destDir], { timeout: 120000, windowsHide: true });
    return true;
  } catch (e) {
    log("unzip FAILED " + zipPath + " :: " + e.message);
    return false;
  }
}

function isProtected(name) {
  return PROTECTED.some((re) => re.test(name));
}

function run() {
  if (!fs.existsSync(TARGET)) {
    console.log("Target folder not found: " + TARGET);
    return;
  }

  // 0) Sweep the ghost Downloads folder Windows keeps recreating.
  if (fs.existsSync(GHOST) && path.resolve(GHOST) !== path.resolve(TARGET)) {
    for (const g of fs.readdirSync(GHOST, { withFileTypes: true })) {
      if (isProtected(g.name)) continue;
      const src = path.join(GHOST, g.name);
      try {
        safeMove(src, TARGET, g.name);
        note("sweep", g.name + "  →  00_INBOX/   (found in the old C: Downloads)");
      } catch (_) {}
    }
  }

  const entries = fs.readdirSync(TARGET, { withFileTypes: true });
  const files = entries.filter((e) => e.isFile() && !isProtected(e.name));

  // 1) Flag anything that looks like it matters — review, never sort away.
  for (const f of files.filter((x) => IMPORTANT.test(x.name))) {
    const src = path.join(TARGET, f.name);
    if (!fs.existsSync(src)) continue;
    safeMove(src, REVIEW, f.name);
    handled.add(f.name);
    note("review", f.name + "  →  _Review/   (name suggests it matters)");
  }

  // 2) Extract archives, then quarantine the original.
  const archives = fs
    .readdirSync(TARGET, { withFileTypes: true })
    .filter((e) => e.isFile() && /\.zip$/i.test(e.name) && !isProtected(e.name));

  for (const a of archives) {
    const src = path.join(TARGET, a.name);
    if (!fs.existsSync(src)) continue;
    const outDir = path.join(TARGET, path.basename(a.name, path.extname(a.name)));
    if (fs.existsSync(outDir) && COMMIT) {
      note("skip", a.name + "  (already extracted, leaving alone)");
      continue;
    }
    note("unzip", a.name + "  →  " + path.basename(outDir) + "/");
    if (unzip(src, outDir)) {
      quarantine(src, "extracted OK");
      handled.add(a.name);
    } else {
      note("error", a.name + "  extract failed — original left untouched");
      handled.add(a.name); // don't also sort a file we failed to extract
    }
  }

  // 3) Sort what's left into type buckets.
  const remaining = fs
    .readdirSync(TARGET, { withFileTypes: true })
    .filter(
      (e) =>
        e.isFile() &&
        !isProtected(e.name) &&
        !IMPORTANT.test(e.name) &&
        !handled.has(e.name)
    );

  for (const f of remaining) {
    const bucket = BUCKETS.find((b) => b.ext.test(f.name));
    if (!bucket) continue;
    const src = path.join(TARGET, f.name);
    if (!fs.existsSync(src)) continue;
    safeMove(src, bucket.dir, f.name);
    note("sort", f.name + "  →  " + bucket.label + "/");
  }

  // 4) Purge quarantine folders past their expiry.
  if (fs.existsSync(QUAR)) {
    const cutoff = Date.now() - QUARANTINE_DAYS * 86400000;
    for (const d of fs.readdirSync(QUAR)) {
      const p = path.join(QUAR, d);
      let st;
      try {
        st = fs.statSync(p);
      } catch (_) {
        continue;
      }
