        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps(self.data, indent=2), encoding="utf-8")
        tmp.replace(self.path)

    def slot(self, role: str) -> SlotPlacement:
        raw = self.data.setdefault("slots", {}).get(role) or {}
        return SlotPlacement.from_dict(role, raw)

