def acquire_single_instance():
    kernel32 = ctypes.windll.kernel32
    handle = kernel32.CreateMutexW(None, False, MUTEX_NAME)
    if not handle:
        return object()
    if kernel32.GetLastError() == 183:
        kernel32.CloseHandle(handle)
        raise SystemExit(0)
    return handle


def media_files(media_dir: Path) -> list[Path]:
    if not media_dir.is_dir():
        return []
    return sorted(
        [
            path
            for path in media_dir.iterdir()
            if path.is_file() and path.suffix.lower() in {".mp3", ".wav", ".m4a", ".aac"}
        ],
        key=lambda path: path.name.lower(),
    )


def parse_file_time(path: Path) -> tuple[int, int] | None:
    stem = path.stem.strip().lower()
    compact = re.sub(r"[\s_-]+", "", stem)

    # These are part of the special 8:00 PM sequence, not separate events.
    if compact in {"bayastay", "playlast"}:
        return None

    am_pm = re.match(r"^(\d{1,2})(am|pm)(?:.*)?$", compact)
    if am_pm:
        hour = int(am_pm.group(1))
        marker = am_pm.group(2)
        if not 1 <= hour <= 12:
            return None
        if marker == "am":
            hour = 0 if hour == 12 else hour
        else:
            hour = 12 if hour == 12 else hour + 12
        return hour, 0

    digits = re.match(r"^(\d{3,4})(?:[a-z].*)?$", compact)
    if digits:
        value = digits.group(1)
        if len(value) == 3:
            hour = int(value[0])
            minute = int(value[1:])
        else:
            hour = int(value[:2])
            minute = int(value[2:])

        if not 0 <= minute <= 59:
            return None

        # The numbered work clips such as 715 and 805 are evening times.
        if 1 <= hour <= 11:
            hour += 12

        if 0 <= hour <= 23:
            return hour, minute

    return None


def build_events(media_dir: Path) -> dict[tuple[int, int], list[Path]]:
    files = media_files(media_dir)
    events: dict[tuple[int, int], list[Path]] = {}

    by_compact = {
        re.sub(r"[\s_-]+", "", path.stem.lower()): path
        for path in files
    }

    special_8pm: list[Path] = []
    for key in ("8pm", "bayastay", "playlast"):
        match = by_compact.get(key)
        if match:
            special_8pm.append(match)

    for path in files:
        when = parse_file_time(path)
        if when is None:
            continue
        # The special 8 PM event is assembled in its intended order below.
        if when == (20, 0) and special_8pm:
            continue
        events.setdefault(when, []).append(path)

    if special_8pm:
        events[(20, 0)] = special_8pm

    for paths in events.values():
        paths.sort(key=lambda path: path.name.lower())

    return events


