            code, error, len(error)
        )
        raise RuntimeError(f"MCI {code}: {error.value}")


def play(file_path: Path) -> None:
    if not file_path.is_file():
        log(f"Missing MP3: {file_path}")
        return

    alias = f"dk_{os.getpid()}_{int(time.time() * 1000)}"
    safe = str(file_path).replace('"', '""')

    try:
        mci(f'open "{safe}" type mpegvideo alias {alias}')
        mci(f"play {alias} wait")
        log(f"Played: {file_path.name}")
    except Exception as exc:
        log(f"Playback error ({file_path.name}): {exc}")
    finally:
        try:
            mci(f"close {alias}")
        except Exception:
            pass


def main() -> None:
    log("Scheduler started.")
    played: set[str] = set()
    active_date = ""

    while True:
        try:
            cfg = load_config()
            now = datetime.now()
            date_key = now.strftime("%Y-%m-%d")

            if date_key != active_date:
                active_date = date_key
                played.clear()

            # Monday=0; enabled Tuesday through Saturday.
            if now.weekday() in set(
                cfg.get("enabled_weekdays", [1, 2, 3, 4, 5])
            ):
                hhmm = now.strftime("%H:%M")

                for event in cfg.get("events", []):
                    if not event.get("enabled", True):
                        continue
                    if event.get("time") != hhmm:
                        continue

                    event_id = str(event.get("id", hhmm))
                    key = f"{date_key}|{event_id}"
                    if key in played:
                        continue

                    played.add(key)
                    prepare_audio(cfg)

                    files = event.get("files", [])
                    pause_ms = int(
                        event.get("pause_between_files_ms", 600)
                    )

                    for index, item in enumerate(files):
                        play(Path(item))
                        if index < len(files) - 1 and pause_ms > 0:
                            time.sleep(pause_ms / 1000.0)

            time.sleep(1.0)

        except Exception:
            log(traceback.format_exc())
            time.sleep(5.0)


if __name__ == "__main__":
    main()

