STUDIO = PLUGIN / "ANDROID_AUTOMATION_ADB.pyw"
RUN_STUDIO = PLUGIN / "RUN_ADB_STUDIO.bat"
START_KEEPER = PLUGIN / "START_ADB_KEEPER.bat"
