def _kw() -> dict:
    return {"creationflags": CREATE_NO_WINDOW} if os.name == "nt" and CREATE_NO_WINDOW else {}


def find_adb() -> str:
    for c in (
        shutil.which("adb"),
        r"C:\adb\adb.exe",
        str(Path.home() / "AppData/Local/Android/Sdk/platform-tools/adb.exe"),
    ):
        if c and Path(c).is_file():
            return str(c)
    raise RuntimeError("adb.exe not found (PATH, C:\\adb, or Android SDK platform-tools)")


def adb_raw(args: list[str], timeout: int = 30) -> dict[str, Any]:
    adb = find_adb()
    r = subprocess.run(
        [adb, *args],
        capture_output=True,
        text=True,
        timeout=timeout,
        **_kw(),
    )
    return {
        "ok": r.returncode == 0,
        "rc": r.returncode,
        "stdout": (r.stdout or "").strip(),
        "stderr": (r.stderr or "").strip(),
        "cmd": [adb, *args],
    }


def adb_devices() -> dict[str, Any]:
    try:
        r = adb_raw(["devices", "-l"])
        lines = [ln for ln in (r.get("stdout") or "").splitlines() if ln.strip() and not ln.startswith("List")]
        devices = []
        for ln in lines:
            parts = ln.split()
            if not parts:
                continue
            serial = parts[0]
