        brief = "ADB devices:\n" + ("\n".join(f"- {d['serial']} [{d['state']}]" for d in devices) or "(none)")
        return {"ok": True, "action": "adb_devices", "devices": devices, "count": len(devices), "brief": brief, **{k: r[k] for k in ("stdout", "stderr", "rc")}}
    except Exception as exc:
        return {"ok": False, "action": "adb_devices", "error": str(exc)}


def adb_connect(target: str) -> dict[str, Any]:
    target = (target or "").strip()
    if not target:
        return {"ok": False, "action": "adb_connect", "error": "empty target"}
    if ":" not in target:
        target = target + ":5555"
    r = adb_raw(["connect", target], timeout=20)
    brief = f"adb connect {target}\n{(r.get('stdout') or r.get('stderr') or '')}"
    return {"ok": r.get("ok") or "connected" in (r.get("stdout") or "").lower(), "action": "adb_connect", "target": target, "brief": brief, **r}


def load_device_registry() -> dict[str, Any]:
    try:
        if DEVICES_JSON.exists():
            return json.loads(DEVICES_JSON.read_text(encoding="utf-8"))
    except Exception:
        logging.exception("devices.json")
    return {}


def resolve_device_target(name: str) -> Optional[str]:
    name = (name or "").strip().lower()
    data = load_device_registry()
    devices = data.get("devices") if isinstance(data.get("devices"), dict) else data
    if not isinstance(devices, dict):
        return None
    # aliases
    aliases = {
