        "a16": "Jack-s-A16",
        "phone": "Jack-s-A16",
    }
    key = aliases.get(name)
    if key and key in devices:
        meta = devices[key]
        return meta.get("adb_serial") or f"{meta.get('ip')}:{meta.get('port') or 5555}"
    for k, meta in devices.items():
        if not isinstance(meta, dict):
            continue
        if name in k.lower() or name == str(meta.get("ip") or ""):
            return meta.get("adb_serial") or f"{meta.get('ip')}:{meta.get('port') or 5555}"
    if re.match(r"^\d+\.\d+\.\d+\.\d+(:\d+)?$", name):
        return name if ":" in name else name + ":5555"
    return None


def open_studio(extra_args: Optional[list[str]] = None) -> dict[str, Any]:
    if not STUDIO.exists():
        return {"ok": False, "action": "open_adb_studio", "error": f"missing {STUDIO}"}
    py = str(PYTHONW if PYTHONW.exists() else "pythonw")
    args = [py, str(STUDIO)] + list(extra_args or [])
    try:
        subprocess.Popen(args, cwd=str(PLUGIN), **_kw())
        return {"ok": True, "action": "open_adb_studio", "brief": f"Launched ADB Automation Studio\n{STUDIO}"}
    except Exception as exc:
        return {"ok": False, "action": "open_adb_studio", "error": str(exc)}


def start_keeper() -> dict[str, Any]:
    if START_KEEPER.exists():
        try:
            subprocess.Popen(["cmd.exe", "/c", str(START_KEEPER)], cwd=str(PLUGIN), **_kw())
            return {"ok": True, "action": "start_adb_keeper", "brief": "Started ADB Keeper"}
        except Exception as exc:
            return {"ok": False, "action": "start_adb_keeper", "error": str(exc)}
    if KEEPER.exists():
        py = str(PYTHONW if PYTHONW.exists() else "pythonw")
        subprocess.Popen([py, str(KEEPER)], **_kw())
        return {"ok": True, "action": "start_adb_keeper", "brief": f"Started {KEEPER.name}"}
    return {"ok": False, "action": "start_adb_keeper", "error": "keeper not found"}


def run_macro(path: str = "") -> dict[str, Any]:
    p = Path(path) if path else (MACROS / "WHOME_ADB.json")
    if not p.is_file():
