/**
 * ACS bridge — Automation Creation Station integration for Palot Voice HUD / Brianna.
 *
 * Discovers ACS on disk, evaluates health, lists aliases, runs aliases, and
 * submits natural-language automation tasks ACS can execute (OCR, macros, voice, etc.).
 */

const fs = require("fs");
const path = require("path");
const os = require("os");
const http = require("http");
const { spawn, spawnSync } = require("child_process");
const crypto = require("crypto");

const USERPROFILE = process.env.USERPROFILE || os.homedir();

const ACS_CANDIDATES = [
  path.join(USERPROFILE, "Desktop", "Automation Creation Station"),
  path.join(USERPROFILE, "Desktop", "Windows Automation", "Windows automation", "ACS_v9"),
  path.join(USERPROFILE, "Documents", "Automation Creation Station")
];

function exists(p) {
  try {
    return p && fs.existsSync(p);
  } catch (_) {
    return false;
  }
}

function readJson(p, fallback) {
  try {
    if (!exists(p)) return fallback;
    return JSON.parse(fs.readFileSync(p, "utf8"));
  } catch (_) {
    return fallback;
  }
}

function writeJson(p, obj) {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, JSON.stringify(obj, null, 2), "utf8");
}

function nowStamp() {
  const d = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  return (
    d.getFullYear() +
    pad(d.getMonth() + 1) +
    pad(d.getDate()) +
    "_" +
    pad(d.getHours()) +
    pad(d.getMinutes()) +
    pad(d.getSeconds())
  );
}

function findAcsRoot() {
  for (const c of ACS_CANDIDATES) {
    if (exists(c)) return c;
  }
  // loose search on Desktop
  try {
    const desk = path.join(USERPROFILE, "Desktop");
    for (const name of fs.readdirSync(desk)) {
      if (/automation\s*creation\s*station/i.test(name)) {
        const p = path.join(desk, name);
        if (fs.statSync(p).isDirectory()) return p;
      }
    }
  } catch (_) {}
  return ACS_CANDIDATES[0];
}

function resolvePaths(root) {
  root = root || findAcsRoot();
  const core = path.join(root, "_System_Core");
  const canonical = path.join(root, "Canonical Control");
  return {
    root,
    core: exists(core) ? core : root,
    canonical: exists(canonical) ? canonical : path.join(root, "Canonical Control"),
    aliasesJson: path.join(root, "_System_Core", "Nexus Automation Station", "config", "aliases.json"),
    aliasesJsonAlt: path.join(root, "Nexus Automation Station", "config", "aliases.json"),
    runAliasBat: path.join(root, "_System_Core", "Trigger Station", "Nexus_Run_Alias.bat"),
    runAliasBatAlt: path.join(root, "Trigger Station", "Nexus_Run_Alias.bat"),
    trayStatus: path.join(root, "Canonical Control", "ACS_TRAY_CONTROLLER_STATUS.json"),
    healthStatus: path.join(root, "Canonical Control", "ACS_HEALTH_STATUS.json"),
    canonicalConfig: path.join(root, "Canonical Control", "ACS_CANONICAL_CONFIG.json"),
    discovery: path.join(root, "_System_Core", "_SYSTEM_MEMORY", "ACS_DISCOVERY_LATEST.json"),
    discoveryStatus: path.join(root, "_System_Core", "_SYSTEM_MEMORY", "ACS_DISCOVERY_STATUS.json"),
    persistentMemory: path.join(root, "_System_Core", "_SYSTEM_MEMORY", "ACS_PERSISTENT_MEMORY.json"),
    operatorInbox: path.join(root, "Plugins", "DK Local Operator Plugin", "requests", "inbox"),
    operatorPlugin: path.join(root, "Plugins", "DK Local Operator Plugin", "DK_LOCAL_OPERATOR.pyw"),
    operatorRunOnce: path.join(root, "Plugins", "DK Local Operator Plugin", "RUN_LOCAL_OPERATOR_ONCE.bat"),
    nlProcessor: path.join(
      root,
      "Tagged Download Auto-Runner",
      "DK_NATURAL_LANGUAGE_AUTOMATION_PROCESSOR.pyw"
    ),
    nlProcessorAlt: path.join(
      root,
      "_System_Core",
      "Tagged Download Auto-Runner",
      "DK_NATURAL_LANGUAGE_AUTOMATION_PROCESSOR.pyw"
    ),
    ocrStatus: path.join(root, "OCR Click Tag", "status.json"),
    ocrConfig: path.join(root, "OCR Click Tag", "config.json"),
    masterPanelLnk: path.join(root, "ACS Master Control Panel.lnk"),
    webhookPort: 8765,
    gatewayPort: 8770
  };
}

function httpGet(url, timeoutMs) {
  return new Promise((resolve) => {
    const req = http.get(url, { timeout: timeoutMs || 1500 }, (res) => {
      let body = "";
      res.on("data", (c) => (body += c));
      res.on("end", () =>
        resolve({ ok: res.statusCode >= 200 && res.statusCode < 500, status: res.statusCode, body: body.slice(0, 500) })
      );
    });
    req.on("error", (e) => resolve({ ok: false, error: e.message }));
    req.on("timeout", () => {
      req.destroy();
      resolve({ ok: false, error: "timeout" });
    });
  });
}

function listAliases(paths) {
  paths = paths || resolvePaths();
  const p = exists(paths.aliasesJson) ? paths.aliasesJson : paths.aliasesJsonAlt;
  const data = readJson(p, {});
  const names = Object.keys(data || {});
  return {
    path: p,
    count: names.length,
    names: names.slice(0, 200),
    sample: names.slice(0, 25)
  };
}

function findAlias(query, paths) {
  const q = String(query || "")
    .toLowerCase()
    .trim();
  if (!q) return null;
  const { names } = listAliases(paths);
  const exact = names.find((n) => n.toLowerCase() === q);
  if (exact) return exact;
  const partial = names.find((n) => n.toLowerCase().includes(q) || q.includes(n.toLowerCase()));
  return partial || null;
}

/**
 * Full health / inventory evaluation of ACS for Brianna.
 */
async function evaluateAcs() {
  const paths = resolvePaths();
  const rootOk = exists(paths.root);
  const components = [];
  const issues = [];
  const capabilities = [];

  const checkFile = (label, p, critical) => {
    const ok = exists(p);
    components.push({ name: label, path: p, ok });
