  const health = readJson(paths.healthStatus, null);
  const canonical = readJson(paths.canonicalConfig, null);
  const discovery = readJson(paths.discovery, null);
  const ocr = readJson(paths.ocrStatus, null);
  const aliases = listAliases(paths);

  // Ports
  const webhook = await httpGet(`http://127.0.0.1:${paths.webhookPort}/`, 1200);
  const gateway = await httpGet(`http://127.0.0.1:${paths.gatewayPort}/`, 1200);
  components.push({
    name: `Webhook :${paths.webhookPort}`,
    ok: webhook.ok,
    detail: webhook.status || webhook.error
  });
  components.push({
    name: `ACS gateway :${paths.gatewayPort}`,
    ok: gateway.ok,
    detail: gateway.status || gateway.error
  });
  if (!webhook.ok) issues.push("Webhook host (8765) not responding — aliases over HTTP may fail; file/bat still work");
  if (!gateway.ok) issues.push("ACS v9 gateway (8770) not responding");

  // Process hints
  let pythonwAcs = 0;
  try {
    const r = spawnSync(
      "powershell",
      [
        "-NoProfile",
        "-Command",
        "Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -match 'Automation Creation Station|ACS_v9' } | Measure-Object | Select-Object -ExpandProperty Count"
      ],
      { encoding: "utf8", windowsHide: true, timeout: 8000 }
    );
    pythonwAcs = parseInt((r.stdout || "").trim(), 10) || 0;
  } catch (_) {}

  if (aliases.count) capabilities.push(`Nexus aliases (${aliases.count}) via bat/http`);
  if (exists(paths.operatorPlugin)) capabilities.push("Local Operator (file inbox actions)");

