scripts.content:
const { app, BrowserWindow, ipcMain, screen } = require("electron");
const path = require("path");
const fs = require("fs");

// ─── Paths ────────────────────────────────────────────────────────────────
const homedir = require("os").homedir();
const DATA_DIR = path.join(homedir, ".local", "share", "palot");
const LOCKFILE_PATH = path.join(DATA_DIR, "server.lock");

let mainWindow = null;
let serverUrl = "http://127.0.0.1:4101";
let SETTINGS_PATH = null;

function getSettingsPath() {
  if (!SETTINGS_PATH) {
    SETTINGS_PATH = path.join(app.getPath("userData"), "voice-hud-settings.json");
  }
  return SETTINGS_PATH;
}

// ─── Read OpenCode server URL from lockfile ───────────────────────────────
function readServerUrl() {
  try {
    if (fs.existsSync(LOCKFILE_PATH)) {
      const raw = fs.readFileSync(LOCKFILE_PATH, "utf-8");
      const data = JSON.parse(raw);
      if (data.port) {
        serverUrl = `http://127.0.0.1:${data.port}`;
      }
    }
  } catch (e) {
    console.warn("VoiceHUD: Could not read lockfile", e.message);
  }
  return serverUrl;
}

// ─── Persistent settings ──────────────────────────────────────────────────
function loadSettings() {
  try {
    const p = getSettingsPath();
    if (fs.existsSync(p)) {
      return JSON.parse(fs.readFileSync(p, "utf-8"));
    }
  } catch (e) {
    console.warn("VoiceHUD: Failed to load settings", e.message);
  }
  return {};
}

function saveSettings(partial) {
  try {
    const current = loadSettings();
    const merged = { ...current, ...partial };
    const p = getSettingsPath();
    const dir = path.dirname(p);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(p, JSON.stringify(merged, null, 2), "utf-8");
    return merged;
  } catch (e) {
    console.warn("VoiceHUD: Failed to save settings", e.message);
  }
}

// ─── Create the floating overlay window ───────────────────────────────────
function createWindow() {
  const saved = loadSettings();
  const displays = screen.getAllDisplays();

  // Default to primary display
  let targetDisplay = displays[0];
  if (saved.preferredMonitor && displays.length > 1) {
    const found = displays.find((d) => d.id === saved.preferredMonitor);
    if (found) targetDisplay = found;
  }

  const { x: dx, y: dy, width: dw, height: dh } = targetDisplay.workArea;

  // Position: default bottom-right of the target monitor
  const defaultX = Math.round(dx + dw - 340);
  const defaultY = Math.round(dy + dh - 260);  // Bottom right

  const winOptions = {
    width: 320,
    height: 200,
    x: saved.x != null ? saved.x : defaultX,
    y: saved.y != null ? saved.y : defaultY,
    type: "toolbar",
    frame: false,
    transparent: true,
    resizable: true,
    skipTaskbar: true,
    alwaysOnTop: true,
    hasShadow: false,
    focusable: true,
    backgroundColor: "#00000000",
    webPreferences: {
      preload: path.join(__dirname, "preload.js"),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: false,
      webSecurity: false
    }
  };

  // Try to use acrylic / glass if available
  if (process.platform === "win32") {
    winOptions.backgroundColor = "#00000000";
  }

  mainWindow = new BrowserWindow(winOptions);

  // Set Windows window attributes for transparency
  if (process.platform === "win32") {
    mainWindow.setBackgroundColor("#00000000");
  }

  // Open devtools for debugging (comment out for production)
  // mainWindow.webContents.openDevTools({ mode: "detach" });

  mainWindow.loadFile(path.join(__dirname, "hud.html"));

  // Log renderer console messages to main process console
  mainWindow.webContents.on("console-message", (_e, level, msg) => {
    if (level >= 2) console.log("HUD:", msg);
  });

  // Prevent stealing focus
  mainWindow.on("focus", () => {
    // Do not steal focus from Palot
  });

  // Save position on move
  let moveTimer = null;
  mainWindow.on("move", () => {
    if (moveTimer) clearTimeout(moveTimer);
    moveTimer = setTimeout(() => {
      const pos = mainWindow.getBounds();
      saveSettings({ x: pos.x, y: pos.y });
    }, 300);
  });

  // Save screen on close
  mainWindow.on("close", () => {
    const pos = mainWindow.getBounds();
    saveSettings({ x: pos.x, y: pos.y });
  });

  // Expose server URL to renderer
  readServerUrl();

  // Periodically re-read lockfile in case server restarts
  setInterval(() => {
    readServerUrl();
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.webContents.send("server-url", serverUrl);
    }
  }, 5000);
}

// ─── IPC handlers ─────────────────────────────────────────────────────────
ipcMain.handle("voice-hud:get-server-url", () => serverUrl);
ipcMain.handle("voice-hud:get-settings", () => loadSettings());
ipcMain.handle("voice-hud:save-settings", (_e, partial) => saveSettings(partial));

// ─── App lifecycle ────────────────────────────────────────────────────────
app.whenReady().then(() => {
  createWindow();

  app.on("activate", () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on("window-all-closed", () => {
  if (process.platform !== "darwin") app.quit();
});

