import asyncio
import tempfile
import os
import numpy as np
import sounddevice as sd
import edge_tts
from typing import Optional, Tuple


class TextToSpeech:
    """Edge TTS - Free Microsoft neural voices"""

    # Popular voices
    VOICES = {
        "en-US-AriaNeural": "Aria (US Female)",
        "en-US-GuyNeural": "Guy (US Male)",
        "en-US-JennyNeural": "Jenny (US Female)",
        "en-US-DavisNeural": "Davis (US Male)",
        "en-GB-SoniaNeural": "Sonia (UK Female)",
        "en-GB-RyanNeural": "Ryan (UK Male)",
        "en-AU-NatashaNeural": "Natasha (AU Female)",
        "en-AU-WilliamNeural": "William (AU Male)",
    }

    def __init__(self, voice: str = "en-US-AriaNeural"):
        self.voice = voice
        self.temp_dir = tempfile.gettempdir()

    def set_voice(self, voice: str):
        """Change voice"""
        if voice in self.VOICES:
            self.voice = voice

    def list_voices(self) -> dict:
        """Return available voices"""
        return self.VOICES

    async def _synthesize_async(self, text: str, output_path: str) -> bool:
        """Internal async synthesis"""
        try:
            communicate = edge_tts.Communicate(text, self.voice)
            await communicate.save(output_path)
            return True
        except Exception as e:
            print(f"Edge TTS error: {e}")
            return False

    def synthesize(self, text: str) -> Tuple[Optional[np.ndarray], Optional[int]]:
        """Synthesize text to audio array"""
        if not text.strip():
            return None, None

        output_path = os.path.join(self.temp_dir, f"tts_{os.getpid()}_{hash(text) % 10000}.wav")

        try:
            # Run async synthesis
            asyncio.run(self._synthesize_async(text, output_path))

            # Load audio
            import soundfile as sf
            audio_data, sample_rate = sf.read(output_path, dtype='float32')

            # Clean up
            if os.path.exists(output_path):
                os.unlink(output_path)

            return audio_data, sample_rate

        except Exception as e:
            print(f"Synthesis error: {e}")
            if os.path.exists(output_path):
                os.unlink(output_path)
            return None, None

    def speak(self, text: str) -> bool:
        """Synthesize and play text"""
        audio, sr = self.synthesize(text)
        if audio is not None:
            sd.play(audio, sr)
            sd.wait()
            return True
        return False

    def clone_voice(self, reference_audio_path: str) -> bool:
        """Edge TTS doesn't support voice cloning - returns False"""
        print("Edge TTS doesn't support voice cloning from MP3")
        print("Available voices:", list(self.VOICES.values()))
        return False


# Fallback: Windows SAPI (offline, no internet needed)
class WindowsTTS:
    """Windows built-in SAPI TTS - completely offline"""

    def __init__(self):
        try:
            import win32com.client
            self.speaker = win32com.client.Dispatch("SAPI.SpVoice")
            self.voices = self.speaker.GetVoices()
            print(f"Found {self.voices.Count} Windows voices")
            for i in range(self.voices.Count):
                v = self.voices.Item(i)
                print(f"  {i}: {v.GetDescription()}")
        except ImportError:
            print("pywin32 not installed - Windows TTS unavailable")
            self.speaker = None

    def set_voice(self, index: int):
        if self.speaker and 0 <= index < self.voices.Count:
            self.speaker.Voice = self.voices.Item(index)

    def speak(self, text: str) -> bool:
        if self.speaker:
            try:
                self.speaker.Speak(text)
                return True
            except Exception as e:
                print(f"SAPI error: {e}")
        return False

    def synthesize(self, text: str) -> Tuple[Optional[np.ndarray], Optional[int]]:
        # SAPI doesn't easily return audio array
        return None, None

    def clone_voice(self, reference_audio_path: str) -> bool:
