import numpy as np
import sounddevice as sd
import tempfile
import os
from faster_whisper import WhisperModel


class SpeechToText:
    def __init__(self, model_size="base", device="cpu", compute_type="int8"):
        self.model_size = model_size
        self.device = device
        self.compute_type = compute_type
        self.model = None
        self._load_model()

    def _load_model(self):
        try:
            self.model = WhisperModel(
                self.model_size, 
                device=self.device, 
                compute_type=self.compute_type
            )
            print(f"Loaded Whisper model: {self.model_size}")
        except Exception as e:
            print(f"Failed to load Whisper model: {e}")
            self.model = None

    def record_audio(self, duration=5, sample_rate=16000):
        """Record audio from microphone"""
        try:
            print(f"Recording for {duration} seconds...")
            audio = sd.rec(int(duration * sample_rate), samplerate=sample_rate, channels=1, dtype=np.float32)
            sd.wait()
            return audio.flatten()
        except Exception as e:
            print(f"Recording error: {e}")
            return None

    def transcribe(self, audio_data):
        """Transcribe audio data to text"""
        if self.model is None or audio_data is None:
            return ""

        try:
            # Save to temp file for faster-whisper
            with tempfile.NamedTemporaryFile(suffix=".wav", delete=False) as tmp:
                # Normalize audio
                audio_int16 = np.int16(audio_data * 32767)
                import scipy.io.wavfile as wav
                wav.write(tmp.name, 16000, audio_int16)
                tmp_path = tmp.name

            segments, info = self.model.transcribe(tmp_path, beam_size=5, language="en")
            text = " ".join([seg.text for seg in segments])

            os.unlink(tmp_path)
            return text.strip()
        except Exception as e:
            print(f"Transcription error: {e}")
            return ""

    def transcribe_file(self, file_path):
        """Transcribe audio file"""
        if self.model is None:
            return ""
        try:
            segments, info = self.model.transcribe(file_path, beam_size=5, language="en")
            return " ".join([seg.text for seg in segments]).strip()
        except Exception as e:
            print(f"File transcription error: {e}")
            return ""

