        return
    except Exception:
        flags = (0x08000000 | 0x00000008) if os.name == "nt" else 0
        subprocess.Popen([PYTHONW, str(ROOT / "app.pyw"), "--no-browser"], cwd=str(ROOT), creationflags=flags, close_fds=True)
        deadline = time.time() + 8
        while time.time() < deadline:
            try:
                urllib.request.urlopen(f"http://127.0.0.1:{PORT}/api/status", timeout=.5).read()
                return
            except Exception:
                time.sleep(.2)
        raise RuntimeError("Dell's AIO did not start.")


def main():
    command = (sys.argv[1] if len(sys.argv) > 1 else "open").lower()
    if command == "open":
        ensure_running()
        webbrowser.open(f"http://127.0.0.1:{PORT}/")
        return
    ensure_running()
    if command == "stop":
        result = request("/api/acs/command", {"command": "stop"})
    elif command == "status":
        result = request("/api/acs/command", {"command": "status"})
    elif command in ("play-general", "play-private"):
        query = " ".join(sys.argv[2:]).strip()
        if not query:
            raise SystemExit("A title is required.")
        result = request("/api/acs/command", {
            "command": "play",
            "space": "general" if command.endswith("general") else "private",
            "query": query,
        })
    elif command == "exit":
        result = request("/api/app/exit", {})
    else:
        raise SystemExit("Commands: open, stop, status, play-general TITLE, play-private TITLE, exit")
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()

