#!/usr/bin/env python3
from __future__ import annotations

import json
import sys
import time
import traceback
import urllib.error
import urllib.request
import winsound
from pathlib import Path


HOME = Path.home()
ACS_ROOT = HOME / "Desktop" / "Automation Creation Station"
LLM_ROOT = ACS_ROOT / "Canonical Control" / "LLM Station"
CONFIG_PATH = LLM_ROOT / "acs_llm_config.json"
VOICEBOX_DEFAULT_URL = "http://127.0.0.1:17493"
VOICEBOX_DATA_DIRS = [
    HOME / "AppData" / "Roaming" / "sh.voicebox.app",
    HOME / "AppData" / "Local" / "sh.voicebox.app",
]


def emit(payload: dict) -> None:
    sys.stdout.write(json.dumps(payload, ensure_ascii=False) + "\n")
    sys.stdout.flush()


def load_json(path: Path, default):
    try:
        return json.loads(path.read_text(encoding="utf-8-sig"))
    except Exception:
        return default


def request_json(
    url: str,
    method: str = "GET",
    payload: dict | None = None,
    headers: dict | None = None,
    timeout: float = 15.0,
):
    request_headers = {"Accept": "application/json"}
    if headers:
        request_headers.update(headers)

    data = None
    if payload is not None:
        data = json.dumps(payload).encode("utf-8")
        request_headers["Content-Type"] = "application/json"

    request = urllib.request.Request(
        url,
        data=data,
        headers=request_headers,
        method=method,
    )

    with urllib.request.urlopen(request, timeout=timeout) as response:
        raw = response.read()
        if not raw:
            return {}
        return json.loads(raw.decode("utf-8", errors="replace"))


def voicebox_health(base_url: str) -> bool:
    try:
        request_json(base_url.rstrip("/") + "/health", timeout=3.0)
        return True
    except Exception:
        return False


def find_generation_in_history(base_url: str, generation_id: str) -> dict:
    try:
        direct = request_json(
            base_url.rstrip("/") + f"/history/{generation_id}",
            timeout=10.0,
        )
        if isinstance(direct, dict):
            return direct
    except Exception:
        pass

    data = request_json(base_url.rstrip("/") + "/history", timeout=10.0)
    if isinstance(data, dict):
        items = data.get("items") or data.get("history") or data.get("generations") or []
    elif isinstance(data, list):
        items = data
    else:
        items = []

    for item in items:
        if not isinstance(item, dict):
            continue
        current_id = str(item.get("id") or item.get("generation_id") or "").strip()
        if current_id == generation_id:
            return item
    return {}


def cancel_generation(base_url: str, generation_id: str) -> None:
    if not generation_id:
        return
    try:
        request_json(
            base_url.rstrip("/") + f"/generate/{generation_id}/cancel",
            method="POST",
            timeout=5.0,
        )
    except Exception:
        pass


def _audio_paths_from_result(result: dict) -> list[str]:
    paths = []
    raw = str(result.get("audio_path") or "").strip()
    if raw:
        paths.append(raw)

    versions = result.get("versions") or []
    if isinstance(versions, list):
        active_id = str(result.get("active_version_id") or "").strip()
        for version in versions:
            if not isinstance(version, dict):
                continue
            version_path = str(version.get("audio_path") or "").strip()
            if not version_path:
                continue
            if active_id and str(version.get("id") or "").strip() == active_id:
                paths.insert(0, version_path)
            else:
                paths.append(version_path)
    return paths


def resolve_voicebox_audio_path(result: dict) -> Path | None:
    for raw_path in _audio_paths_from_result(result):
        path = Path(raw_path)
        candidates = [path] if path.is_absolute() else []
        if not path.is_absolute():
            candidates.extend(base / raw_path for base in VOICEBOX_DATA_DIRS)
        for candidate in candidates:
            if candidate.is_file():
                return candidate
    return None


def play_voicebox_audio(result: dict) -> str:
    audio_path = resolve_voicebox_audio_path(result)
    if audio_path is None:
        raise RuntimeError(
            "Voicebox finished generation, but no playable audio file was found."
        )
    winsound.PlaySound(str(audio_path), winsound.SND_FILENAME)
    return str(audio_path)


def select_profile(config: dict, base_url: str) -> tuple[str, str]:
    configured_id = str(config.get("voicebox_profile_id") or "").strip()
    configured_name = str(config.get("voicebox_profile") or "").strip()

    data = request_json(base_url.rstrip("/") + "/profiles", timeout=8.0)

    profiles = data if isinstance(data, list) else data.get("profiles", [])
    profiles = [item for item in profiles if isinstance(item, dict)]

    def item_id(item: dict) -> str:
        return str(
            item.get("id")
            or item.get("profile_id")
            or item.get("uuid")
            or ""
        ).strip()

    def item_name(item: dict) -> str:
        return str(
            item.get("name")
            or item.get("display_name")
            or item.get("title")
            or item_id(item)
        ).strip()

    if configured_id or configured_name:
        for item in profiles:
            current_id = item_id(item)
            current_name = item_name(item)
            if configured_id and current_id.lower() == configured_id.lower():
                return current_id, current_name
            if configured_name and current_name.lower() == configured_name.lower():
                return current_id, current_name

    if not profiles:
        raise RuntimeError("Voicebox returned no saved voice profiles.")

    chosen = profiles[0]
    return item_id(chosen), item_name(chosen)


def poll_generation(
    base_url: str,
    generation_id: str,
    poll_url: str,
    request_id: str,
    profile_name: str,
    timeout_seconds: float = 60.0,
) -> dict:
    url = ""
    if poll_url:
        if poll_url.startswith("http://") or poll_url.startswith("https://"):
            url = poll_url
        else:
            url = base_url.rstrip("/") + "/" + poll_url.lstrip("/")

    deadline = time.monotonic() + max(10.0, float(timeout_seconds or 60.0))
    last_status = ""

    while time.monotonic() < deadline:
        if url:
            result = request_json(url, timeout=10.0)
        else:
            result = find_generation_in_history(base_url, generation_id)

        status = str(
            result.get("status")
            or result.get("state")
            or result.get("task_status")
            or ""
        ).strip().lower()
        audio_path = str(result.get("audio_path") or result.get("path") or "").strip()

        if status and status != last_status:
            last_status = status
            emit({
                "type": "status",
                "id": request_id,
                "provider": "voicebox",
                "profile": profile_name,
                "status": status,
            })

        if status in {
            "completed",
            "complete",
            "done",
            "succeeded",
            "success",
            "ready",
            "finished",
        } or (audio_path and status not in {"", "generating", "queued", "pending", "running"}):
            return result

        if status in {
            "failed",
            "error",
            "cancelled",
            "canceled",
        }:
            message = (
                result.get("error")
                or result.get("message")
                or result.get("detail")
                or f"Voicebox generation ended with status: {status}"
            )
            raise RuntimeError(str(message))

        time.sleep(1.0)

    cancel_generation(base_url, generation_id)
    raise TimeoutError(
        "Voicebox accepted the speech request but did not finish gen

