$Root = Split-Path -Parent $SystemCore
$KokoroBat = Join-Path $VoiceStation "Kokoro_Say.bat"
$KokoroPy = Join-Path $VoiceStation "kokoro_say.pyw"
$KokoroVenvPython = Join-Path $VoiceStation "Kokoro\.venv\Scripts\python.exe"
$LogDir = Join-Path $VoiceStation "logs"
$LogFile = Join-Path $LogDir "say_text_kokoro.log"

New-Item -ItemType Directory -Force -Path $LogDir | Out-Null

function Write-VoiceLog {
    param([string]$Message)
    Add-Content -Path $LogFile -Value "$(Get-Date -Format s) $Message"
}

function Speak-With-KokoroBat {
    param([string]$SpeechText, [string]$VoiceName)

    if (!(Test-Path $KokoroBat)) {
        Write-VoiceLog "Missing Kokoro BAT: $KokoroBat"
        return $false
    }

    try {
        if ($VoiceName -ne "") {
            Start-Process -FilePath $KokoroBat -ArgumentList @($SpeechText, $VoiceName) -WindowStyle Hidden -Wait
        } else {
            Start-Process -FilePath $KokoroBat -ArgumentList @($SpeechText) -WindowStyle Hidden -Wait
        }

        Write-VoiceLog "Kokoro BAT spoke: $SpeechText"
        return $true
    }
    catch {
        Write-VoiceLog "Kokoro BAT failed: $($_.Exception.Message)"
        return $false
    }
}

function Speak-With-KokoroPython {
    param([string]$SpeechText, [string]$VoiceName)

    if (!(Test-Path $KokoroVenvPython)) {
        Write-VoiceLog "Missing Kokoro venv python: $KokoroVenvPython"
        return $false
    }

    if (!(Test-Path $KokoroPy)) {
        Write-VoiceLog "Missing kokoro_say.py: $KokoroPy"
        return $false
    }

    try {
        if ($VoiceName -ne "") {
            Start-Process -FilePath $KokoroVenvPython -ArgumentList @($KokoroPy, $SpeechText, $VoiceName) -WorkingDirectory $VoiceStation -WindowStyle Hidden -Wait
        } else {
            Start-Process -FilePath $KokoroVenvPython -ArgumentList @($KokoroPy, $SpeechText) -WorkingDirectory $VoiceStation -WindowStyle Hidden -Wait
        }

        Write-VoiceLog "Kokoro Python spoke: $SpeechText"
        return $true
    }
    catch {
        Write-VoiceLog "Kokoro Python failed: $($_.Exception.Message)"
        return $false
    }
}

function Speak-With-WindowsFallback {
    param([string]$SpeechText)

    try {
        Add-Type -AssemblyName System.Speech
        $speaker = New-Object System.Speech.Synthesis.SpeechSynthesizer
        $speaker.Rate = 0
        $speaker.Volume = 100
        $speaker.Speak($SpeechText)
        Write-VoiceLog "Windows fallback spoke: $SpeechText"
        return $true
    }
    catch {
        Write-VoiceLog "Windows fallback failed: $($_.Exception.Message)"
        return $false
    }
}

$Text = $Text.Trim()

if ($Text -eq "") {
    Write-VoiceLog "No text provided."
    exit 1
}

Write-VoiceLog "Requested Kokoro speech. Voice=$Voice Text=$Text"

$ok = Speak-With-KokoroBat -SpeechText $Text -VoiceName $Voice

if (!$ok) {
    $ok = Speak-With-KokoroPython -SpeechText $Text -VoiceName $Voice
}

if (!$ok -and !$NoFallback) {
    $ok = Speak-With-WindowsFallback -SpeechText $Text
}

if ($ok) {
    exit 0
}

exit 1

