        if event.button() == Qt.MouseButton.LeftButton and self.is_neon:
            self.drag_pos = QPoint()
            event.accept()

    def load_config(self):
        if CONFIG_PATH.exists():
            try:
                with open(CONFIG_PATH, "r") as f:
                    return json.load(f)
            except:
                pass
        return {}

    def save_config(self):
        self.config["template"] = self.text_area.toPlainText().strip()
        with open(CONFIG_PATH, "w") as f:
            json.dump(self.config, f, indent=4)
        QMessageBox.information(self, "Saved", "Announcement template saved successfully!")

    def get_calendar_events(self):
        try:
            return asyncio.run(self.get_calendar_events_async())
        except Exception as e:
            return f"Error fetching Windows calendar: {e}"

    async def get_calendar_events_async(self):
        try:
            if 'AppointmentManager' not in globals():
                return "winsdk is not installed. Please run: pip install winsdk"

            store = await AppointmentManager.request_store_async(AppointmentStoreAccessType.ALL_CALENDARS_READ_ONLY)
            if not store:
                return "Failed to get Windows Calendar store access."

            now = datetime.now(timezone.utc)
            options = FindAppointmentsOptions()
            options.max_count = 10

            appointments = await store.find_appointments_async(now, timedelta(days=1), options)
            if not appointments:
                return "You have no upcoming events today."

            event_strings = []
            for apt in appointments:
                dt = apt.start_time.astimezone()
                if apt.all_day:
                    event_strings.append(f"{apt.subject} all day")
                else:
                    time_str = dt.strftime("%I:%M %p").lstrip('0')
                    event_strings.append(f"{apt.subject} at {time_str}")

            return ", ".join(event_strings)
        except Exception as e:
            return f"Error accessing Windows Calendar: {e}"

    def build_announcement(self):
        template = self.text_area.toPlainText().strip()
        now = datetime.now()
        day_str = now.strftime("%A, %B %d")
        time_str = now.strftime("%I:%M %p").lstrip('0')

        if "{calendar}" in template:
            calendar_str = self.get_calendar_events()
        else:
            calendar_str = ""

        final_text = template.replace("{day}", day_str).replace("{time}", time_str).replace("{calendar}", calendar_str)
        return final_text

    def test_announcement(self):
        text = self.build_announcement()
        print(f"Announcing: {text}")

import ctypes
import json
import os
import shutil
import subprocess
import time
import zipfile
from datetime import datetime, timedelta
from pathlib import Path

ROOT = Path(r"~\Desktop\Automation Creation Station\_System_Core\Downloads Watcher")
CONFIG_PATH = ROOT / "config.json"
DOWNLOADS_DIR = Path(r"~\Downloads")
SCRIPTS_DIR = DOWNLOADS_DIR / "Python_Scripts"
OSD_SCRIPT = r"~\Desktop\Automation Creation Station\_System_Core\Tagged Download Auto-Runner\DK_TASK_RESULT_OSD.pyw"

VK_CONTROL = 0x11
VK_MENU = 0x12
VK_SHIFT = 0x10
VK_D = 0x44

def atomic_json(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + ".tmp")
    temp.write_text(json.dumps(value, indent=2), encoding="utf-8")
    os.replace(temp, path)

def load_config():
    try:
        if CONFIG_PATH.exists():
            return json.loads(CONFIG_PATH.read_text(encoding="utf-8-sig"))
    except Exception:
        pass
    return {"enabled": True}

def osd_notify(title, message, status="SUCCESS"):
    try:
        cmd = ["pythonw.exe", OSD_SCRIPT, "--title", title, "--message", message, "--status", status]
        subprocess.Popen(cmd, creationflags=subprocess.CREATE_NO_WINDOW)
    except Exception:
        pass

def hotkey_pressed():
    user32 = ctypes.windll.user32
    return (
        (user32.GetAsyncKeyState(VK_CONTROL) & 0x8000)
        and (user32.GetAsyncKeyState(VK_MENU) & 0x8000)
        and (user32.GetAsyncKeyState(VK_SHIFT) & 0x8000)
        and (user32.GetAsyncKeyState(VK_D) & 0x8000)
    )

def cleanup_old_scripts():
    if not SCRIPTS_DIR.exists():
        return
    now = time.time()
    for item in SCRIPTS_DIR.iterdir():
        if item.is_file():
            try:
                age_days = (now - item.stat().st_mtime) / (24 * 3600)
                if age_days > 7:
                    item.unlink()
            except Exception:
                pass

def get_current_files():
    try:
        if not DOWNLOADS_DIR.exists():
            return set()
        return {f.name for f in DOWNLOADS_DIR.iterdir() if f.is_file()}
    except Exception:
        return set()

def open_maximized(folder_path):
    powershell_script = f"Start-Process explorer -ArgumentList '\"{folder_path}\"' -WindowStyle Maximized"
    subprocess.Popen(["powershell", "-NoProfile", "-WindowStyle", "Hidden", "-Command", powershell_script], creationflags=subprocess.CREATE_NO_WINDOW)

def process_new_files(new_files):
    for filename in new_files:
        path = DOWNLOADS_DIR / filename
        if not path.exists():
            continue

        ext = path.suffix.lower()

        if ext == ".py":
            try:
                subprocess.Popen(["python.exe", str(path)])
                osd_notify("Script Started", f"Auto-ran {filename}", "SUCCESS")
            except Exception as e:
                osd_notify("Execution Error", f"Failed to run {filename}: {e}", "ERROR")

            time.sleep(0.5)
            SCRIPTS_DIR.mkdir(parents=True, exist_ok=True)
            dest = SCRIPTS_DIR / filename
            try:
                shutil.move(str(path), str(dest))
            except Exception as e:
                osd_notify("Move Error", f"Failed to move {filename}: {e}", "ERROR")

        elif ext == ".zip":
            target_folder = DOWNLOADS_DIR / path.stem
            try:
                with zipfile.ZipFile(path, 'r') as zip_ref:
                    zip_ref.extractall(target_folder)
                path.unlink()
                open_maximized(target_folder)
                osd_notify("Archive Extracted", f"Successfully extracted {filename}", "SUCCESS")
            except Exception as e:
                osd_notify("Extraction Error", f"Failed to unzip {filename}: {e}", "ERROR")

def main():
    ROOT.mkdir(parents=True, exist_ok=True)
    if not CONFIG_PATH.exists():
        atomic_json(CONFIG_PATH, {"enabled": True})

    known_files = get_current_files()
    last_cleanup = time.time()
    hotkey_was_down = False

    while True:
        # Check hotkey
        down = hotkey_pressed()
        if down and not hotkey_was_down:
            config = load_config()
            config["enabled"] = not config.get("enabled", True)
            atomic_json(CONFIG_PATH, config)
            state = "ON" if config["enabled"] else "OFF"
            osd_notify("Download Watcher", f"Status changed to: {state}", "SUCCESS" if state == "ON" else "ERROR")
        hotkey_was_down = down

        config = load_config()
        if not config.get("enabled", True):
            time.sleep(1)
            # Keep updating known_files so that when re-enabled, it doesn't process backlog
            known_files = get_current_files()
            continue

        # Check cleanup (every 1 hour)
        if time.time() - last_cleanup > 3600:
            cleanup_old_scripts()
            last_cleanup = time.time()

        current_files = get_current_files()
        new_files = current_files - known_files

        if new_files:
            process_new_files(new_files)
            known_files = current_files

        # Remove deleted files from known_files so they can be re-processed if downloaded again
        known_files.intersection_update(current_files)

        time.sleep(1)

if __name__ == "__main__":
    main()

