import winreg
import glob
import os
from pathlib import Path
import json

def check_registry():
    keys = [
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows\CurrentVersion\Run"),
        (winreg.HKEY_LOCAL_MACHINE, r"SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce"),
        (winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\Run"),
        (winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\RunOnce")
    ]
    results = {}
    for hkey, subkey in keys:
        try:
            with winreg.OpenKey(hkey, subkey) as k:
                i = 0
                while True:
                    try:
                        name, val, type_ = winreg.EnumValue(k, i)
                        results[name] = val
                        i += 1
                    except OSError:
                        break
        except OSError:
            pass
    return results

def check_shortcuts(folder):
    import win32com.client
    shell = win32com.client.Dispatch("WScript.Shell")
    results = {}
    for lnk in glob.glob(os.path.join(folder, "*.lnk")):
        shortcut = shell.CreateShortCut(lnk)
        results[os.path.basename(lnk)] = shortcut.Targetpath + " " + shortcut.Arguments
    return results

res = {
    "registry": check_registry(),
    "startup_folder_vbs": {},
    "startup_folder_lnk": {}
}

try:
    import win32com.client
    startup = os.path.expanduser(r"~\AppData\Roaming\Microsoft\Windows\Start Menu\Programs\Startup")
    res["startup_folder_lnk"] = check_shortcuts(startup)
    for vbs in glob.glob(os.path.join(startup, "*.vbs")):
        with open(vbs, "r", encoding="utf-8", errors="ignore") as f:
            res["startup_folder_vbs"][os.path.basename(vbs)] = f.read()
except Exception as e:
    res["error"] = str(e)

print(json.dumps(res, indent=2))

