def human_size(value):
    try:
        size = float(value or 0)
    except (TypeError, ValueError):
        size = 0.0

    units = ("B", "KB", "MB", "GB", "TB")
    index = 0
    while size >= 1024 and index < len(units) - 1:
        size /= 1024.0
        index += 1

    if index == 0:
        return f"{int(size)} {units[index]}"
    return f"{size:.1f} {units[index]}"


def safe_int(value, default=0):
    try:
