            return text
        return ""

    if isinstance(value, dict):
        preferred = (
            "download_url", "download", "stream_url", "url", "link", "data"
        )
        for key in preferred:
            if key in value:
                found = find_http_url(value.get(key))
                if found:
                    return found
        for nested in value.values():
            found = find_http_url(nested)
            if found:
                return found

    if isinstance(value, list):
        for nested in value:
            found = find_http_url(nested)
            if found:
                return found

    return ""


def api_json(url, key, timeout=40):
    request = urllib.request.Request(
        url,
        headers={
            "Accept": "application/json",
            "Authorization": f"Bearer {key}",
            "User-Agent": "DK-TorBox-Library/1.0",
        },
        method="GET",
    )

    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            raw = response.read()
    except urllib.error.HTTPError as exc:
        detail = ""
        try:
            detail = exc.read().decode("utf-8", errors="replace")[:800]
        except Exception:
            pass
        if exc.code in (401, 403):
            raise RuntimeError(
                "TorBox rejected the API key. Copy a fresh key from "
                "TorBox Settings > Account > API Key."
            ) from exc
        raise RuntimeError(
            f"TorBox returned HTTP {exc.code}: {detail or exc.reason}"
        ) from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Could not reach TorBox: {exc.reason}") from exc
    except Exception as exc:
        raise RuntimeError(f"Could not reach TorBox: {exc}") from exc

    if not raw:
        return None

    text = raw.decode("utf-8", errors="replace").strip()
    try:
        payload = json.loads(text)
    except Exception:
        if text.lower().startswith(("http://", "https://")):
            return text
        raise RuntimeError("TorBox returned an unreadable response.")

    if isinstance(payload, dict) and payload.get("success") is False:
        detail = (
            payload.get("detail")
            or payload.get("error")
            or payload.get("message")
            or "TorBox rejected the request."
        )
        raise RuntimeError(str(detail))

    return payload.get("data") if isinstance(payload, dict) and "data" in payload else payload


def rows_from_payload(payload):
    if isinstance(payload, list):
        return payload

    if isinstance(payload, dict):
        for key in ("torrents", "items", "results", "downloads", "data"):
            value = payload.get(key)
            if isinstance(value, list):
                return value
        if any(key in payload for key in ("id", "torrent_id", "hash")):
            return [payload]

    return []


def files_from_torrent(row):
    if not isinstance(row, dict):
        return []

    for key in ("files", "file_list", "download_files", "contents"):
        value = row.get(key)
        if isinstance(value, list):
            return value
        if isinstance(value, dict):
            return list(value.values())

    return []


