            moved.append(str(dst))

    for src in STARTUP.glob("*.lnk"):
        low = src.name.lower()
        if "auto" in low and "send" in low and "chatgpt" in low:
            dst = DISABLED_DIR / src.name
            if dst.exists():
                dst = DISABLED_DIR / f"{src.stem}_{datetime.now().strftime('%Y%m%d_%H%M%S')}{src.suffix}"
            shutil.move(str(src), str(dst))
            moved.append(str(dst))

    log_line(f"Disabled Startup shortcuts: {moved if moved else 'none present in active Startup folder'}.")
    return moved

def disable_hkcu_run_entries() -> list[str]:
    ps = r'''
$paths = @(
 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Run',
 'HKCU:\Software\Microsoft\Windows\CurrentVersion\RunOnce'
)
$removed = @()
foreach ($path in $paths) {
  if (Test-Path $path) {
    $props = Get-ItemProperty -Path $path
    foreach ($p in $props.PSObject.Properties) {
      if ($p.Name -notmatch '^PS' -and $p.Name -ne 'Path') {
        $name = [string]$p.Name
        $data = [string]$p.Value
        $combined = ($name + ' ' + $data).ToLowerInvariant()
        if ($combined.Contains('chatgpt') -and $combined.Contains('auto') -and $combined.Contains('send')) {
          try {
            Remove-ItemProperty -Path $path -Name $name -Force -ErrorAction Stop
            $removed += "$path::$name"
          } catch {}
        }
      }
    }
  }
}
$removed -join "`n"
'''
    completed = subprocess.run(
        ["powershell.exe", "-NoProfile", "-ExecutionPolicy", "Bypass", "-Command", ps],
        capture_output=True,
        text=True,
        creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        timeout=20,
    )
    removed = [line.strip() for line in completed.stdout.splitlines() if line.strip()]
    log_line(f"Removed auto-send Run entries: {removed if removed else 'none found'}.")
    return removed

def write_status(stopped, moved, removed) -> None:
    payload = {
        "enabled": False,
        "paused": True,
        "running": False,
        "state": "disabled",
        "message": "ChatGPT Auto-Send is stopped and disabled from Windows startup.",
        "updated_at": datetime.now().isoformat(timespec="seconds"),
        "stopped_process_ids": stopped,
        "disabled_startup_shortcuts": moved,
        "removed_run_entries": removed,
    }
    try:
        STATUS.parent.mkdir(parents=True, exist_ok=True)
        temp = STATUS.with_suffix(".json.tmp")
        with temp.open("w", encoding="utf-8") as f:
            json.dump(payload, f, indent=2)
        temp.replace(STATUS)
    except Exception as e:
        log_line(f"Could not write status file: {e}")

    summary = (
        "CHATGPT AUTO-SEND IS DISABLED\n\n"
        f"Completed: {payload['updated_at']}\n"
        f"Stopped process IDs: {stopped if stopped else 'No matching process was running'}\n"
        f"Startup shortcuts disabled: {len(moved)}\n"
        f"Registry startup entries removed: {len(removed)}\n\n"
        "The main ACS bridge, ACS watcher, telemetry, and unrelated Python processes were not stopped.\n"
    )
    try:
        RESULT_FILE.write_text(summary, encoding="utf-8")
    except Exception:
        pass

def main() -> None:
    disable_config()
    stopped = stop_matching_processes()
    moved = disable_startup_shortcuts()
    removed = disable_hkcu_run_entries()

    time.sleep(1.0)
    stopped_again = stop_matching_processes()
    stopped = sorted(set(stopped + stopped_again))

    write_status(stopped, moved, removed)
    log_line("ChatGPT browser auto-send is fully stopped and disabled from startup.")

if __name__ == "__main__":
    try:
        main()
    except Exception as exc:
        try:
            RESULT_FILE.write_text(
                "The auto-send disable script hit an error:\n\n" + repr(exc),
                encoding="utf-8",
            )
        except Exception:
            pass
        sys.exit(1)

