def candidate_bridge_results() -> list[Path]:
    candidates = [
        Path(r"G:\My Drive\DK_ACS_REMOTE_CONTROL\Results"),
        Path(r"G:\My Drive\ACS Eyes"),
    ]

    for letter in string.ascii_uppercase:
        root = Path(f"{letter}:\\")
        candidates.extend(
            [
                root / "My Drive" / "DK_ACS_REMOTE_CONTROL" / "Results",
                root / "My Drive" / "ACS Eyes",
            ]
        )

    unique: list[Path] = []
    seen: set[str] = set()
    for candidate in candidates:
        key = str(candidate).lower()
        if key not in seen:
            seen.add(key)
            unique.append(candidate)
    return unique


def resolve_output_folder() -> Path:
    config = load_json(CONFIG_PATH, {})
    configured = str(config.get("output_folder", "")).strip() if isinstance(config, dict) else ""
    if configured:
        path = Path(configured)
        if path.is_dir():
            return path

    for candidate in candidate_bridge_results():
        try:
            if candidate.is_dir():
                atomic_json(
                    CONFIG_PATH,
                    {
                        "output_folder": str(candidate),
                        "capture_interval_seconds": 10,
                    },
                )
                return candidate
