            continue

    raise FileNotFoundError(
        r"Google Drive bridge was not found. Expected G:\My Drive\DK_ACS_REMOTE_CONTROL\Results"
    )


def latest_runner_result_key() -> str:
    try:
        files = [path for path in RUNNER_RESULTS.glob("*.json") if path.is_file()]
        if not files:
            return ""
        newest = max(files, key=lambda path: path.stat().st_mtime_ns)
        return f"{newest}|{newest.stat().st_mtime_ns}"
    except OSError:
        return ""


