    make_dpi_aware()
    image = ImageGrab.grab(all_screens=True)

    # Keep the relay readable while reducing Google Drive churn.
    max_width = 3200
    if image.width > max_width:
        ratio = max_width / image.width
        image = image.resize(
            (max_width, max(1, int(image.height * ratio)))
        )

    digest = hashlib.sha256(image.tobytes()).hexdigest()
    force_write = reason != "interval"

    if digest != prior_hash or force_write:
        output_folder.mkdir(parents=True, exist_ok=True)

        image_path = output_folder / "ACS_EYES_LATEST.jpg"
