#!/usr/bin/env python3
from __future__ import annotations

import argparse
import json
import os
import re
import shutil
import subprocess
import sys
import time
import xml.etree.ElementTree as ET
from datetime import datetime
from pathlib import Path

USER = Path.home()
ROOT = USER / "Desktop" / "Automation Creation Station" / "ADB Station" / "Nexus ADB"
LOG_DIR = ROOT / "logs"
STATUS_FILE = ROOT / "last_status.json"
LOG_FILE = LOG_DIR / "nexus_adb_recording.log"
CREATE_NO_WINDOW = getattr(subprocess, "CREATE_NO_WINDOW", 0)


def ensure_dirs():
    LOG_DIR.mkdir(parents=True, exist_ok=True)


def log(message):
    ensure_dirs()
    stamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    with LOG_FILE.open("a", encoding="utf-8") as stream:
        stream.write(f"[{stamp}] {message}\n")


def write_status(ok, command, serial, message, details=""):
    ensure_dirs()
    payload = {
        "ok": bool(ok),
        "command": command,
        "serial": serial,
        "message": message,
        "details": details,
        "updated_at": datetime.now().isoformat(timespec="seconds"),
    }
    STATUS_FILE.write_text(json.dumps(payload, indent=2), encoding="utf-8")
    log(f"{command} serial={serial or '-'} ok={ok}: {message}")


def find_adb():
    candidates = [
        shutil.which("adb"),
        r"C:\adb\adb.exe",
        str(USER / "AppData" / "Local" / "Android" / "Sdk" / "platform-tools" / "adb.exe"),
    ]
    for candidate in candidates:
        if candidate and Path(candidate).is_file():
            return str(candidate)
    raise RuntimeError("adb.exe was not found in PATH, C:\\adb, or the Android SDK.")


def hidden_kwargs():
    return {"creationflags": CREATE_NO_WINDOW} if os.name == "nt" and CREATE_NO_WINDOW else {}


def run_raw(args, timeout=20, check=True):
    result = subprocess.run(args, capture_output=True, text=True, timeout=timeout, **hidden_kwargs())
    if check and result.returncode != 0:
        detail = (result.stderr or result.stdout or "").strip()
        raise RuntimeError(detail or f"Command failed with exit code {result.returncode}")
    return result


def adb(serial, args, timeout=20, check=True):
    command = [find_adb()]
    if serial:
        command += ["-s", serial]
    command += list(args)
    result = run_raw(command, timeout=timeout, check=check)
    return (result.stdout or "").strip()


def list_online_devices():
    output = adb("", ["devices"], timeout=10)
    devices = []
    for line in output.splitlines()[1:]:
        parts = line.strip().split()
        if len(parts) >= 2 and parts[1] == "device":
            devices.append(parts[0])
    return devices


def choose_serial(requested):
    devices = list_online_devices()
    if requested:
        if requested not in devices:
            raise RuntimeError(f"ADB device is not online: {requested}")
        return requested
    if not devices:
        raise RuntimeError("No authorized ADB device is online.")
    return devices[0]


def get_screen_size(serial):
    output = adb(serial, ["shell", "wm", "size"], timeout=10)
    matches = re.findall(r"(\d+)\s*x\s*(\d+)", output)
    if not matches:
        return 1080, 1920
    width, height = matches[-1]
    return int(width), int(height)


def expand_quick_settings(serial):
    attempts = [
