        ["shell", "service", "call", "statusbar", "2"],
    ]
    for command in attempts:
        try:
            adb(serial, command, timeout=10)
            return
        except Exception:
            pass
    width, height = get_screen_size(serial)
    adb(serial, ["shell", "input", "swipe", str(width // 2), "0", str(width // 2), str(int(height * 0.85)), "500"])


def collapse_statusbar(serial):
    try:
        adb(serial, ["shell", "cmd", "statusbar", "collapse"], timeout=10)
    except Exception:
        width, height = get_screen_size(serial)
        adb(serial, ["shell", "input", "swipe", str(width // 2), str(int(height * 0.85)), str(width // 2), str(int(height * 0.08)), "350"])


def dump_ui(serial):
    remote = "/sdcard/dk_nexus_window.xml"
    last_error = ""
    for _ in range(4):
        try:
            adb(serial, ["shell", "uiautomator", "dump", remote], timeout=15, check=False)
            xml_text = adb(serial, ["exec-out", "cat", remote], timeout=15)
            start = xml_text.find("<?xml")
            if start >= 0:
                xml_text = xml_text[start:]
            return ET.fromstring(xml_text)
        except Exception as exc:
            last_error = str(exc)
            time.sleep(0.35)
    raise RuntimeError(f"Could not read Android UI hierarchy: {last_error}")


def normalized(value):
    return re.sub(r"\s+", " ", (value or "").strip()).casefold()


def node_label(node):
    return " ".join(part for part in [node.attrib.get("text", ""), node.attrib.get("content-desc", "")] if part).strip()


def parse_bounds(bounds):
    match = re.fullmatch(r"\[(\d+),(\d+)\]\[(\d+),(\d+)\]", bounds or "")
    if not match:
