def launch_chrome(serial):
    adb(serial, ["shell", "monkey", "-p", "com.android.chrome", "-c", "android.intent.category.LAUNCHER", "1"], timeout=20)


def start_recording(serial):
    log("Starting screen-record sequence.")
    expand_quick_settings(serial)
