#!/usr/bin/env python3
from __future__ import annotations

import importlib.util
import sys
import traceback
from pathlib import Path

HERE = Path(__file__).resolve().parent
APP_PATH = HERE / "DK_ACS_BRAIN_CHAT.pyw"
LOG_PATH = HERE / "Logs" / "ACS_BRAIN_CHAT_LAUNCHER.log"


def log(message: str) -> None:
    try:
        LOG_PATH.parent.mkdir(parents=True, exist_ok=True)
        with LOG_PATH.open("a", encoding="utf-8") as handle:
            handle.write(message.rstrip() + "\n")
    except Exception:
        pass


def load_app():
    spec = importlib.util.spec_from_file_location("dk_acs_brain_chat_app", APP_PATH)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"Could not load {APP_PATH}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def main() -> int:
    try:
        app_module = load_app()
        handle, acquired = app_module.acquire_single_instance()
        if not acquired:
            focused = app_module.focus_existing_window()
            if handle:
                try:
                    app_module.ctypes.windll.kernel32.CloseHandle(handle)
                except Exception:
                    pass
            return 0 if focused else 1
        app_module.ChatApp(handle).run()
        return 0
    except Exception:
        log(traceback.format_exc())
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
from __future__ import annotations

import ctypes
import json
import os
import re
import shutil
import subprocess
import sys
import time
import traceback
from datetime import datetime
from pathlib import Path

HOME = Path.home()
ROOT = HOME / "Desktop" / "Automation Creation Station" / "Tagged Download Auto-Runner"
QUEUE = ROOT / "Queue"
ARCHIVE = ROOT / "Processed - Keep 7 Days"
LOGS = ROOT / "Logs"
STATE = ROOT / "State"
WATCHER = ROOT / "DK_TAGGED_DOWNLOAD_WATCHER_LIGHT.pyw"
CONFIG = ROOT / "watcher_config.json"
STATUS = STATE / "watcher_status.json"
LOG = LOGS / "watcher.log"

STARTUP = (
    Path(os.environ.get("APPDATA", ""))
    / "Microsoft"
    / "Windows"
    / "Start Menu"
    / "Programs"
    / "Startup"
    / "DK Tagged Script Watcher.vbs"
)
START_BAT = HOME / "Desktop" / "START TAGGED SCRIPT WATCHER.bat"
STOP_BAT = HOME / "Desktop" / "STOP TAGGED SCRIPT WATCHER.bat"
OPEN_BAT = HOME / "Desktop" / "OPEN TAGGED SCRIPT ARCHIVE.bat"

CREATE_NO_WINDOW = getattr(subprocess, "CREATE_NO_WINDOW", 0)
MUTEX_NAME = r"Local\DK_TAGGED_DOWNLOAD_WATCHER_LIGHT_V2"
TAGGED_RE = re.compile(r"^DK_.*__DKRUN__\.(py|pyw)$", re.IGNORECASE)

DEFAULT_CONFIG = {
    "watch_folders": [r"D:\Dell\Downloads", str(HOME / "Downloads")],
    "retention_days": 7,
    "poll_seconds": 2.0,
    "stable_seconds": 1.5,
    "timeout_seconds": 1800,
}


def hidden_kwargs() -> dict:
    if os.name == "nt" and CREATE_NO_WINDOW:
        return {"creationflags": CREATE_NO_WINDOW}
    return {}


def now_iso() -> str:
    return datetime.now().astimezone().isoformat(timespec="seconds")


def atomic_text(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + ".tmp")
    temp.write_text(text, encoding="utf-8")
    os.replace(temp, path)


def atomic_json(path: Path, data: object) -> None:
    atomic_text(path, json.dumps(data, indent=2, ensure_ascii=False))


def load_json(path: Path, default: object) -> object:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return default


def append_log(message: str) -> None:
    LOGS.mkdir(parents=True, exist_ok=True)
    with LOG.open("a", encoding="utf-8") as handle:
        handle.write(f"{now_iso()}  {message}\n")


def write_status(state: str, message: str, **extra: object) -> None:
    atomic_json(
        STATUS,
        {
            "state": state,
            "message": message,
            "heartbeat": now_iso(),
            "pid": os.getpid(),
            **extra,
        },
    )


def config_data() -> dict:
    raw = load_json(CONFIG, {})
    data = dict(DEFAULT_CONFIG)
    if isinstance(raw, dict):
        data.update(raw)
    data["watch_folders"] = [
        Path(os.path.expandvars(str(value))).expanduser()
        for value in data.get("watch_folders", [])
    ]
    return data


def candidates(data: dict) -> list[Path]:
    found: list[Path] = []
    for folder in data["watch_folders"]:
        if not folder.is_dir():
            continue
        try:
            found.extend(
                path
                for path in folder.iterdir()
                if path.is_file() and TAGGED_RE.fullmatch(path.name)
            )
        except OSError:
            pass
    return found


def unique_destination(folder: Path, name: str) -> Path:
    folder.mkdir(parents=True, exist_ok=True)
    target = folder / name
    if not target.exists():
        return target
    stamp = datetime.now().strftime("%H%M%S_%f")
    original = Path(name)
    return folder / f"{original.stem}_{stamp}{original.suffix}"


def move_file(path: Path, folder: Path) -> Path:
    target = unique_destination(folder, path.name)
    shutil.move(str(path), str(target))
    return target


def archive_folder(kind: str) -> Path:
    return ARCHIVE / datetime.now().strftime("%Y-%m-%d") / kind


def choose_python(windowless: bool) -> str:
    names = ["pythonw.exe"] if windowless else ["python.exe"]
    roots = [
        HOME / "AppData" / "Local" / "Programs" / "Python" / "Python312",
        HOME / "AppData" / "Local" / "Programs" / "Python" / "Python314",
        Path(sys.executable).parent,
    ]
    for root in roots:
        for name in names:
            candidate = root / name
            if candidate.is_file():
                return str(candidate)
    return shutil.which("pythonw" if windowless else "python") or sys.executable


def acquire_mutex():
    kernel32 = ctypes.windll.kernel32
    handle = kernel32.CreateMutexW(None, False, MUTEX_NAME)
    if not handle:
        raise RuntimeError("Could not create watcher lock.")
    if kernel32.GetLastError() == 183:
        kernel32.CloseHandle(handle)
        raise SystemExit(0)
    return handle


def release_mutex(handle) -> None:
    try:
        ctypes.windll.kernel32.ReleaseMutex(handle)
        ctypes.windll.kernel32.CloseHandle(handle)
    except Exception:
        pass


def syntax_check(path: Path) -> tuple[bool, str]:
    try:
        compile(path.read_text(encoding="utf-8-sig"), str(path), "exec")
        return True, ""
    except Exception:
        return False, traceback.format_exc()


def execute(path: Path, data: dict) -> tuple[bool, int, str, str, float]:
    started = time.monotonic()
    exe = choose_python(path.suffix.lower() == ".pyw")
    try:
        result = subprocess.run(
            [exe, str(path)],
            cwd=str(path.parent),
            capture_output=True,
            text=True,
            timeout=float(data.get("timeout_seconds", 1800)),
            **hidden_kwargs(),
        )
        return (
            result.returncode == 0,
            int(result.returncode),
            result.stdout or "",
            result.stderr or "",
            time.monotonic() - started,
        )
    except subprocess.TimeoutExpired as exc:
        return (
            False,
            124,
            exc.stdout or "",
            exc.stderr or "Timed out",
            time.monotonic() - started,
        )
    except Exception:
        return False, 1, "", traceback.format_exc(), time.monotonic() - started


def receipt(
    archived: Path,
    original: Path,
    success: bool,
    code: int,
    stdout: str,
    stderr: str,
    elapsed: float,
) -> None:
    atomic_json(
        archived.with_suffix(archived.suffix + ".result.json"),
        {
            "success": success,
            "exit_code": code,
            "original_path": str(original),
            "archived_script": str(archived),
            "elapsed_seconds": round(elapsed, 3),
            "stdout": stdout[-20000:],
            "stderr": stderr[-20000:],
            "completed_at": now_iso(),
        },
    )


def process(path: Path, data: dict) -> None:
    original = path
    write_status("MOVING", f"Moving {path.name} out of Downloads.", current_file=path.name)
    queued = move_file(path, QUEUE)
    append_log(f"QUEUED {original} -> {queued}")

    valid, error = syntax_check(queued)
    if not valid:
        archived = move_file(queued, archive_folder("Failed"))
        receipt(archived, original, False, 2, "", error, 0.0)
        write_status("FAILED", f"{original.name} failed syntax validation.")
        return

    write_status("RUNNING", f"Running {original.name}", current_file=original.name)
    success, code, stdout, stderr, elapsed = execute(queued, data)
    archived = move_file(queued, archive_folder("Success" if success else "Failed"))
    receipt(archived, original, success, code, stdout, stderr, elapsed)

    append_log(
        f"{'SUCCESS' if success else 'FAILED'} {original.name} "
        f"exit={code} elapsed={elapsed:.2f}s -> {archived}"
    )
    write_status(
        "WAITING" if success else "FAILED",
        (
            f"Completed {original.name}; waiting."
            if success
            else f"{original.name} failed with exit code {code}."
        ),
        last_file=original.name,
        last_success=success,
        current_file="",
    )

