#!/usr/bin/env python3
from __future__ import annotations

import ctypes
import hashlib
import json
import os
import re
import subprocess
import sys
import time
import traceback
import urllib.request
from datetime import datetime
from pathlib import Path
from typing import Any

try:
    import websocket
except Exception:
    websocket = None

HOME = Path.home()
DESKTOP = HOME / "Desktop"
ACS_ROOT = DESKTOP / "Automation Creation Station"
RUNNER_ROOT = ACS_ROOT / "Tagged Download Auto-Runner"
RESULTS_DIR = RUNNER_ROOT / "Results"
RELAY_ROOT = RUNNER_ROOT / "Result Relay"
CONFIG_PATH = RELAY_ROOT / "relay_config.json"
STATE_PATH = RELAY_ROOT / "relay_state.json"
STATUS_PATH = RELAY_ROOT / "relay_status.json"
LOG_PATH = RELAY_ROOT / "relay.log"

DIRECT_BRIDGE = ACS_ROOT / "ChatGPT Direct Bridge"
PROFILE_ROOT = DIRECT_BRIDGE / "Browser Profile"

CREATE_NO_WINDOW = getattr(subprocess, "CREATE_NO_WINDOW", 0)
DETACHED_PROCESS = getattr(subprocess, "DETACHED_PROCESS", 0)
MUTEX_NAME = r"Global\DK_CHATGPT_RESULT_RELAY_V3"

DEFAULT_CONFIG: dict[str, Any] = {
    "enabled": True,
    "poll_seconds": 2.0,
    "retry_seconds": 12.0,
    "maximum_message_characters": 12000,
    "auto_launch_chatgpt": True,
    "preferred_debug_port": 9223,
    "chat_url": "https://chatgpt.com/",
    "send_only_new_results": True,
}


def now_iso() -> str:
    return datetime.now().astimezone().isoformat(timespec="seconds")


def atomic_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(path.suffix + ".tmp")
    temporary.write_text(
        json.dumps(payload, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )
    os.replace(temporary, path)


def load_json(path: Path, default: Any) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8-sig"))
    except Exception:
        return default


def load_config() -> dict[str, Any]:
    config = dict(DEFAULT_CONFIG)
    loaded = load_json(CONFIG_PATH, {})
    if isinstance(loaded, dict):
        config.update(loaded)
    return config


def save_config(config: dict[str, Any]) -> None:
    atomic_json(CONFIG_PATH, config)


def load_state() -> dict[str, Any]:
    state = load_json(STATE_PATH, {})
    if not isinstance(state, dict):
        state = {}
    state.setdefault("sent", {})
    state.setdefault("sent_count", 0)
    state.setdefault("failure_count", 0)
    return state


def save_state(state: dict[str, Any]) -> None:
    atomic_json(STATE_PATH, state)


def log(message: str) -> None:
    try:
        RELAY_ROOT.mkdir(parents=True, exist_ok=True)
        with LOG_PATH.open("a", encoding="utf-8") as handle:
            handle.write(f"{now_iso()}  {message.rstrip()}\n")
    except Exception:
        pass


def write_status(state: str, detail: str, **extra: Any) -> None:
    config = load_config()
    saved = load_state()
    atomic_json(
        STATUS_PATH,
        {
            "updated": now_iso(),
            "pid": os.getpid(),
            "enabled": bool(config.get("enabled", True)),
            "state": state,
            "detail": detail,
            "sent_count": int(saved.get("sent_count", 0)),
            "failure_count": int(saved.get("failure_count", 0)),
            **extra,
        },
    )


def acquire_single_instance() -> tuple[Any, bool]:
    if os.name != "nt":
        return None, True
    kernel32 = ctypes.windll.kernel32
    handle = kernel32.CreateMutexW(None, False, MUTEX_NAME)
    if not handle:
        return None, True
    return handle, kernel32.GetLastError() != 183


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def stable(path: Path, seconds: float = 0.65) -> bool:
    try:
        first = (path.stat().st_size, path.stat().st_mtime_ns)
        time.sleep(seconds)
        second = (path.stat().st_size, path.stat().st_mtime_ns)
        return first == second and path.is_file()
    except OSError:
        return False


def result_files() -> list[Path]:
    try:
        paths = [
            path
            for path in RESULTS_DIR.glob("*.result.json")
            if path.is_file()
        ]
        paths.sort(key=lambda path: path.stat().st_mtime)
        return paths
    except Exception:
        return []


def redact(text: str) -> str:
    replacements = [
        (
            re.compile(
                r"(?i)\b(api[_ -]?key|token|secret|password|authorization)"
                r"\b\s*[:=]\s*([^\s,;]+)"
            ),
            r"\1=[REDACTED]",
        ),
        (
            re.compile(r"\bsk-[A-Za-z0-9_-]{12,}\b"),
            "[REDACTED_OPENAI_KEY]",
        ),
        (
            re.compile(r"\bgh[pousr]_[A-Za-z0-9]{20,}\b"),
            "[REDACTED_GITHUB_TOKEN]",
        ),
        (
            re.compile(r"(?i)\bBearer\s+[A-Za-z0-9._~+/-]{12,}"),
            "Bearer [REDACTED]",
        ),
    ]

    cleaned = text
    for pattern, replacement in replacements:
        cleaned = pattern.sub(replacement, cleaned)
    return cleaned


def stringify(value: Any, limit: int) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        text = value
    else:
        try:
            text = json.dumps(value, indent=2, ensure_ascii=False)
        except Exception:
            text = str(value)

    text = redact(text.strip())
    if len(text) > limit:
        text = text[:limit] + "\n...[truncated]"
    return text


def compose_message(path: Path, digest: str, maximum: int) -> str:
    data = load_json(path, {})
    if not isinstance(data, dict):
        data = {
            "raw_result": path.read_text(
                encoding="utf-8",
                errors="replace",
            )
        }

    result_id = digest[:16]
    lines = [
        "AUTOMATED ACS FILE-RUNNER RESULT",
        f"Result ID: {result_id}",
        f"Result file: {path}",
        f"Script: {data.get('file', 'unknown')}",
        f"Status: {data.get('status', 'unknown')}",
        f"Exit code: {data.get('exit_code')}",
        f"Started: {data.get('started', '')}",
        f"Finished: {data.get('finished', '')}",
        f"Duration seconds: {data.get('duration_seconds', '')}",
    ]

    archived = stringify(data.get("archived_to"), 1000)
    error = stringify(data.get("error"), 2500)
    stdout = stringify(data.get("stdout"), 5000)
    stderr = stringify(data.get("stderr"), 4000)

    if archived:
        lines.extend(["", "Archived to:", archived])
    if error:
        lines.extend(["", "Error:", error])
    if stdout:
        lines.extend(["", "Standard output:", stdout])
    if stderr:
        lines.extend(["", "Standard error:", stderr])

    lines.extend(
        [
            "",
            "Continue the current ACS task from this result.",
            "This message was sent automatically by Dell's ACS Result Relay.",
        ]
    )

    message = redact("\n".join(lines))
    if len(message) > maximum:
        message = message[:maximum] + "\n...[message truncated]"
    return message


def run_powershell(
    script: str,
