def safe_relative_path(value: str) -> Path:
    if not value or not isinstance(value, str):
        raise ValueError("Missing relative_path.")

    value = value.replace("/", "\\").strip().strip('"')
    p = Path(value)

    if p.is_absolute():
        raise ValueError(f"Absolute paths are not allowed in generated files: {value}")

    if ".." in p.parts:
        raise ValueError(f"Path traversal is not allowed: {value}")

    if p.name.strip() == "":
        raise ValueError(f"Invalid path: {value}")

    ext = p.suffix.lower()
    if ext not in ALLOWED_EXTENSIONS:
        raise ValueError(f"Extension not allowed: {ext}")

    return p

