            or result.get("task_status")
            or ""
        ).strip().lower()

        if status and status != last_status:
            last_status = status
            emit({
                "type": "status",
                "id": request_id,
                "provider": "voicebox",
                "profile": profile_name,
                "status": status,
            })

        if status in {
            "completed",
            "complete",
            "done",
            "succeeded",
            "success",
            "ready",
            "finished",
        }:
            return result

        if status in {
            "failed",
            "error",
            "cancelled",
            "canceled",
        }:
            message = (
                result.get("error")
                or result.get("message")
                or result.get("detail")
                or f"Voicebox generation ended with status: {status}"
            )
            raise RuntimeError(str(message))

        time.sleep(0.35)

    raise TimeoutError("Voicebox did not finish speaking within 15 minutes.")


def speak_with_voicebox(
    text: str,
    base_url: str,
    profile_id: str,
    profile_name: str,
    client_id: str,
    personality: bool,
    language: str,
    engine: str,
    request_id: str,
) -> dict:
    payload = {
        "text": text,
        "profile": profile_id or profile_name,
        "personality": bool(personality),
        "language": language or "en",
    }

    if engine:
        payload["engine"] = engine

    response = request_json(
        base_url.rstrip("/") + "/speak",
        method="POST",
        payload=payload,
        headers={"X-Voicebox-Client-Id": client_id},
        timeout=30.0,
    )

    generation_id = str(
        response.get("generation_id")
        or response.get("id")
        or response.get("task_id")
        or ""
    ).strip()

    poll_url = str(response.get("poll_url") or "").strip()

    emit({
        "type": "audio_ready",
        "id": request_id,
        "provider": "voicebox",
        "profile": response.get("profile") or profile_name or profile_id,
        "generation_id": generation_id,
    })

    if generation_id:
        poll_generation(
            base_url=base_url,
            generation_id=generation_id,
            poll_url=poll_url,
            request_id=request_id,
            profile_name=profile_name or profile_id,
        )

    return response


def main() -> int:
    emit({
        "type": "ready",
        "provider": "voicebox",
        "fallback": "disabled",
    })

    for raw in sys.stdin:
        raw = raw.strip()
        if not raw:
            continue

        try:
            request_data = json.loads(raw)
        except Exception:
            emit({"type": "error", "error": "Invalid JSON request."})
            continue

        request_id = str(request_data.get("id") or "")
        command = str(request_data.get("command") or "speak").lower()

        if command == "shutdown":
            emit({"type": "shutdown", "id": request_id})
            return 0

        if command == "stop":
            emit({
                "type": "stopped",
                "id": request_id,
                "note": "Voicebox owns playback; active generation will finish normally.",
            })
            continue

        text = str(request_data.get("text") or "").strip()
        if not text:
            emit({
                "type": "error",
                "id": request_id,
                "error": "Empty speech text.",
            })
            continue

        try:
            config = load_json(CONFIG_PATH, {})
            if not isinstance(config, dict):
                config = {}

            base_url = str(
                config.get("voicebox_url")
                or VOICEBOX_DEFAULT_URL
            ).rstrip("/")

            if not voicebox_health(base_url):
                raise ConnectionError(
                    "Voicebox is not running at "
                    + base_url
                    + ". Open Voicebox and try SPEAK LAST."
                )

            profile_id, profile_name = select_profile(config, base_url)

            client_id = str(
                config.get("voicebox_client_id")
                or "acs-brain"
            ).strip()

