def _dkconn_connect(self):
    """
    Check or wake Z: only.
    Never launch GoogleDriveFS.exe.
    """
    state = _dkconn_state(self)
    target = state.get("target")

    if state.get("state") == "connected":
        try:
            self.set_status(
                "Z: is connected — refreshing library"
            )
        except Exception:
            pass

        _dkconn_refresh_library(self)
        _dkconn_check(self, False)
        return

    try:
        self._dkconn_connect_button.configure(
            text="CHECKING Z:…",
            state="disabled",
        )
        self._dkconn_label.configure(
            text="CHECKING Z: — waiting for the mounted drive…"
        )
    except Exception:
        pass

    def worker():
        _dkz_open_root()
        deadline = _dkz_time.monotonic() + 30.0

        while _dkz_time.monotonic() < deadline:
            try:
                if target.is_dir():
