                            self.set_status(
                                "Z: connected — refreshing library"
                            )
                            _dkconn_refresh_library(self)
                        except Exception:
                            pass

                    self.root.after(0, connected)
                    return

                if _DKZ_ROOT.is_dir():
                    def root_available():
                        try:
                            self._dkconn_connect_button.configure(
                                state="normal"
                            )
                            _dkconn_check(self, False)
                        except Exception:
                            pass

                    self.root.after(0, root_available)
                    return
            except Exception:
                pass

            _dkz_time.sleep(1.0)

        def failed():
            try:
                self._dkconn_connect_button.configure(
                    state="normal"
                )
                _dkconn_check(self, False)
                _dkz_messagebox.showwarning(
                    "Z: Drive Disconnected",
