                    "Google Drive for Desktop was not launched.\n\n"
                    "Mount Z:, then click CONNECT Z: again.\n\n"
                    f"Configured media folder:\n{target}",
                    parent=self.root,
                )
            except Exception:
                pass

        self.root.after(0, failed)

    _dkz_threading.Thread(
        target=worker,
        daemon=True,
    ).start()


