        **hidden_options(),
    )
    raise SystemExit(0)


def find_pythonw() -> Path:
    current = Path(sys.executable)
    local = Path(os.environ.get("LOCALAPPDATA", ""))

    candidates = [
        current.with_name("pythonw.exe"),
