    )
    os.replace(temporary, path)


def old_primary_path(config: dict) -> str:
    for key in (
        "connection_path",
        "download_dir",
        "media_storage_path",
    ):
        value = str(config.get(key) or "").strip()
        if value:
            return value

    for value in config.get("local_roots") or []:
        value = str(value or "").strip()
        if value:
            return value

    return ""


def relative_after_my_drive(value: str) -> str:
    normalized = value.replace("/", "\\")
    marker = "\\My Drive\\"
    position = normalized.lower().find(marker.lower())

    if position >= 0:
        return normalized[position + len(marker):].strip("\\")

    drive, tail = os.path.splitdrive(normalized)
    return tail.strip("\\") if drive else normalized.strip("\\")


def unique_candidates(config: dict) -> list[Path]:
    old = old_primary_path(config)
    relative = relative_after_my_drive(old) if old else ""

    candidates: list[Path] = []

    if relative:
        candidates.extend(
            [
                Z_ROOT / relative,
                Z_ROOT / "My Drive" / relative,
            ]
        )

    candidates.extend(
        [
            Z_ROOT / "RD_DOWNLOADS",
            Z_ROOT / "My Drive" / "RD_DOWNLOADS",
            Z_ROOT / "Media",
            Z_ROOT / "Videos",
            Z_ROOT,
        ]
    )

    result: list[Path] = []
    seen: set[str] = set()

    for candidate in candidates:
        key = os.path.normcase(os.path.normpath(str(candidate)))
        if key in seen:
            continue
        seen.add(key)
        result.append(candidate)

    return result


def directory_score(path: Path, preferred_index: int) -> tuple[int, int, int]:
    try:
        exists = path.is_dir()
    except Exception:
        exists = False

    if not exists:
        return (0, 0, -preferred_index)

    try:
        entries = list(path.iterdir())
        media_count = sum(
            1
            for item in entries[:500]
            if item.is_file()
            and item.suffix.lower()
            in {
                ".mp4", ".mkv", ".avi", ".mov", ".webm",
                ".json", ".jpg", ".jpeg", ".png",
            }
        )
        total = len(entries)
    except Exception:
        media_count = 0
        total = 0

    return (2 if media_count else 1, media_count + total, -preferred_index)


def detect_target(config: dict) -> Path:
    candidates = unique_candidates(config)
    ranked = sorted(
        enumerate(candidates),
        key=lambda row: directory_score(row[1], row[0]),
        reverse=True,
    )

    if ranked and ranked[0][1].is_dir():
        return ranked[0][1]

    old = old_primary_path(config)
    relative = relative_after_my_drive(old) if old else "RD_DOWNLOADS"
    return Z_ROOT / (relative or "RD_DOWNLOADS")


def replace_prefix(value, old_prefix: str, new_prefix: str):
    if isinstance(value, dict):
        return {
            key: replace_prefix(item, old_prefix, new_prefix)
            for key, item in value.items()
        }

    if isinstance(value, list):
        return [
            replace_prefix(item, old_prefix, new_prefix)
            for item in value
        ]

    if not isinstance(value, str):
        return value

    text = value.strip()

    if not old_prefix:
        return value

    old_norm = os.path.normcase(
        os.path.normpath(old_prefix)
    )
    value_norm = os.path.normcase(
        os.path.normpath(text)
    )

    if value_norm == old_norm:
        return new_prefix

    old_with_sep = old_norm.rstrip("\\/") + os.sep
    if value_norm.startswith(old_with_sep):
        suffix = text[len(old_prefix.rstrip("\\/")):].lstrip("\\/")
        return str(Path(new_prefix) / suffix)

    return value


def update_config(config: dict, target: Path) -> tuple[dict, list[str]]:
    old = old_primary_path(config)
    updated = replace_prefix(
        config,
        old,
        str(target),
    )

    changes: list[str] = []

    for key in (
        "connection_path",
        "download_dir",
        "media_storage_path",
    ):
        previous = str(updated.get(key) or "")
        if previous != str(target):
            updated[key] = str(target)
            changes.append(f"{key}: {previous or '(blank)'} -> {target}")

    if not bool(updated.get("rd_only_mode", False)):
        roots = [
            str(value)
            for value in updated.get("local_roots") or []
            if str(value).strip()
        ]

        normalized_target = os.path.normcase(
            os.path.normpath(str(target))
        )
