                os.path.normpath(value)
            )

            # Remove stale G: roots that point at the old mount.
            if normalized.startswith("g:" + os.sep):
                continue

            if normalized in seen:
                continue

            seen.add(normalized)
            filtered.append(value)

        if normalized_target not in seen:
            filtered.append(str(target))

        updated["local_roots"] = filtered

    updated["storage_drive"] = "Z:"
