        if value:
            candidates.append(value)

    for value in config.get("local_roots") or []:
        value = str(value or "").strip()
        if value:
            candidates.append(value)

    # Prefer a configured remote or virtual drive, especially Google Drive.
    for value in candidates:
        if _dkconn_is_remote_style(value):
            return _DKConnPath(value)

    # A manually chosen local location can still be checked and opened.
