def _dkconn_drive_root(path):
    if path is None:
        return None

    text = str(path)

    if text.startswith("\\\\"):
        parts = [
            part
            for part in text.strip("\\").split("\\")
            if part
        ]
        if len(parts) >= 2:
            return _DKConnPath(
                "\\\\" + parts[0] + "\\" + parts[1] + "\\"
            )
        return path

    drive, _tail = _dkconn_os.path.splitdrive(text)
    if drive:
        return _DKConnPath(drive + "\\")

    return path


