            ),
        }

    root = _dkconn_drive_root(target)

    try:
        root_exists = bool(root and root.exists())
    except Exception:
        root_exists = False

    try:
        target_exists = target.exists()
    except Exception:
        target_exists = False

    if target_exists:
        return {
            "state": "connected",
            "target": target,
            "root": root,
            "message": f"MEDIA STORAGE CONNECTED — {target}",
        }

    if root_exists:
        return {
            "state": "folder_missing",
            "target": target,
            "root": root,
            "message": (
                "MEDIA DRIVE CONNECTED, BUT FOLDER IS MISSING — "
                + str(target)
            ),
        }

    return {
        "state": "disconnected",
        "target": target,
        "root": root,
        "message": (
            "MEDIA DRIVE DISCONNECTED — library may appear empty — "
