import argparse
import json
import urllib.error
import urllib.request
from pathlib import Path
from typing import Any, Dict, List, Optional

HERE = Path(__file__).resolve().parent
CONFIG_PATH = HERE / "acs_llm_config.json"

PLAN_SCHEMA: Dict[str, Any] = {
    "type": "object",
    "properties": {
        "summary": {"type": "string"},
        "action": {
            "type": "string",
            "enum": ["respond", "request_registered_job", "request_clarification", "refuse"]
        },
        "tool_or_job": {"type": ["string", "null"]},
        "arguments": {"type": "object"},
        "requires_approval": {"type": "boolean"},
        "risk": {"type": "string", "enum": ["none", "low", "medium", "high"]},
        "reason": {"type": "string"},
        "user_message": {"type": "string"}
    },
    "required": [
        "summary", "action", "tool_or_job", "arguments",
        "requires_approval", "risk", "reason", "user_message"
    ],
    "additionalProperties": False
}


def load_config() -> Dict[str, Any]:
    return json.loads(CONFIG_PATH.read_text(encoding="utf-8"))


def post_json(url: str, payload: Dict[str, Any], timeout: int) -> Dict[str, Any]:
    request = urllib.request.Request(
        url,
        data=json.dumps(payload).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"Ollama HTTP {exc.code}: {detail}") from exc
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Ollama is unreachable: {exc.reason}") from exc


def ask_acs(
    prompt: str,
    mode: str = "chat",
    history: Optional[List[Dict[str, str]]] = None,
) -> Dict[str, Any]:
    cfg = load_config()
    messages: List[Dict[str, str]] = []

    if history:
        for item in history:
            role = item.get("role")
            content = item.get("content")
            if role in {"user", "assistant", "system", "tool"} and isinstance(content, str):
                messages.append({"role": role, "content": content})

    user_text = prompt
    if mode == "plan":
        user_text = (
            "Create a safe ACS action plan. Do not execute anything. "
            "Only request a registered job when its real name is provided. "
            "Otherwise request clarification.\n\nUSER REQUEST:\n" + prompt
        )
    elif mode != "chat":
        raise ValueError("mode must be chat or plan")

    messages.append({"role": "user", "content": user_text})

    payload: Dict[str, Any] = {
        "model": cfg["model"],
        "messages": messages,
        "stream": False,
        "think": False,
        "options": {
            "temperature": cfg.get("temperature", 0.2),
            "num_ctx": cfg.get("context_length", 8192),
        },
    }

    if mode == "plan":
        payload["format"] = PLAN_SCHEMA

    raw = post_json(
        str(cfg["ollama_url"]).rstrip("/") + "/api/chat",
        payload,
        int(cfg.get("timeout_seconds", 300)),
    )
    content = str((raw.get("message") or {}).get("content", "")).strip()
    if not content:
        raise RuntimeError("Ollama returned an empty response.")

    result: Dict[str, Any] = {
        "ok": True,
        "mode": mode,
        "model": cfg["model"],
        "response": content,
    }

    if mode == "plan":
        try:
            result["plan"] = json.loads(content)
        except json.JSONDecodeError as exc:
            result["ok"] = False
            result["error"] = f"Invalid plan JSON: {exc}"

    return result


def main() -> int:
    parser = argparse.ArgumentParser(description="ACS local Ollama bridge")
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("--test", action="store_true")
    group.add_argument("--ask")
    group.add_argument("--plan")
    parser.add_argument("--pretty", action="store_true")
    args = parser.parse_args()

    try:
        if args.test:
            result = ask_acs("Reply with exactly: ACS LLM ONLINE")
        elif args.ask is not None:
            result = ask_acs(args.ask, "chat")
        else:
            result = ask_acs(args.plan, "plan")

        print(json.dumps(result, indent=2 if args.pretty else None, ensure_ascii=False))
        return 0 if result.get("ok") else 2
    except Exception as exc:
        print(json.dumps({"ok": False, "error": str(exc)}, indent=2))
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

