def acquire_lock(job_name: str) -> Path:
    lock = LOCK_DIR / f"{job_name}.lock"

    if lock.exists():
        try:
            age = time.time() - lock.stat().st_mtime
            if age < 6 * 60 * 60:
                raise RuntimeError(
                    f"Job '{job_name}' already appears to be running."
                )
        except OSError:
            pass

    lock.write_text(
        json.dumps(
            {"pid": os.getpid(), "started": now_text()},
            indent=2,
        ),
        encoding="utf-8",
    )
    return lock


def run_process(
    executable: Path,
    arguments: list[str],
    timeout_seconds: int,
    wait: bool,
    working_directory: str | None = None,
) -> dict:
    command = [str(executable), *[str(item) for item in arguments]]
    cwd = None

    if working_directory:
        cwd_path = Path(working_directory)
        if not cwd_path.is_absolute() or not cwd_path.is_dir():
            raise ValueError(
                f"Working directory is invalid: {working_directory}"
            )
        cwd = str(cwd_path)

    if wait:
        completed = subprocess.run(
            command,
            cwd=cwd,
            capture_output=True,
            text=True,
            errors="replace",
            creationflags=CREATE_NO_WINDOW,
            timeout=max(1, min(timeout_seconds, 3600)),
            check=False,
        )
        return {
            "command": command,
            "returncode": completed.returncode,
            "stdout": (completed.stdout or "").strip(),
            "stderr": (completed.stderr or "").strip(),
        }

    process = subprocess.Popen(
        command,
        cwd=cwd,
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        creationflags=CREATE_NO_WINDOW,
        close_fds=True,
    )
    return {"command": command, "pid": process.pid}


def execute_action(action: dict, context: dict) -> dict:
    action_type = str(action.get("type", "")).strip()

    if action_type == "write_status":
        message = str(action.get("message", "OK"))
        context["notes"].append(message)
        return {"type": action_type, "message": message}

    if action_type == "sleep":
        seconds = float(action.get("seconds", 0))
        if seconds < 0 or seconds > 3600:
            raise ValueError("Sleep must be between 0 and 3600 seconds.")
        time.sleep(seconds)
        return {"type": action_type, "seconds": seconds}

    if action_type == "open_uri":
        uri = str(action.get("uri", "")).strip()
        parsed = urlparse(uri)
        if parsed.scheme.lower() not in ALLOWED_URI_SCHEMES:
            raise ValueError(f"URI scheme is not permitted: {parsed.scheme}")
        os.startfile(uri)
        return {"type": action_type, "uri": uri}

    if action_type == "open_file":
        path = absolute_existing_file(str(action.get("path", "")))
        os.startfile(str(path))
        return {"type": action_type, "path": str(path)}

    if action_type == "run_process":
        executable = absolute_existing_file(
            str(action.get("executable", ""))
        )
        args = action.get("args", [])
        if not isinstance(args, list):
            raise ValueError("run_process args must be a JSON list.")
        timeout_seconds = int(action.get("timeout_seconds", 120))
        wait = bool(action.get("wait", True))
        return {
            "type": action_type,
            "result": run_process(
                executable,
                [str(item) for item in args],
                timeout_seconds,
                wait,
                action.get("working_directory"),
            ),
        }

    if action_type == "python_script":
        python_exe = absolute_existing_file(
            str(action.get("python", ""))
        )
        script = absolute_existing_file(
            str(action.get("script", ""))
        )
        if script.suffix.lower() not in {".py", ".pyw"}:
            raise ValueError("python_script requires a .py or .pyw file.")
        args = action.get("args", [])
        if not isinstance(args, list):
            raise ValueError("python_script args must be a JSON list.")
        result = run_process(
            python_exe,
            [str(script), *[str(item) for item in args]],
            int(action.get("timeout_seconds", 300)),
            bool(action.get("wait", False)),
            action.get("working_directory"),
        )
        return {"type": action_type, "result": result}

    if action_type == "soundvolumeview":
        tool = absolute_existing_file(str(action.get("tool", "")))
        device = str(action.get("device_match", "LG")).strip()
        volume = max(0, min(100, int(action.get("volume", 80))))

        commands = [
            [str(tool), "/SetDefault", device, "all"],
            [str(tool), "/Unmute", device],
            [str(tool), "/SetVolume", device, str(volume)],
            [str(tool), "/Unmute", "DefaultRenderDevice"],
            [
                str(tool),
                "/SetVolume",
                "DefaultRenderDevice",
                str(volume),
            ],
        ]

        result

