def snapshot() -> list[dict]:
    script = r"""
$items = Get-CimInstance Win32_Process -ErrorAction SilentlyContinue |
    Where-Object {
        $_.Name -ieq 'rclone.exe' -or
        $_.Name -ieq 'zurg.exe' -or
        (
            $_.Name -match '^(python|pythonw)\.exe$' -and
            $_.CommandLine -match '(?i)(PLAYER_.*RD|RD_.*PLAYER|Media Control.*PLAYER)'
        )
    } |
    ForEach-Object {
        $gp = Get-Process -Id $_.ProcessId -ErrorAction SilentlyContinue
        [PSCustomObject]@{
            Name = $_.Name
            PID = $_.ProcessId
            CommandLine = [string]$_.CommandLine
            MemoryMB = if ($gp) {[math]::Round($gp.WorkingSet64 / 1MB, 1)} else {0}
        }
    }
@($items) | ConvertTo-Json -Compress
"""
    result = run_ps(script)
    if result.returncode != 0 or not result.stdout.strip():
        return []
    try:
        data = json.loads(result.stdout)
        if isinstance(data, dict):
            return [data]
        return data if isinstance(data, list) else []
    except Exception:
        return []


def stop_stack(include_player: bool) -> list[str]:
    player_test = ""
    if include_player:
        player_test = r"""
        -or (
            $_.Name -match '^(python|pythonw)\.exe$' -and
            $_.CommandLine -match '(?i)(PLAYER_.*RD|RD_.*PLAYER|Media Control.*PLAYER)'
        )
"""
    script = rf"""
$targets = Get-CimInstance Win32_Process -ErrorAction SilentlyContinue |
    Where-Object {{
        $_.Name -ieq 'rclone.exe' -or
        $_.Name -ieq 'zurg.exe'
        {player_test}
    }}
$stopped = @()
foreach ($item in $targets) {{
    try {{
        Stop-Process -Id $item.ProcessId -Force -ErrorAction Stop
        $stopped += "$($item.Name) PID $($item.ProcessId)"
    }} catch {{}}
}}
@($stopped) | ConvertTo-Json -Compress
"""
    result = run_ps(script)
    if not result.stdout.strip():
        return []
    try:
        data = json.loads(result.stdout)
        if isinstance(data, str):
            return [data]
        return data if isinstance(data, list) else []
    except Exception:
        return []


def launch(path_text: str) -> tuple[bool, str]:
    if not path_text:
        return False, "not configured"

    path = Path(path_text)
    if not path.is_file():
        return False, f"not found: {path}"

    try:
        suffix = path.suffix.lower()
        if suffix == ".ps1":
            command = [
                "powershell.exe",
                "-NoProfile",
                "-ExecutionPolicy",
                "Bypass",
                "-WindowStyle",
                "Hidden",
                "-File",
                str(path),
            ]
        elif suffix in {".cmd", ".bat"}:
            command = ["cmd.exe", "/d", "/c", str(path)]
        elif suffix in {".py", ".pyw"}:
            python = Path(sys.executable)
            if suffix == ".pyw":
                candidate = python.with_name("pythonw.exe")
                if candidate.is_file():
                    python = candidate
            command = [str(python), str(path)]
        else:
            command = [str(path)]

        subprocess.Popen(
            command,
            cwd=str(path.parent),
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            creationflags=CREATE_NO_WINDOW | DETACHED_PROCESS,
            close_fds=True,
        )
        return True, str(path)
    except Exception as exc:
        return False, f"{type(exc).__name__}: {exc}"


def show_osd(title: str, lines: list[str], seconds: float = 6.0) -> None:
    try:
        root = tk.Tk()
        root.overrideredirect(True)
        root.attributes("-topmost", True)
        root.configure(bg="#080b10")

        frame = tk.Frame(
            root,
            bg="#080b10",
            highlightbackground="#00e5ff",
            highlightthickness=2,
            padx=18,
            pady=14,
        )
        frame.pack(fill="both", expand=True)

        tk.Label(
            frame,
            text=title,
            bg="#080b10",
            fg="#00e5ff",
            font=("Segoe UI", 17, "bold"),
            anchor="w",
        ).pack(fill="x")

        tk.Label(
            frame,
            text="\n".join(lines),
            bg="#080b10",
            fg="white",
            font=("Segoe UI", 12),
            justify="left",
            anchor="w",
            pady=8,
        ).pack(fill="both", expand=True)

        root.update_idletasks()
        width = min(max(root.winfo_reqwidth(), 500), 850)
        height = min(max(root.winfo_reqheight(), 155), 430)
        x = 35
        y = max(90, root.winfo_screenheight() - height - 90)
        root.geometry(f"{width}x{height}+{x}+{y}")
        root.after(int(seconds * 1000), root.destroy)
        root.mainloop()
    except Exception:
        pass


def status_lines() -> tuple[str, list[str]]:
    rows = snapshot()
    stack_running = any(
        str(item.get("Name", "")).lower() in {"rclone.exe", "zurg.exe"}
        for item in rows
    )
    state = "RUNNING" if stack_running else "PAUSED"
    lines = [f"RD mount stack: {state}"]

    if not rows:
        lines.append("No Zurg, rclone, or matching RD player process is running.")
        return state, lines

    total = sum(float(item.get("MemoryMB", 0) or 0) for item in rows)
    lines.append(f"Matched RAM use: {total:.1f} MB")

    for item in sorted(
        rows,
        key=lambda row: float(row.get("MemoryMB", 0) or 0),
        reverse=True,
    ):
        lines.append(
            f"{item.get('Name', '?')}  PID {item.get('PID', '?')}  "
            f"{float(item.get('MemoryMB', 0) or 0):.1f} MB"
        )
    return state, lines


