function Test-TermMatch {
    param([string]$Text)
    if ([string]::IsNullOrWhiteSpace($Text)) { return $false }
    foreach ($term in $terms) {
        if ($Text.IndexOf($term, [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
            return $true
        }
    }
    return $false
}

function Normalize-PathCandidate {
    param([string]$Value)
    if ([string]::IsNullOrWhiteSpace($Value)) { return '' }
    $value = [Environment]::ExpandEnvironmentVariables($Value.Trim())
    if ($value.StartsWith('"')) {
        $secondQuote = $value.IndexOf('"', 1)
        if ($secondQuote -gt 1) {
            return $value.Substring(1, $secondQuote - 1)
        }
    }
    $match = [regex]::Match($value, '^[A-Z]:\\[^\s"]+\.(?:exe|cmd|bat|py|pyw)', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
    if ($match.Success) { return $match.Value }
    return $value.Trim('"')
}

function Read-RegValues {
    param([string]$Path)
    $rows = @()
    try {
        $item = Get-ItemProperty -LiteralPath $Path -ErrorAction Stop
        foreach ($prop in $item.PSObject.Properties) {
            if ($prop.Name -like 'PS*') { continue }
            $rows += [ordered]@{
                key = $Path
                name = $prop.Name
                value = [string]$prop.Value
            }
        }
    } catch {
    }
    return $rows
}

