    return $null -ne $process
}

function Hide-AcsWindows {
    $signature = @'
using System;
using System.Text;
using System.Runtime.InteropServices;

public static class Win32AcsWindow {
    public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);

    [DllImport("user32.dll")]
    public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);

    [DllImport("user32.dll")]
    public static extern int GetWindowText(IntPtr hWnd, StringBuilder text, int count);

    [DllImport("user32.dll")]
    public static extern int GetWindowTextLength(IntPtr hWnd);

    [DllImport("user32.dll")]
    public static extern bool IsWindowVisible(IntPtr hWnd);

    [DllImport("user32.dll")]
    public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
}
'@
    try {
        if (-not ('Win32AcsWindow' -as [type])) {
            Add-Type -TypeDefinition $signature
        }
        [Win32AcsWindow]::EnumWindows({
            param([IntPtr]$hwnd, [IntPtr]$lparam)
            if ([Win32AcsWindow]::IsWindowVisible($hwnd)) {
                $length = [Win32AcsWindow]::GetWindowTextLength($hwnd)
                if ($length -gt 0) {
                    $builder = New-Object System.Text.StringBuilder ($length + 1)
                    [void][Win32AcsWindow]::GetWindowText($hwnd, $builder, $builder.Capacity)
                    $title = $builder.ToString()
                    if ($title -match 'Automation Creation Station|ACS v[0-9]|DK ACS') {
                        [void][Win32AcsWindow]::ShowWindow($hwnd, 6)
                        Start-Sleep -Milliseconds 60
                        [void][Win32AcsWindow]::ShowWindow($hwnd, 0)
                    }
                }
            }
            return $true
        }, [IntPtr]::Zero) | Out-Null
    } catch {
    }
}

Write-GuardLog 'ACS minimized startup guard beginning.'

if ((Test-Path -LiteralPath $pythonw) -and (Test-Path -LiteralPath $canonicalLauncher)) {
