}

Start-Sleep -Seconds 3

if ((Test-Path -LiteralPath $pythonw) -and (Test-Path -LiteralPath $trayController)) {
    if (-not (Test-CommandLineContains $trayController)) {
        Start-Process -FilePath $pythonw -ArgumentList "`"$trayController`"" -WorkingDirectory (Split-Path -Parent $trayController) -WindowStyle Hidden
        Write-GuardLog 'Tray controller started.'
    } else {
        Write-GuardLog 'Tray controller already active.'
    }
}

$deadline = (Get-Date).AddSeconds(120)
while ((Get-Date) -lt $deadline) {
    Hide-AcsWindows
    Start-Sleep -Milliseconds 750
}

Write-GuardLog 'ACS minimized startup guard finished.'

