#!/usr/bin/env python3
from __future__ import annotations

import ctypes
import json
import socket
import subprocess
import sys
import time
from datetime import datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parent
CONFIG_PATH = ROOT / "ACS_CANONICAL_CONFIG.json"
MUTEX_NAME = r"Global\DK_ACS_CANONICAL_LAUNCHER_V1"


def log(message: str) -> None:
    line = f"{datetime.now().astimezone().isoformat(timespec='seconds')}  {message}\n"
    try:
        with (ROOT / "ACS_CANONICAL_LAUNCHER.log").open("a", encoding="utf-8") as handle:
            handle.write(line)
    except Exception:
        pass


def acquire_single_instance():
    kernel32 = ctypes.windll.kernel32
    handle = kernel32.CreateMutexW(None, False, MUTEX_NAME)
    if not handle:
        return None, False
    return handle, kernel32.GetLastError() != 183


def port_is_listening(port):
    if not port:
        return False
    try:
        with socket.create_connection(("127.0.0.1", int(port)), timeout=0.5):
            return True
    except OSError:
        return False


def commandline_contains(needle: str) -> bool:
    escaped = needle.replace("'", "''")
    script = (
        "$row = Get-CimInstance Win32_Process | "
        "Where-Object { ([string]$_.CommandLine) -like "
        f"'*{escaped}*' }} | Select-Object -First 1 ProcessId; "
        "if ($row) { 'YES' }"
    )
    flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
    try:
        result = subprocess.run(
            [
                "powershell.exe",
                "-NoProfile",
                "-NonInteractive",
                "-ExecutionPolicy",
                "Bypass",
                "-Command",
                script,
            ],
            capture_output=True,
            text=True,
            timeout=8,
            creationflags=flags,
        )
        return "YES" in result.stdout
    except Exception:
        return False


def python_executable(windowless: bool) -> str:
    current = Path(sys.executable)
    if windowless:
        candidate = current.with_name("pythonw.exe")
        if candidate.exists():
            return str(candidate)
    return str(current)


def start_component(component: dict) -> None:
    path = Path(component["path"])
    name = component.get("name", path.name)
    if not path.exists():
        log(f"SKIP missing: {name} -> {path}")
        return False

    expected_port = component.get("expected_port")
    if expected_port and port_is_listening(expected_port):
        log(f"ALREADY ACTIVE by port {expected_port}: {name}")
        return False

    if commandline_contains(str(path)):
        log(f"ALREADY ACTIVE by command line: {name}")
        return False

    start_type = component.get("start_type", "")
    arguments = list(component.get("arguments") or [])
    working_directory = component.get("working_directory") or str(path.parent)
    flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)

    if start_type == "pythonw":
        command = [python_executable(True), str(path), *arguments]
    elif start_type == "python":
        command = [python_executable(False), str(path), *arguments]
    elif start_type == "powershell":
        command = [
            "powershell.exe",
            "-NoProfile",
            "-ExecutionPolicy",
            "Bypass",
            "-File",
            str(path),
            *arguments,
        ]
    elif start_type == "vbs":
        command = ["wscript.exe", str(path), *arguments]
    elif start_type in ("bat", "cmd"):
        command = ["cmd.exe", "/c", str(path), *arguments]
    else:
        command = [str(path), *arguments]

    try:
        subprocess.Popen(
            command,
            cwd=working_directory,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            creationflags=flags,
            close_fds=True,
        )
        log(f"STARTED: {name} -> {path}")
        return True
    except Exception as exc:
        log(f"ERROR starting {name}: {type(exc).__name__}: {exc}")
        return False


def main() -> int:
    mutex_handle, first_instance = acquire_single_instance()
    if not mutex_handle:
        return 2
    if not first_instance:
        return 0

    try:
        config = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
    except Exception as exc:
        log(f"CONFIG ERROR: {type(exc).__name__}: {exc}")
        return 3

    components = sorted(
        config.get("components", []),
        key=lambda item: int(item.get("priority", 999)),
    )
    log("Canonical ACS startup beginning")
    for component in components:
        if not component.get("enabled", True):
            continue

        started = start_component(component)
        expected_port = component.get("expected_port")

        if started and expected_port:
            deadline = time.time() + 20.0
            while time.time() < deadline:
                if port_is_listening(expected_port):
                    log(f"READY on port {expected_port}: {component.get('name')}")
                    break
                time.sleep(0.5)
            else:
                log(
                    f"READY TIMEOUT on port {expected_port}: "
                    f"{component.get('name')}"
                )

            # Allow a multi-service core time to open secondary ports,
            # such as ACS v9 owning both 8770 and 8765.
            time.sleep(2.0)
        else:
            time.sleep(1.2)
    log("Canonical ACS startup finished")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

