from __future__ import annotations

import json
import os
import subprocess
import sys
import time
from datetime import datetime
from pathlib import Path


ROOT = Path(
    r"~\Desktop\Automation Creation Station"
    r"\Tagged Download Auto-Runner"
)
REQUEST_ROOT = ROOT / "Natural Language Requests"
PROCESSED = REQUEST_ROOT / "Processed"
FAILED = REQUEST_ROOT / "Failed"
PENDING = REQUEST_ROOT / "Pending"
STATE_DIR = ROOT / "State"
SEEN_PATH = STATE_DIR / "request_result_notifier_seen.json"
STATUS_PATH = STATE_DIR / "request_result_notifier_status.json"
OSD = ROOT / "DK_TASK_RESULT_OSD.pyw"

POLL_SECONDS = 1.0


def now_iso() -> str:
    return datetime.now().astimezone().isoformat(timespec="seconds")


def load_json(path: Path, default):
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return default


def save_json(path: Path, data) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + ".tmp")
    temp.write_text(
        json.dumps(data, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )
    os.replace(temp, path)


def choose_pythonw() -> Path:
    current = Path(sys.executable)
    if current.name.lower() == "python.exe":
        candidate = current.with_name("pythonw.exe")
        if candidate.is_file():
            return candidate
    return current


def show_osd(status: str, title: str, message: str, report: Path) -> None:
    if not OSD.is_file():
        return

    try:
        subprocess.Popen(
            [
                str(choose_pythonw()),
                str(OSD),
                "--status",
                status,
                "--title",
                title,
                "--message",
                message,
                "--report",
                str(report),
            ],
            stdin=subprocess.DEVNULL,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            creationflags=(
                getattr(subprocess, "CREATE_NO_WINDOW", 0)
                | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
            ),
            close_fds=True,
        )
    except OSError:
        pass


def request_text(data: dict) -> str:
    return str(
        data.get("request")
        or data.get("text")
        or data.get("command")
        or ""
    ).strip()


def result_message(data: dict) -> str:
    return str(
        data.get("result_message")
        or data.get("message")
        or data.get("detail")
        or data.get("error")
        or ""
    ).strip()


def is_uninstall_request(text: str) -> bool:
    lowered = text.lower()
    return any(
        phrase in lowered
        for phrase in (
            "uninstall ",
            "remove software",
            "remove program",
            "delete program",
        )
    )


def move_to_pending(source: Path, data: dict) -> Path:
    PENDING.mkdir(parents=True, exist_ok=True)
    destination = PENDING / source.name

    if destination.exists():
        destination = PENDING / (
            f"{source.stem}_{int(time.time())}{source.suffix}"
        )

    pending_data = {
        **data,
        "task_status": "WAITING_FOR_CONFIRMATION",
        "pending_reason": (
            "Software uninstall is destructive and requires a confirmed "
            "execution plan before ACS removes anything."
        ),
        "moved_to_pending_at": now_iso(),
        "original_result_location": str(source),
    }

    save_json(destination, pending_data)
    return destination


def newest_request_files():
    items = []
    for folder_name, folder in (
        ("PROCESSED", PROCESSED),
        ("FAILED", FAILED),
    ):
        if not folder.is_dir():
            continue

        for path in folder.glob("*.dkrequest.json"):
            try:
                mtime = path.stat().st_mtime
            except OSError:
                continue
            items.append((mtime, folder_name, path))

    items.sort(key=lambda item: item[0])
    return items


def main() -> int:
    for folder in (
        PROCESSED,
        FAILED,
        PENDING,
        STATE_DIR,
    ):
        folder.mkdir(parents=True, exist_ok=True)

    seen_data = load_json(SEEN_PATH, {})
    seen = set(seen_data.get("seen", [])) if isinstance(seen_data, dict) else set()

    while True:
        last_event = {}

        for _mtime, state, path in newest_request_files():
            key = f"{state}:{path.name}"
            if key in seen:
                continue

            data = load_json(path, {})
            if not isinstance(data, dict):
                data = {}

            text = request_text(data)
            message = result_message(data)

            if state == "PROCESSED":
                title = "Task completed"
                body = message or text or path.name
                show_osd("SUCCESS", title, body, path)
                last_event = {
                    "state": "COMPLETED",
                    "request": text,
                    "message": body,
                    "path": str(path),
                    "time": now_iso(),
                }

            elif is_uninstall_request(text):
                pending_path = move_to_pending(path, data)
                body = (
                    "Uninstall request captured. No software was removed. "
                    "The task is waiting for confirmation and a verified "
                    "uninstall plan."
                )
                show_osd(
                    "ATTENTION",
                    "Uninstall waiting for confirmation",
                    body,
                    pending_path,
                )
                last_event = {
                    "state": "WAITING_FOR_CONFIRMATION",
                    "request": text,
                    "message": body,
                    "path": str(pending_path),
                    "time": now_iso(),
                }

            else:
                body = (
                    message
                    or "The current processor does not support this task yet."
                )
                show_osd("FAILED", "Task not completed", body, path)
                last_event = {
                    "state": "FAILED",
                    "request": text,
                    "message": body,
                    "path": str(path),
                    "time": now_iso(),
                }

            seen.add(key)
            save_json(
                SEEN_PATH,
                {
                    "seen": sorted(seen)[-1000:],
                    "updated_at": now_iso(),
                },
            )

        save_json(
            STATUS_PATH,
            {
                "status": "RUNNING",
                "heartbeat": now_iso(),
                "pid": os.getpid(),
                "last_event": last_event,
            },
        )

        time.sleep(POLL_SECONDS)


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
from __future__ import annotations

import ctypes
import json
import os
import subprocess
import sys
import time
import traceback
from datetime import datetime
from pathlib import Path


ROOT = Path(
    r"~\Desktop\Automation Creation Station"
    r"\Tagged Download Auto-Runner"
)
WATCHER = ROOT / "DK_TAGGED_DOWNLOAD_AUTORUNNER.pyw"
STATUS = ROOT / "State" / "activity_status.json"
GUARDIAN_STATUS = ROOT / "State" / "watcher_guardian_status.json"
GUARDIAN_LOG = ROOT / "Logs" / "watcher_guardian.log"
OSD = ROOT / "DK_TASK_RESULT_OSD.pyw"

MUTEX_NAME = r"Local\DK_TAGGED_WATCHER_GUARDIAN_V1"
CHECK_SECONDS = 5.0
STALE_RESTART_SECONDS = 60.0
RESTART_COOLDOWN_SECONDS = 20.0


def now_iso() -> str:
    return datetime.now().astimezone().isoformat(timespec="seconds")


def log(message: str) -> None:
    try:
        GUARDIAN_LOG.parent.mkdir(parents=True, exist_ok=True)
        with GUARDIAN_LOG.open("a", encoding="utf-8") as handle:
            handle.write(f"{now_iso()}  {message}\n")
    except OSError:
        pass


def atomic_json(path: Path, data: object) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix + ".tmp")
    temp.write_text(
        json.dumps(data, indent=2, ensure_ascii=False),
        encoding="utf-8",
    )
    os.replace(temp, path)


def load_json(path: Path, default):
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return default


def heartbeat_age() -> float | None:
    data = load_json(STATUS, {})
    if not isinstance(data, dict):
        return None

    value = str(data.get("heartbeat", "")).strip()
    if not value:
        return None

    try:
        stamp = datetime.fromisoformat(value)
        return max(
            0.0,
            (datetime.now(stamp.tzinfo) - stamp).total_seconds(),
        )
    except (ValueError, TypeError):
        return None


def acquire_mutex():
    kernel32 = ctypes.windll.kernel32
    handle = kernel32.CreateMutexW(None, False, MUTEX_NAME)

    if not handle:
        raise RuntimeError("Unable to create guardian mutex.")

    if kernel32.GetLastError() == 183:
        kernel32.CloseHandle(handle)
        raise SystemExit(0)

    return handle


def choose_pythonw() -> Path:
    candidates = [
        Path(sys.executable),
        Path(
            r"~\AppData\Local\Programs"
            r"\Python\Python312\pythonw.exe"
        ),
        Path(
            r"~\AppData\Local\Programs"
            r"\Python\Python314\pythonw.exe"
        ),
    ]

    for item in candidates:
        if item.name.lower() == "python.exe":
            pyw = item.with_name("pythonw.exe")
            if pyw.is_file():
                return pyw
        if item.is_file():
            return item

    return Path(sys.executable)


def powershell(script: str) -> subprocess.CompletedProcess[str]:
    return subprocess.run(
        [
            "powershell.exe",
            "-NoLogo",
            "-NoProfile",
            "-NonInteractive",
            "-ExecutionPolicy",
            "Bypass",
            "-Command",
            script,
        ],
        text=True,
        capture_output=True,
        timeout=30,
        creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        check=False,
    )


def watcher_processes() -> list[dict]:
    watcher = str(WATCHER).replace("'", "''")
    script = f"""
$items = Get-CimInstance Win32_Process | Where-Object {{
    $_.Name -match '^python(w)?[.]exe$' -and
    $_.CommandLine -and
    $_.CommandLine.IndexOf(
        '{watcher}',
        [System.StringComparison]::OrdinalIgnoreCase
    ) -ge 0
}} | Select-Object ProcessId, Name, CommandLine

$items | ConvertTo-Json -Depth 3 -Compress
"""
    completed = powershell(script)
    output = completed.stdout.strip()

    if not output:
        return []

    parsed = json.loads(output)
    return parsed if isinstance(parsed, list) else [parsed]


def stop_watcher() -> list[int]:
    watcher = str(WATCHER).replace("'", "''")
    script = f"""
$ids = @()
Get-CimInstance Win32_Process | Where-Object {{
    $_.Name -match '^python(w)?[.]exe$' -and
    $_.CommandLine -and
    $_.CommandLine.IndexOf(
        '{watcher}',
        [System.StringComparison]::OrdinalIgnoreCase
    ) -ge 0
}} | ForEach-Object {{
    $ids += [int]$_.ProcessId
    Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue
}}
$ids | ConvertTo-Json -Compress
"""
    completed = powershell(script)
    output = completed.stdout.strip()

    if not output:
        return []

    parsed = json.loads(output)
    return parsed if isinstance(parsed, list) else [int(parsed)]


def start_watcher() -> int:
    if not WATCHER.is_file():
        raise FileNotFoundError(f"Watcher is missing: {WATCHER}")

    pythonw = choose_pythonw()
    process = subprocess.Popen(
        [str(pythonw), str(WATCHER)],
        cwd=str(ROOT),
        stdin=subprocess.DEVNULL,
