) -> None:
    atomic_json(
        GUARDIAN_STATUS,
        {
            "status": state,
            "message": message,
            "updated_at": now_iso(),
            "pid": os.getpid(),
            "watcher_process_count": len(processes),
            "watcher_processes": processes,
            "heartbeat_age_seconds": age,
            "restart_count": restart_count,
            "stale_restart_seconds": STALE_RESTART_SECONDS,
        },
    )


