    ROOT.mkdir(parents=True, exist_ok=True)
    mutex = acquire_mutex()
    restart_count = 0
    last_restart = 0.0
    log(f"Guardian started. PID={os.getpid()}")

    try:
        while True:
            try:
                processes = watcher_processes()
                age = heartbeat_age()
                reason = ""

                if not processes:
                    reason = "watcher process missing"
                elif age is None:
                    reason = "heartbeat missing"
                elif age > STALE_RESTART_SECONDS:
                    reason = (
                        f"heartbeat stale for {age:.1f} seconds"
                    )

                now_clock = time.monotonic()

                if (
                    reason
                    and now_clock - last_restart
                    >= RESTART_COOLDOWN_SECONDS
                ):
                    old_ids = stop_watcher() if processes else []
                    time.sleep(0.7)
                    new_pid = start_watcher()
                    restart_count += 1
                    last_restart = now_clock

