    text = safe_read(path)
    record: dict[str, Any] = {
        "report": str(path),
        "report_modified_at": datetime.fromtimestamp(
            path.stat().st_mtime
        ).astimezone().isoformat(timespec="seconds"),
    }

    for field in REPORT_FIELDS:
        match = re.search(
            rf"^{re.escape(field)}:\s*(.*)$",
            text,
            re.MULTILINE,
        )
        if match:
            key = field.lower().replace("-", "_").replace(" ", "_")
            record[key] = match.group(1).strip()

    if "status" not in record:
        if "STATUS: SUCCESS" in text:
            record["status"] = "SUCCESS"
        elif "FAILED" in text:
            record["status"] = "FAILED"
        else:
            record["status"] = "UNKNOWN"

    stdout_match = re.search(
        r"\nSTDOUT\n-+\n(.*?)(?:\n\nSTDERR\n-+\n|\Z)",
        text,
        re.DOTALL,
    )
    if stdout_match:
        lines = [
            line.strip()
            for line in stdout_match.group(1).splitlines()
            if line.strip()
        ]
        record["stdout_tail"] = lines[-8:]

    stderr_match = re.search(
        r"\nSTDERR\n-+\n(.*)$",
        text,
        re.DOTALL,
    )
    if stderr_match:
        stderr = stderr_match.group(1).strip()
        if stderr and stderr != "[no stderr]":
            record["stderr_tail"] = stderr.splitlines()[-8:]

    return record


