def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        while True:
            block = handle.read(1024 * 1024)
            if not block:
                break
            digest.update(block)
    return digest.hexdigest()


def candidate_files(config: dict[str, Any]) -> list[Path]:
    folders = [
        Path(value)
        for value in config.get("download_directories", [])
    ]
    prefix = str(config.get("required_prefix", "DK_"))
    tag = str(config.get("autorun_tag", "__DKRUN__"))
    allowed = {
        str(value).casefold()
        for value in config.get(
            "allowed_extensions",
            [".py", ".pyw"],
        )
    }
    ignored = {
        str(value).casefold()
        for value in config.get("ignore_names", [])
    }
    maximum_age_days = float(
        config.get("maximum_age_days", 14)
    )
    cutoff = time.time() - maximum_age_days * 86400

    output: list[Path] = []

    for folder in folders:
        if not folder.is_dir():
            continue
        try:
            items = list(folder.iterdir())
        except Exception:
            continue

        for path in items:
            try:
                if not path.is_file():
                    continue
                if path.name.casefold() in ignored:
                    continue
                if not path.name.startswith(prefix):
                    continue
                if tag not in path.name:
                    continue
                if path.suffix.casefold() not in allowed:
                    continue
                if path.stat().st_mtime < cutoff:
                    continue
                output.append(path)
            except Exception:
                continue

    output.sort(key=lambda path: path.stat().st_mtime)
    return output


def file_is_stable(
    path: Path,
    observed: dict[str, dict[str, Any]],
    stable_seconds: float,
) -> bool:
    key = str(path).casefold()
    try:
        stat = path.stat()
    except Exception:
        observed.pop(key, None)
        return False

    previous = observed.get(key)
    if (
        not isinstance(previous, dict)
        or previous.get("size") != stat.st_size
        or previous.get("mtime_ns") != stat.st_mtime_ns
    ):
        observed[key] = {
            "size": stat.st_size,
            "mtime_ns": stat.st_mtime_ns,
            "stable_since": time.time(),
        }
        return False

    return (
        time.time()
        - float(previous.get("stable_since", time.time()))
    ) >= stable_seconds


