) -> tuple[bool, str]:
    completed = subprocess.run(
        [str(python), "-m", "py_compile", str(script)],
        capture_output=True,
        text=True,
        errors="replace",
        creationflags=CREATE_NO_WINDOW,
        timeout=90,
        check=False,
    )
    details = (
        completed.stderr
        or completed.stdout
        or ""
    ).strip()
    return completed.returncode == 0, redact(details)


def run_script(
    python: Path,
    script: Path,
    timeout_seconds: int,
) -> dict[str, Any]:
    started = time.time()
    environment = os.environ.copy()
    environment["DK_TAGGED_AUTORUN"] = "1"
    environment["DK_AUTOMATED_SCRIPT_RUNNER"] = "1"

    process = subprocess.Popen(
        [str(python), str(script)],
        cwd=str(script.parent),
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        errors="replace",
        env=environment,
        creationflags=CREATE_NO_WINDOW,
    )

    timed_out = False
    try:
        stdout, stderr = process.communicate(
            input="\n" * 30,
            timeout=timeout_seconds,
        )
    except subprocess.TimeoutExpired:
        timed_out = True
        process.kill()
        stdout, stderr = process.communicate()

    return {
        "returncode": process.returncode,
        "timed_out": timed_out,
        "elapsed_seconds": round(time.time() - started, 2),
        "stdout": redact(stdout or ""),
        "stderr": redact(stderr or ""),
    }


def result_message(report: dict[str, Any]) -> str:
    successful = (
        report.get("syntax_ok") is True
        and report.get("returncode") == 0
        and not report.get("timed_out")
    )
    status = "SUCCESS" if successful else "FAILED"

    message = (
        "AUTOMATED TAGGED SCRIPT RESULT\n"
        f"Status: {status}\n"
        f"Tag: {report.get('autorun_tag')}\n"
        f"File: {report.get('file_name')}\n"
        f"Path: {report.get('script_path')}\n"
        f"SHA-256: {report.get('sha256')}\n"
        f"Started: {report.get('started')}\n"
        f"Duration: {report.get('elapsed_seconds')} seconds\n"
        f"Syntax check: {report.get('syntax_ok')}\n"
        f"Exit code: {report.get('returncode')}\n"
        f"Timed out: {report.get('timed_out')}\n"
        f"Full local result: {report.get('result_text_path')}\n\n"
    )

    syntax_details = str(
        report.get("syntax_details", "")
    ).stri

# -*- coding: utf-8 -*-
"""
Relay a local ACS script-run result into the connected ChatGPT conversation.

Uses the already-running localhost-only Chrome DevTools connection created by
the DK ChatGPT ACS Control profile.
"""

from __future__ import annotations

import argparse
import json
import time
import urllib.request
from pathlib import Path
from typing import Any

import websocket

DEBUG_URL = "http://127.0.0.1:9223/json/list"


def get_targets() -> list[dict[str, Any]]:
    with urllib.request.urlopen(DEBUG_URL, timeout=4) as response:
        value = json.loads(response.read().decode("utf-8"))

    output = []
    if isinstance(value, list):
        for target in value:
            if not isinstance(target, dict):
                continue
            url = str(target.get("url", ""))
            if (
                target.get("type") == "page"
                and target.get("webSocketDebuggerUrl")
                and (
                    url.startswith("https://chatgpt.com/")
                    or url.startswith("https://chat.openai.com/")
                )
            ):
                output.append(target)
    return output


class CDP:
    def __init__(self, url: str) -> None:
        self.ws = websocket.create_connection(
            url,
            timeout=8,
            suppress_origin=True,
        )
        self.next_id = 1

    def close(self) -> None:
        try:
            self.ws.close()
        except Exception:
            pass

    def command(
        self,
        method: str,
        params: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        command_id = self.next_id
        self.next_id += 1

        self.ws.send(
            json.dumps(
                {
                    "id": command_id,
                    "method": method,
                    "params": params or {},
                }
            )
        )

        deadline = time.time() + 12
        while time.time() < deadline:
            message = json.loads(self.ws.recv())
            if message.get("id") == command_id:
                return message

        raise TimeoutError(method)

    def evaluate(self, expression: str) -> Any:
        response = self.command(
            "Runtime.evaluate",
            {
                "expression": expression,
                "returnByValue": True,
                "awaitPromise": True,
            },
        )
        if response.get("error"):
            raise RuntimeError(str(response["error"]))

        result = response.get("result", {}).get("result", {})
        if result.get("subtype") == "error":
            raise RuntimeError(
                result.get("description", "JavaScript failed.")
            )
        return result.get("value")


def choose_target(
    targets: list[dict[str, Any]],
) -> dict[str, Any] | None:
    first_chatgpt = None

    for target in targets:
        if first_chatgpt is None:
            first_chatgpt = target

        cdp = None
        try:
            cdp = CDP(str(target["webSocketDebuggerUrl"]))
            connected = cdp.evaluate(
                "Boolean(document.getElementById("
                "'dk-acs-watcher-indicator'))"
            )
            if connected:
                return target
        except Exception:
            pass
        finally:
            if cdp:
                cdp.close()

    return first_chatgpt


def send_message(
    target: dict[str, Any],
    message: str,
) -> bool:
    cdp = CDP(str(target["webSocketDebuggerUrl"]))
    try:
        message_json = json.dumps(message)
        expression = f"""
(async () => {{
  const sleep = (ms) => new Promise(resolve => setTimeout(resolve, ms));

  const composer =
    document.querySelector('#prompt-textarea') ||
    document.querySelector('textarea[placeholder]') ||
    document.querySelector('textarea') ||
    document.querySelector('[contenteditable="true"][data-lexical-editor="true"]') ||
    document.querySelector('[contenteditable="true"]');

  if (!composer) {{
    return {{ok:false, error:'ChatGPT composer was not found.'}};
  }}

  composer.focus();

  if (composer instanceof HTMLTextAreaElement) {{
    const setter = Object.getOwnPropertyDescriptor(
      HTMLTextAreaElement.prototype,
      'value'
    ).set;
    setter.call(composer, {message_json});
    composer.dispatchEvent(new Event('input', {{bubbles:true}}));
    composer.dispatchEvent(new Event('change', {{bubbles:true}}));
  }} else {{
    const selection = window.getSelection();
    const range = document.createRange();
    range.selectNodeContents(composer);
    selection.removeAllRanges();
    selection.addRange(range);
    document.execCommand('delete', false, null);
    document.execCommand('insertText', false, {message_json});
    composer.dispatchEvent(
      new InputEvent(
        'input',
        {{
          bubbles: true,
          inputType: 'insertText',
          data: {message_json}
        }}
      )
    );
  }}

  await sleep(800);

  for (let attempt = 0; attempt < 12; attempt++) {{
    const sendButton =
      document.querySelector('[data-testid="send-button"]') ||
      document.querySelector('button[aria-label="Send prompt"]') ||
      document.querySelector('button[aria-label*="Send"]');

    if (sendButton && !sendButton.disabled) {{
      sendButton.click();
      return {{ok:true, method:'button'}};
    }}

    await sleep(350);
  }}

  composer.dispatchEvent(
    new KeyboardEvent(
      'keydown',
      {{
        key: 'Enter',
        code: 'Enter',
        keyCode: 13,
        which: 13,
        bubbles: true
      }}
    )
  );

  await sleep(500);
  return {{ok:true, method:'enter'}};
}})()
"""
        result = cdp.evaluate(expression)
        return bool(
            isinstance(result, dict)
            and result.get("ok")
        )
    finally:
        cdp.close()


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("message_file")
    args = parser.parse_args()

    message_path = Path(args.message_file)
    message = message_path.read_text(
        encoding="utf-8",
        errors="replace",
    )

    targets = get_targets()
    target = choose_target(targets)
    if not target:
        raise RuntimeError(
            "No connected ChatGPT browser tab was found."
        )

    if not send_message(target, message):
        raise RuntimeError(
            "The ChatGPT result message could not be submitted."
        )

    return 0


if __name__ == "__main__":
    raise SystemExit(main())

