﻿from __future__ import annotations

import json
import os
import shutil
import sys
import traceback
from datetime import datetime
from pathlib import Path

USERPROFILE = Path(os.environ.get("USERPROFILE", str(Path.home())))
ACS_ROOT = USERPROFILE / "Desktop" / "Automation Creation Station"
ACTIVE_SCRIPTS = USERPROFILE / "Desktop" / "Active Scripts"

PLUGIN_ROOT = ACS_ROOT / "Plugins" / "DK Local Operator Plugin"
CONFIG = PLUGIN_ROOT / "config"
INBOX = PLUGIN_ROOT / "requests" / "inbox"
PROCESSED = PLUGIN_ROOT / "requests" / "processed"
FAILED = PLUGIN_ROOT / "requests" / "failed"
LOGS = PLUGIN_ROOT / "logs"
REPORTS = PLUGIN_ROOT / "reports"

SAFE_BACKUPS = ACS_ROOT / "_SAFE_BACKUPS" / "DK Local Operator Plugin"
QUARANTINE = ACS_ROOT / "_QUARANTINE" / "DK Local Operator Plugin"

BLOCKED_NAME_PARTS = [
    "password", "passwd", "credential", "credentials", "cookie", "cookies",
    "token", "secret", "secrets", "api_key", "apikey", "gemini_api_key",
    "openai_api_key", ".env", "id_rsa", "id_dsa", "private_key"
]

TEXT_EXTS = {
    ".txt", ".md", ".json", ".csv", ".log", ".py", ".pyw", ".ps1", ".bat",
    ".cmd", ".ahk", ".vbs", ".xml", ".yaml", ".yml", ".ini", ".cfg", ".html",
    ".css", ".js"
}

ALLOWED_ACTIONS = {
    "ping",
    "list_dir",
    "read_text",
    "write_text",
    "append_text",
    "mkdir",
    "copy_file",
    "move_file",
    "backup_file",
    "quarantine_file",
    "touch",
    "file_exists",
    "tree"
}


def now() -> str:
    return datetime.now().strftime("%Y-%m-%d_%H-%M-%S")


def write(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8", newline="")


def log(msg: str) -> None:
    LOGS.mkdir(parents=True, exist_ok=True)
    with (LOGS / "dk_local_operator.log").open("a", encoding="utf-8") as f:
        f.write(f"{datetime.now().isoformat()}  {msg}\n")


def load_allowed_roots() -> list[Path]:
    roots_file = CONFIG / "allowed_roots.json"
    if roots_file.exists():
        try:
            data = json.loads(roots_file.read_text(encoding="utf-8", errors="replace"))
            roots = data.get("allowed_roots", [])
            result = []
            for r in roots:
                p = Path(os.path.expandvars(str(r))).expanduser()
                result.append(p.resolve())
            return result
        except Exception:
            pass

    return [ACS_ROOT.resolve(), ACTIVE_SCRIPTS.resolve()]


def is_under(path: Path, root: Path) -> bool:
    try:
        path.resolve().relative_to(root.resolve())
        return True
    except Exception:
        return False


def has_sensitive_name(path: Path) -> bool:
    s = str(path).lower()
    return any(part in s for part in BLOCKED_NAME_PARTS)


def resolve_path(value: str | None, *, for_write: bool = False, allow_sensitive: bool = False) -> Path:
    if not value:
        raise ValueError("Missing path.")

    raw = Path(os.path.expandvars(str(value))).expanduser()

    if raw.is_absolute():
        p = raw
    else:
        p = ACS_ROOT / raw

    p = p.resolve()
    allowed = load_allowed_roots()

    if not any(is_under(p, r) for r in allowed):
        raise PermissionError(f"Path outside allowed roots: {p}")

    if not allow_sensitive and has_sensitive_name(p):
        raise PermissionError(f"Sensitive-looking path blocked: {p}")

    if ".." in Path(value).parts:
        raise PermissionError(f"Path traversal blocked: {value}")

    return p


def ensure_safe_text_file(path: Path) -> None:
    if path.suffix.lower() not in TEXT_EXTS:
        raise PermissionError(f"Refusing text operation on non-text extension: {path.suffix}")


def backup_file(path: Path) -> Path:
    if not path.exists():
        raise FileNotFoundError(path)
    SAFE_BACKUPS.mkdir(parents=True, exist_ok=True)
    stamp = now()
    rel = path.name
    dest = SAFE_BACKUPS / stamp / rel
    dest.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(path, dest)
    return dest


def op_ping(op: dict) -> dict:
    return {"ok": True, "message": "DK Local Operator alive.", "plugin_root": str(PLUGIN_ROOT)}


def op_file_exists(op: dict) -> dict:
    p = resolve_path(op.get("path"), allow_sensitive=True)
    return {"path": str(p), "exists": p.exists(), "is_file": p.is_file(), "is_dir": p.is_dir()}


def op_list_dir(op: dict) -> dict:
    p = resolve_path(op.get("path") or ".", allow_sensitive=True)
    if not p.exists():
        raise FileNotFoundError(p)
    if not p.is_dir():
        raise NotADirectoryError(p)

    limit = int(op.get("limit", 200))
    items = []
    for child in sorted(p.iterdir(), key=lambda x: (not x.is_dir(), x.name.lower()))[:limit]:
        items.append({
            "name": child.name,
            "path": str(child),
            "type": "dir" if child.is_dir() else "file",
            "size": child.stat().st_size if child.is_file() else None,
            "modified": datetime.fromtimestamp(child.stat().st_mtime).isoformat()
        })
    return {"path": str(p), "count": len(items), "items": items}


def op_tree(op: dict) -> dict:
    p = resolve_path(op.get("path") or ".", allow_sensitive=True)
    max_depth = int(op.get("max_depth", 2))
    limit = int(op.get("limit", 500))
    lines = []
    count = 0

    def walk(base: Path, depth: int) -> None:
        nonlocal count
        if count >= limit or depth > max_depth:
            return
        try:
            children = sorted(base.iterdir(), key=lambda x: (not x.is_dir(), x.name.lower()))
        except Exception:
            return
        for child in children:
            if count >= limit:
                return
            prefix = "  " * depth
            lines.append(f"{prefix}{'[D]' if child.is_dir() else '[F]'} {child.name}")
            count += 1
            if child.is_dir():
                walk(child, depth + 1)

    walk(p, 0)
    return {"path": str(p), "tree": "\n".join(lines), "count": count}


def op_read_text(op: dict) -> dict:
    p = resolve_path(op.get("path"))
    if not p.exists():
        raise FileNotFoundError(p)
    if not p.is_file():
        raise IsADirectoryError(p)
    ensure_safe_text_file(p)
    max_chars = int(op.get("max_chars", 30000))
    text = p.read_text(encoding="utf-8", errors="replace")
    return {"path": str(p), "chars": len(text), "content": text[:max_chars]}


def op_write_text(op: dict) -> dict:
    p = resolve_path(op.get("path"), for_write=True)
    ensure_safe_text_file(p)
    content = str(op.get("content", ""))
    backup = None
    if p.exists() and bool(op.get("backup_if_exists", True)):
        backup = backup_file(p)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding="utf-8", newline="")
    return {"path": str(p), "wrote_chars": len(content), "backup": str(backup) if backup else None}


def op_append_text(op: dict) -> dict:
    p = resolve_path(op.get("path"), for_write=True)
    ensure_safe_text_file(p)
    content = str(op.get("content", ""))
    p.parent.mkdir(parents=True, exist_ok=True)
    with p.open("a", encoding="utf-8", newline="") as f:
        f.write(content)
    return {"path": str(p), "appended_chars": len(content)}


def op_mkdir(op: dict) -> dict:
    p = resolve_path(op.get("path"), for_write=True, allow_sensitive=True)
    p.mkdir(parents=True, exist_ok=True)
    return {"path": str(p), "created_or_exists": True}


def op_touch(op: dict) -> dict:
    p = resolve_path(op.get("path"), for_write=True)
    ensure_safe_text_file(p)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.touch()
    return {"path": str(p), "touched": True}


def op_copy_file(op: dict) -> dict:
    src = resolve_path(op.get("src"))
    dst = resolve_path(op.get("dst"), for_write=True)
    if not src.is_file():
        raise FileNotFoundError(src)
    if dst.exists() and bool(op.get("backup_if_exists", True)):
        backup_file(dst)
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src, dst)
