import os
import json

# Define base paths
ACS_ROOT = "C:\\Users\\Dell\\Desktop\\Automation Creation Station"
AUTOPILOT_WORKSPACE = os.path.join(ACS_ROOT, "Plugins", "DK One Button ACS Autopilot", "workspace")
REPORT_FILE = os.path.join(AUTOPILOT_WORKSPACE, "gif_plugin_smoke_test_report.txt")

GIF_CONFIG_PATH = os.path.join(ACS_ROOT, "config", "acs_gif_popup_config.json")
WINDOWS_STARTUP_VBS = os.path.join(os.environ["APPDATA"], "Microsoft", "Windows", "Start Menu", "Programs", "Startup", "DK_One_Button_ACS_Autopilot.vbs")
SANDBOX_CONFIG_PATH = os.path.join(ACS_ROOT, "config", "acs_sandbox_config.json")

def append_to_report(message):
    try:
        with open(REPORT_FILE, "a") as f:
            f.write(message + "\n")
        print(message)
    except IOError as e:
        print(f"ERROR: Could not write to report file {REPORT_FILE}: {e}")

def verify_ahk_vbs_sandbox():
    append_to_report("\n--- Task 003: Verify GIF Popup AHK Path, Windows Startup VBS, and Sandbox Config ---")

    # 1. Extract GIF popup AHK script path from config and verify existence
    gif_popup_ahk_path = None
    try:
        with open(GIF_CONFIG_PATH, 'r') as f:
            gif_config = json.load(f)
        # Assuming the AHK path is stored under 'gif_popup_ahk_script_path' or similar
        # Adjust this key if the actual config structure is different
        gif_popup_ahk_path = gif_config.get('gif_popup_ahk_script_path') or \
                             gif_config.get('ahk_script_path') or \
                             gif_config.get('script_path')

        if gif_popup_ahk_path:
            full_ahk_path = os.path.abspath(os.path.join(ACS_ROOT, gif_popup_ahk_path)) # Assume relative to ACS_ROOT if not absolute
            if os.path.exists(full_ahk_path):
                append_to_report(f"[CHECK] GIF Popup AHK script '{full_ahk_path}' exists. STATUS: OK")
            else:
                append_to_report(f"[CHECK] GIF Popup AHK script '{full_ahk_path}' does NOT exist. STATUS: MISSING")
        else:
            append_to_report(f"[CHECK] GIF Popup AHK script path not found in '{GIF_CONFIG_PATH}'. STATUS: N/A")
    except FileNotFoundError:
        append_to_report(f"[CHECK] GIF Popup config file '{GIF_CONFIG_PATH}' not found. Cannot verify AHK path. STATUS: MISSING")
    except json.JSONDecodeError:
        append_to_report(f"[CHECK] Error decoding JSON from '{GIF_CONFIG_PATH}'. Cannot verify AHK path. STATUS: ERROR")
    except Exception as e:
        append_to_report(f"[CHECK] An unexpected error occurred while processing '{GIF_CONFIG_PATH}': {e}. STATUS: ERROR")

    # 2. Check for existence of Windows Startup VBS file
    if os.path.exists(WINDOWS_STARTUP_VBS):
        append_to_report(f"[CHECK] Windows Startup VBS file '{WINDOWS_STARTUP_VBS}' exists. STATUS: OK")
    else:
        append_to_report(f"[CHECK] Windows Startup VBS file '{WINDOWS_STARTUP_VBS}' does NOT exist. STATUS: MISSING")

    # 3. Check for existence of sandbox configuration file
    if os.path.exists(SANDBOX_CONFIG_PATH):
        append_to_report(f"[CHECK] Sandbox configuration file '{SANDBOX_CONFIG_PATH}' exists. STATUS: OK")
    else:
        append_to_report(f"[CHECK] Sandbox configuration file '{SANDBOX_CONFIG_PATH}' does NOT exist. STATUS: MISSING")

    append_to_report("--- End Task 003 ---")

if __name__ == "__main__":
    verify_ahk_vbs_sandbox()

