@echo off
start "" "~\Desktop\Automation Creation Station\Plugins\DK One Button ACS Autopilot\START_WATCHER_HIDDEN.vbs"
exit /b

param(
    [string]$pluginPath = "~\Desktop\Automation Creation Station\Plugins\DK One Button ACS Autopilot",
    [string]$mainScript = "autopilot_main.py"
)

$ErrorActionPreference = "Stop"

function Write-Log {
    param(
        [string]$Message,
        [string]$Level = "INFO"
    )
    $timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    Write-Host "[$timestamp] [$Level] $Message"
}

Write-Log "Starting Autopilot Plugin preparation..."
Write-Log "Plugin path: $pluginPath"

# 1. Create a timestamped backup of the entire plugin folder
try {
    $backupDir = Join-Path $pluginPath "backups"
    if (-not (Test-Path $backupDir)) {
        New-Item -Path $backupDir -ItemType Directory -Force | Out-Null
        Write-Log "Created backup directory: $backupDir"
    }
    $timestamp = Get-Date -Format "yyyyMMdd_HHmmss"
    $backupDestination = Join-Path $backupDir "DK One Button ACS Autopilot_$timestamp"

    Write-Log "Creating timestamped backup of '$pluginPath' to '$backupDestination'..."
    Copy-Item -Path $pluginPath -Destination $backupDestination -Recurse -Force
    Write-Log "Backup created successfully: $backupDestination"
} catch {
    Write-Log "ERROR: Failed to create backup. $_" "ERROR"
    exit 1
}

# 2. Ensure 'logs' and 'workspace' directories exist
try {
    $logsPath = Join-Path $pluginPath "logs"
    $workspacePath = Join-Path $pluginPath "workspace"

    if (-not (Test-Path $logsPath)) {
        New-Item -Path $logsPath -ItemType Directory -Force | Out-Null
        Write-Log "Created directory: $logsPath"
    } else {
        Write-Log "Directory already exists: $logsPath"
    }

    if (-not (Test-Path $workspacePath)) {
        New-Item -Path $workspacePath -ItemType Directory -Force | Out-Null
        Write-Log "Created directory: $workspacePath"
    } else {
        Write-Log "Directory already exists: $workspacePath"
    }
} catch {
    Write-Log "ERROR: Failed to ensure directories exist. $_" "ERROR"
    exit 1
}

# 3. Create batch scripts
try {
    $mainScriptFullPath = Join-Path $pluginPath $mainScript
    $pythonwPath = "pythonw.exe" # Assumed to be in PATH

    $runOnceContent = "start """" `"$pythonwPath`" `"$mainScriptFullPath`" --run-once"
    $startWatcherContent = "start """" `"$pythonwPath`" `"$mainScriptFullPath`" --start-watcher"
    $stopWatcherContent = "start """" `"$pythonwPath`" `"$mainScriptFullPath`" --stop-watcher"

    $scriptsToCreate = @{
        "RUN_ONCE.bat" = $runOnceContent;
        "START_WATCHER.bat" = $startWatcherContent;
        "STOP_WATCHER.bat" = $stopWatcherContent
    }

    foreach ($scriptName in $scriptsToCreate.Keys) {
        $scriptPath = Join-Path $pluginPath $scriptName
        $content = $scriptsToCreate[$scriptName]

        Write-Log "Creating/updating batch script: $scriptPath"
        Set-Content -Path $scriptPath -Value $content -Encoding ASCII
        Write-Log "Content for '$scriptName': $content"
    }
    Write-Log "All batch scripts created/updated successfully."
} catch {
    Write-Log "ERROR: Failed to create batch scripts. $_" "ERROR"
    exit 1
}

Write-Log "Autopilot Plugin preparation completed successfully."

import os
import json
import shutil
from datetime import datetime

CONFIG_FILE_PATH = r"~\Desktop\Automation Creation Station\config\acs_sandbox_config.json"
WINDOWS_SANDBOX_PATH_VALUE = r"C:\WINDOWS\system32\WindowsSandbox.exe"

def update_sandbox_config():
    print(f"Attempting to update ACS Sandbox configuration at: {CONFIG_FILE_PATH}")

    config_dir = os.path.dirname(CONFIG_FILE_PATH)
    if not os.path.exists(config_dir):
        try:
            os.makedirs(config_dir)
            print(f"Created directory: {config_dir}")
        except OSError as e:
            print(f"ERROR: Could not create directory {config_dir}: {e}")
            return False

    # Create a timestamped backup if the file exists
    if os.path.exists(CONFIG_FILE_PATH):
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup_file_path = f"{CONFIG_FILE_PATH}.{timestamp}.bak"
        try:
            shutil.copy2(CONFIG_FILE_PATH, backup_file_path)
            print(f"INFO: Created timestamped backup: {backup_file_path}")
        except Exception as e:
            print(f"ERROR: Failed to create backup of {CONFIG_FILE_PATH}: {e}")
            # Continue attempting to update the original file even if backup fails

        # Read existing content, update, and write back
        try:
            with open(CONFIG_FILE_PATH, 'r', encoding='utf-8') as f:
                config_data = json.load(f)
        except json.JSONDecodeError as e:
            print(f"WARNING: Existing file {CONFIG_FILE_PATH} is not valid JSON. Overwriting with new config. Error: {e}")
            config_data = {}
        except FileNotFoundError:
            # This case should ideally not happen if os.path.exists was true
            config_data = {}
        except Exception as e:
            print(f"ERROR: Failed to read {CONFIG_FILE_PATH}: {e}")
            return False

        config_data['windows_sandbox_path'] = WINDOWS_SANDBOX_PATH_VALUE

        try:
            with open(CONFIG_FILE_PATH, 'w', encoding='utf-8') as f:
                json.dump(config_data, f, indent=2)
            print(f"SUCCESS: Updated 'windows_sandbox_path' in {CONFIG_FILE_PATH} to '{WINDOWS_SANDBOX_PATH_VALUE}'.")
            return True
        except Exception as e:
            print(f"ERROR: Failed to write updated content to {CONFIG_FILE_PATH}: {e}")
            return False
    else:
        # File does not exist, create it with default content
        default_content = {"windows_sandbox_path": WINDOWS_SANDBOX_PATH_VALUE}
        try:
            with open(CONFIG_FILE_PATH, 'w', encoding='utf-8') as f:
                json.dump(default_content, f, indent=2)
            print(f"SUCCESS: Created new configuration file {CONFIG_FILE_PATH} with 'windows_sandbox_path' set to '{WINDOWS_SANDBOX_PATH_VALUE}'.")
            return True
        except Exception as e:
            print(f"ERROR: Failed to create {CONFIG_FILE_PATH}: {e}")
            return False

if __name__ == "__main__":
    if update_sandbox_config():
        print("ACS Sandbox configuration task completed successfully.")
    else:
        print("ACS Sandbox configuration task failed.")

import os
import subprocess
import sys

def create_shortcut(shortcut_path, target_path, description=""):
    try:
        # PowerShell command to create a shortcut
        powershell_command = f"""
$WshShell = New-Object -ComObject WScript.Shell;
$Shortcut = $WshShell.CreateShortcut('{shortcut_path}');
$Shortcut.TargetPath = '{target_path}';
$Shortcut.Description = '{description}';
$Shortcut.Save();
""".format(shortcut_path=shortcut_path.replace("'", "''"),
                   target_path=target_path.replace("'", "''"),
                   description=description.replace("'", "''"))

        result = subprocess.run(['powershell.exe', '-NoProfile', '-Command', powershell_command],
                                capture_output=True, text=True, check=True)
        print(f"Successfully created shortcut: {shortcut_path}")
        return True
    except subprocess.CalledProcessError as e:
        print(f"Error creating shortcut {shortcut_path}: {e.stderr}")
        return False
    except Exception as e:
        print(f"An unexpected error occurred while creating shortcut {shortcut_path}: {e}")
        return False

def create_batch_file(file_path, content):
    try:
        with open(file_path, 'w') as f:
            f.write(content)
        print(f"Successfully created batch file: {file_path}")
        return True
    except Exception as e:
        print(f"Error creating batch file {file_path}: {e}")
        return False

def main():
    print("Starting creation of Autopilot Control Panel and Shortcuts...")

    # Define base paths
    acs_plugins_path = "C:\\Users\\Dell\\Desktop\\Automation Creation Station\\Plugins"
    autopilot_plugin_path = os.path.join(acs_plugins_path, "DK One Button ACS Autopilot")
    launcher_folder = os.path.join(autopilot_plugin_path, "Autopilot Launcher")
    startup_vbs_path = "C:\\Users\\Dell\\AppData\\Roaming\\Microsoft\\Windows\\Start Menu\\Programs\\Startup\\DK_One_Button_ACS_Autopilot.vbs"

    # 1. Create the 'Autopilot Launcher' folder
    try:
        os.makedirs(launcher_folder, exist_ok=True)
        print(f"Ensured directory exists: {launcher_folder}")
    except Exception as e:
        print(f"Error creating directory {launcher_folder}: {e}")
        sys.exit(1)

    # Define shortcut targets and names
    shortcuts = [
        {
            "name": "Open Latest Report.lnk",
            "target": os.path.join(autopilot_plugin_path, "latest_autopilot_report.txt"),
            "description": "Opens the latest autopilot report"
        },
        {
            "name": "Open Drop Goal File.lnk",
            "target": os.path.join(autopilot_plugin_path, "DROP_VAGUE_GOAL_HERE.txt"),
            "description": "Opens the file for dropping vague goals"
        },
        {
            "name": "Open Autopilot Logs Folder.lnk",
            "target": autopilot_plugin_path,
            "description": "Opens the Autopilot Logs Folder"
        },
        {
            "name": "Open Autopilot Workspaces Folder.lnk",
            "target": autopilot_plugin_path,
            "description": "Opens the Autopilot Workspaces Folder"
        }
    ]

    # Create shortcuts
    for s in shortcuts:
        shortcut_full_path = os.path.join(launcher_folder, s["name"])
        create_shortcut(shortcut_full_path, s["target"], s["description"])

    # Define batch scripts content and names
    batch_scripts = [
        {
            "name": "Start_Autopilot_Watcher.bat",
            "content": f'start "" "{startup_vbs_path}"'
        },
        {
            "name": "Stop_Autopilot_Watcher.bat",
            "content": 'powershell.exe -NoProfile -Command "Get-WmiObject Win32_Process -Filter \"CommandLine LIKE \'%DK_One_Button_ACS_Autopilot.vbs%\'\" | ForEach-Object { Stop-Process -Id $_.ProcessId -Force }"'
        },
        {
            "name": "Run_Autopilot_Once.bat",
            "content": f'start "" "{startup_vbs_path}"'
        }
    ]

    # Create batch files
    for bs in batch_scripts:
