import os
import datetime

def inspect_autopilot_components():
    report_lines = []
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")

    # Define paths
    acs_root = "C:\\Users\\Dell\\Desktop\\Automation Creation Station"
    gif_plugin_dir = os.path.join(acs_root, "Plugins", "DK GIF Popup Plugin")
    autopilot_startup_vbs = os.path.join(os.environ['APPDATA'], "Microsoft", "Windows", "Start Menu", "Programs", "Startup", "DK_One_Button_ACS_Autopilot.vbs")
    autopilot_report_dir = os.path.join(acs_root, "Plugins", "DK One Button ACS Autopilot")

    launcher_extensions = ('.ahk', '.py', '.exe', '.bat', '.vbs')

    report_lines.append(f"--- Autopilot System Status Report ({timestamp}) ---")
    report_lines.append("\n1. DK GIF Popup Plugin Inspection:")

    # 1. Check for the existence of the 'DK GIF Popup Plugin' directory
    if os.path.isdir(gif_plugin_dir):
        report_lines.append(f"  - Directory found: '{gif_plugin_dir}'")

        # 2. List its immediate subdirectories and files
        try:
            contents = os.listdir(gif_plugin_dir)
            report_lines.append("  - Contents:")

            found_car = False
            found_animal = False
            found_person = False
            potential_launchers = []

            for item in contents:
                full_path = os.path.join(gif_plugin_dir, item)
                report_lines.append(f"    - {item} ({'Directory' if os.path.isdir(full_path) else 'File'})")

                if os.path.isdir(full_path):
                    if item.lower() == 'car':
                        found_car = True
                    elif item.lower() == 'animal':
                        found_animal = True
                    elif item.lower() == 'person':
                        found_person = True
                elif os.path.isfile(full_path):
                    if item.lower().endswith(launcher_extensions):
                        potential_launchers.append(item)

            report_lines.append("\n  - Specific Subdirectories Check:")
            report_lines.append(f"    - 'Car' subdirectory: {'Found' if found_car else 'Not Found'}")
            report_lines.append(f"    - 'Animal' subdirectory: {'Found' if found_animal else 'Not Found'}")
            report_lines.append(f"    - 'Person' subdirectory: {'Found' if found_person else 'Not Found'}")

            report_lines.append("\n  - Potential 'camera vehicle trigger launcher' files:")
            if potential_launchers:
                for launcher in potential_launchers:
                    report_lines.append(f"    - {launcher}")
            else:
                report_lines.append("    - None identified.")

        except Exception as e:
            report_lines.append(f"  - Error listing contents: {e}")
    else:
        report_lines.append(f"  - Directory NOT found: '{gif_plugin_dir}'")

    report_lines.append("\n2. DK_One_Button_ACS_Autopilot.vbs Startup File Inspection:")

    # 3. Verify the existence of the Autopilot startup VBS file
    if os.path.isfile(autopilot_startup_vbs):
        report_lines.append(f"  - File found: '{autopilot_startup_vbs}'")
    else:
        report_lines.append(f"  - File NOT found: '{autopilot_startup_vbs}'")

    # 4. Generate a detailed temporary report
    report_filename = f"autopilot_system_status_report_{timestamp}.txt"
    full_report_path = os.path.join(autopilot_report_dir, report_filename)

    # Ensure the report directory exists before writing
    if not os.path.exists(autopilot_report_dir):
        try:
            os.makedirs(autopilot_report_dir)
            report_lines.append(f"\nNote: Created missing report directory: '{autopilot_report_dir}'")
        except Exception as e:
            report_lines.append(f"\nError: Could not create report directory '{autopilot_report_dir}': {e}")
            print(f"Error: Could not create report directory '{autopilot_report_dir}': {e}")
            return # Exit if report directory cannot be created

    try:
        with open(full_report_path, 'w') as f:
            for line in report_lines:
                f.write(line + '\n')
        print(f"SUCCESS: Autopilot system status report generated at '{full_report_path}'")
    except Exception as e:
        print(f"FAILURE: Could not write report to '{full_report_path}': {e}")

if __name__ == "__main__":
    inspect_autopilot_components()

