$Lines = New-Object System.Collections.Generic.List[string]

function Add-Line {
    param([string]$Text = "")
    $Lines.Add($Text) | Out-Null
}

function Add-Section {
    param([string]$Title)
    Add-Line ""
    Add-Line "============================================================"
    Add-Line $Title
    Add-Line "============================================================"
}

function Redact-Text {
    param([string]$Text)

    if ($null -eq $Text) { return "" }

    $t = [string]$Text
    $t = $t -replace '(?i)(api[_ -]?key\s*[:=]\s*)["'']?[^"'']+["'']?', '$1[REDACTED]'
    $t = $t -replace '(?i)(secret\s*[:=]\s*)["'']?[^"'']+["'']?', '$1[REDACTED]'
    $t = $t -replace '(?i)(token\s*[:=]\s*)["'']?[^"'']+["'']?', '$1[REDACTED]'
    $t = $t -replace '(?i)(password\s*[:=]\s*)["'']?[^"'']+["'']?', '$1[REDACTED]'
    $t = $t -replace '(?i)(bearer\s+)[A-Za-z0-9._\-]+', '$1[REDACTED]'
    return $t
}

function Is-SensitivePath {
    param([string]$Path)

    if ([string]::IsNullOrWhiteSpace($Path)) { return $true }

    $lower = $Path.ToLowerInvariant()
    $name = [System.IO.Path]::GetFileName($Path).ToLowerInvariant()

    $blocked = @(
        "\appdata\local\google\chrome\user data",
        "\appdata\local\microsoft\edge\user data",
        "\appdata\roaming\mozilla\firefox",
        "\.ssh\",
        "\.aws\",
        "\.azure\",
        "\.git\",
        "\node_modules\",
        "\__pycache__\",
        "\venv\",
        "\.venv\"
    )

    foreach ($b in $blocked) {
        if ($lower.Contains($b)) { return $true }
    }

    $badNames = @("secret","secrets","credential","credentials","password","passwd","token","cookie","cookies","login data",".env","id_rsa")
    foreach ($b in $badNames) {
        if ($name.Contains($b)) { return $true }
    }

    $ext = [System.IO.Path]::GetExtension($Path).ToLowerInvariant()
    if ($ext -in @(".pem",".key",".pfx",".p12",".sqlite",".db")) { return $true }

    return $false
}

function Add-EventLogSummary {
    param(
        [string]$LogName,
        [int]$Hours = 12,
        [int]$MaxEvents = 40
    )

    Add-Section "WINDOWS EVENT LOG - $LogName - ERRORS/WARNINGS LAST $Hours HOURS"

    try {
        $start = (Get-Date).AddHours(-1 * $Hours)

        $events = Get-WinEvent -FilterHashtable @{
            LogName = $LogName
            StartTime = $start
            Level = 1,2,3
        } -MaxEvents $MaxEvents -ErrorAction SilentlyContinue

        if (!$events) {
            Add-Line "No recent critical/error/warning events found."
            return
        }

        foreach ($e in $events) {
            $msg = ($e.Message -replace "`r"," " -replace "`n"," ")
            $msg = Redact-Text $msg
            if ($msg.Length -gt 900) { $msg = $msg.Substring(0,900) + " ...[truncated]" }

            Add-Line ("Time: {0}" -f $e.TimeCreated)
            Add-Line ("Level: {0} | Provider: {1} | Id: {2}" -f $e.LevelDisplayName, $e.ProviderName, $e.Id)
            Add-Line ("Message: {0}" -f $msg)
            Add-Line ""
        }
    } catch {
        Add-Line "Could not read $LogName: $($_.Exception.Message)"
    }
}

function Add-ProcessSnapshot {
    Add-Section "SELECTED RUNNING PROCESSES"

    $names = @(
        "AutoHotkey64","AutoHotkey","python","pythonw","py","pyw",
        "powershell","pwsh","adb","scrcpy","ffmpeg","rclone","vlc",
        "chrome","msedge","EventGhost","Code","Plex Media Server",
        "node","npm"
    )

    try {
        $procs = Get-Process -ErrorAction SilentlyContinue |
            Where-Object { $names -contains $_.ProcessName } |
            Sort-Object ProcessName,Id

        if (!$procs) {
            Add-Line "No selected automation/media processes found."
            return
        }

        foreach ($p in $procs) {
            $start = ""
            try { $start = $p.StartTime } catch {}
            Add-Line ("{0} PID={1} CPU={2} MEM_MB={3:N1} START={4}" -f $p.ProcessName, $p.Id, $p.CPU, ($p.WorkingSet64 / 1MB), $start)
        }
    } catch {
        Add-Line "Could not list processes: $($_.Exception.Message)"
    }
}

function Add-PortSnapshot {
    Add-Section "LOCAL LISTENING PORTS"

    try {
        $important = @(8000,8001,8002,8003,8004,8765,8766,5555,5037,32400,11434)

        $conns = Get-NetTCPConnection -State Listen -ErrorAction SilentlyContinue |
            Where-Object { $important -contains $_.LocalPort } |
            Sort-Object LocalPort

        if (!$conns) {
            Add-Line "No selected ports are listening."
            return
        }

        foreach ($c in $conns) {
            $procName = ""
            try { $procName = (Get-Process -Id $c.OwningProcess -ErrorAction SilentlyContinue).ProcessName } catch {}
            Add-Line ("LISTEN {0}:{1} PID={2} PROC={3}" -f $c.LocalAddress, $c.LocalPort, $c.OwningProcess, $procName)
        }
    } catch {
        Add-Line "Could not list ports: $($_.Exception.Message)"
    }
}

function Add-RecentChangedFiles {
    param(
        [string[]]$Roots,
        [int]$Minutes = 240,
        [int]$Max = 180
    )

    Add-Section "RECENT CHANGED SCRIPT/CONFIG FILES - LAST $Minutes MINUTES"

    $cutoff = (Get-Date).AddMinutes(-1 * $Minutes)
    $items = @()

    foreach ($root in $Roots) {
        if (!(Test-Path -LiteralPath $root)) { continue }

        try {
            $items += Get-ChildItem -LiteralPath $root -Recurse -Force -File -ErrorAction SilentlyContinue |
                Where-Object {
                    $_.LastWriteTime -ge $cutoff -and
                    $_.Extension.ToLowerInvariant() -in @(".ahk",".py",".pyw",".ps1",".bat",".cmd",".json",".ini",".txt",".log",".html",".js",".vbs") -and
                    !(Is-SensitivePath $_.FullName)
                }
        } catch {}
    }

    $items = $items | Sort-Object LastWriteTime -Descending | Select-Object -First $Max

    if (!$items) {
        Add-Line "No recent tracked file changes."
        return
    }

    foreach ($i in $items) {
        Add-Line ("{0} | {1} | {2} bytes" -f $i.LastWriteTime, $i.FullName, $i.Length)
    }
}

function Add-LogTails {
    param(
        [string[]]$Roots,
        [int]$MaxLogs = 25,
        [int]$TailLines = 70
    )

    Add-Section "RECENT LOG TAILS"

    $logs = @()

    foreach ($root in $Roots) {
        if (!(Test-Path -LiteralPath $root)) { continue }

        try {
            $logs += Get-ChildItem -LiteralPath $root -Recurse -Force -File -ErrorAction SilentlyContinue |
                Where-Object {
                    $_.Extension.ToLowerInvariant() -in @(".log",".txt") -and
                    $_.Length -lt 3MB -and
                    !(Is-SensitivePath $_.FullName)
                }
        } catch {}
    }

    $logs = $logs | Sort-Object LastWriteTime -Descending | Select-Object -First $MaxLogs

    if (!$logs) {
        Add-Line "No readable logs found."
        return
    }

    foreach ($log in $logs) {
        Add-Line ""
        Add-Line "----- LOG: $($log.FullName)"
        Add-Line "----- Modified: $($log.LastWriteTime)"
        try {
            $tail = Get-Content -LiteralPath $log.FullName -Tail $TailLines -ErrorAction SilentlyContinue
            foreach ($line in $tail) {
                Add-Line (Redact-Text $line)
            }
        } catch {
            Add-Line "Could not read log: $($_.Exception.Message)"
        }
    }
}

