    WEBHOOK_DIR / "record_nest_cam.bat",
    Path(r"~\Documents\Codex\2026-06-08\i-want-real-debrid-mounted-as\outputs\nest-camera-desktop-button\Launch Nest Camera Red Button Minimized.bat"),
    Path(r"~\Documents\Codex\2026-06-08\i-want-real-debrid-mounted-as\outputs\nest-camera-station\Launch Nest Camera Station.bat"),
]

BLOCKED_WORDS = {
    "voice",
    "voiceactions",
    "dictate",
    "dictation",
    "announcement",
    "announce",
    "kokoro",
    "piper",
    "tts",
    "say",
    "workannouncements",
    "workvoiceannouncements",
    "watcher",
    "filewatcher",
    "fileorganizer",
    "organizer",
}

def no_window_flags():
    return getattr(subprocess, "CREATE_NO_WINDOW", 0)

def log_line(message: str):
    try:
        WEBHOOK_DIR.mkdir(parents=True, exist_ok=True)
        stamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with LOG_FILE.open("a", encoding="utf-8") as f:
            f.write(f"{stamp} - {message}\n")
    except Exception:
        pass

def clean_name(value: str) -> str:
    text = unquote_plus(str(value or "")).strip().strip('"').strip("'")
    text = text.replace(".bat", "").replace(".cmd", "").replace(".ps1", "")
    return text.strip()

def compact(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "", str(value or "").lower())

def is_blocked(name: str) -> bool:
    c = compact(name)
    return any(word in c for word in BLOCKED_WORDS)

def validate_alias(value: str):
    name = clean_name(value)

    if not name:
        return None, "No alias name was given."

    if is_blocked(name):
        return None, "Blocked in clean mode: voice, dictation, announcements, and file watcher routes are disabled."

    if "\\" in name or "/" in name or ":" in name:
        return None, "Path characters are not allowed. Use only an Alias Relay BAT name."

    if not re.fullmatch(r"[A-Za-z0-9 _.-]{1,120}", name):
        return None, "Alias name contains unsupported characters."

    return name, None

def run_process(command, cwd=None):
    subprocess.Popen(
        command,
        cwd=str(cwd) if cwd else None,
        creationflags=no_window_flags(),
        stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL,
        stdin=subprocess.DEVNULL,
    )

def run_alias(alias_name: str):
    name, error = validate_alias(alias_name)

    if error:
        log_line(f"BLOCKED alias={alias_name!r} error={error}")
        return {"ok": False, "error": error, "name": alias_name}

    bat = ALIAS_DIR / f"{name}.bat"

    if not bat.exists():
        log_line(f"MISSING alias={name} path={bat}")
        return {
            "ok": False,
            "error": "Alias BAT not found.",
            "alias": name,
            "expected": str(bat),
        }

    run_process(["cmd", "/c", str(bat)], cwd=ALIAS_DIR)
    log_line(f"RAN alias={name} path={bat}")
    return {"ok": True, "type": "alias_bat", "alias": name, "ran": str(bat)}

def find_nest_target():
    for candidate in NEST_CANDIDATES:
        try:
            if candidate.exists():
                return candidate
        except Exception:
            pass
    return None

def run_nest():
    target = find_nest_target()
    if not target:
        return {
            "ok": False,
            "error": "No Nest launcher was found.",
            "checked": [str(x) for x in NEST_CANDIDATES],
        }

    run_process(["cmd", "/c", str(target)], cwd=target.parent)
    log_line(f"RAN Nest target={target}")
    return {"ok": True, "type": "nest", "ran": str(target)}

