STATE_DIR = Path.home() / "Documents" / "Codex" / "2026-06-08" / "i-want-real-debrid-mounted-as" / "outputs" / "central-control-panel" / "state"
BRIDGE_LOG = STATE_DIR / "station_webhook_bridge.log"
PYTHONW = Path(r"~\AppData\Local\Programs\Python\Python312\pythonw.exe")
PYTHON = Path(r"~\AppData\Local\Programs\Python\Python312\python.exe")
MACRO_RUNNER = TRIGGER / "MACRO_LAUNCH_PAD_FIXED.pyw"
NEST_CAMERA_STATION = Path(r"~\Documents\Codex\2026-06-08\i-want-real-debrid-mounted-as\outputs\nest-camera-station\Launch Nest Camera Station.bat")


def run_bat(bat_name):
    bat = ALIAS / f"{bat_name}.bat"

    if not bat.exists():
        return {"ok": False, "error": f"BAT not found: {bat}"}

    subprocess.Popen(["cmd", "/c", str(bat)])
    return {"ok": True, "ran": str(bat)}


def find_bridge_macro(name):
    wanted = normalize_bridge_name(name)
    for path in TRIGGER.rglob("*.json"):
        try:
            data = json.loads(path.read_text(encoding="utf-8-sig"))
        except Exception:
            continue
        triggers = data.get("active_triggers", []) if isinstance(data, dict) else []
        for trigger in triggers:
            if not isinstance(trigger, dict):
                continue
            if trigger.get("type") != "acs_bridge_trigger":
                continue
            if trigger.get("enabled", True) is False:
                continue
            names = [
                str(trigger.get("name", "")),
                str(trigger.get("display", "")),
                path.stem,
            ]
            if any(normalize_bridge_name(value) == wanted for value in names):
                return path
    return None


def normalize_bridge_name(value):
    return re.sub(r"[^a-z0-9]+", "", str(value or "").strip().lower())


def bridge_log(message):
    try:
        STATE_DIR.mkdir(parents=True, exist_ok=True)
        with BRIDGE_LOG.open("a", encoding="utf-8") as handle:
            handle.write(f"{__import__('time').strftime('%Y-%m-%dT%H:%M:%S')} {message}\n")
    except Exception:
        pass


def run_macro_json(path):
    if not MACRO_RUNNER.exists():
        bridge_log(f"ERROR runner missing: {MACRO_RUNNER}")
        return {"ok": False, "error": f"Macro runner not found: {MACRO_RUNNER}"}
    exe = PYTHONW if PYTHONW.exists() else PYTHON
    subprocess.Popen(
        [str(exe), str(MACRO_RUNNER), "--run-json", str(path)],
        cwd=str(MACRO_RUNNER.parent),
    )
    bridge_log(f"RUN {path}")
    return {"ok": True, "ran": str(path)}


