app = Flask(__name__)

ROOT = Path(r"~\Desktop\Automation Creation Station")
ALIAS = ROOT / "Alias Relay"
TTS_STATION = ROOT / "TTS Station"
VOICE_STATION = ROOT / "Voice Station"
ANNOUNCEMENT_HUB = TTS_STATION / "Announcement_Hub.ahk"
SAY_TEXT = ROOT / "scripts" / "say_text.ps1"

AUTOHOTKEY_CANDIDATES = [
    Path(r"C:\Program Files\AutoHotkey\v2\AutoHotkey64.exe"),
    Path(r"C:\Program Files\AutoHotkey\v2\AutoHotkey.exe"),
    Path(r"C:\Program Files\AutoHotkey\AutoHotkey.exe"),
]


def no_window_flags():
    return getattr(subprocess, "CREATE_NO_WINDOW", 0)


def find_autohotkey():
    for exe in AUTOHOTKEY_CANDIDATES:
        if exe.exists():
            return exe
    return None


def clean_text(value: str) -> str:
    text = unquote_plus(str(value)).strip().strip('"').strip("'")
    text = text.replace("\\", " ").replace("/", " ")
    return " ".join(text.split())


def clean_announcement_name(value: str) -> str:
    text = unquote_plus(str(value)).strip().strip('"').strip("'")
    text = text.replace("\\", "-").replace("/", "-")
    lower = text.lower()

    for prefix in ["announcement-", "announce-", "tts-", "voice-", "say-"]:
        if lower.startswith(prefix):
            text = text[len(prefix):]
            lower = text.lower()

    return text.strip()


def run_bat(bat_name):
    bat = ALIAS / f"{bat_name}.bat"

    if not bat.exists():
        return {"ok": False, "error": f"BAT not found: {bat}"}

    subprocess.Popen(
        ["cmd", "/c", str(bat)],
        cwd=str(ALIAS),
        creationflags=no_window_flags(),
    )

    return {"ok": True, "type": "bat", "ran": str(bat)}


def run_announcement(name):
    clean = clean_announcement_name(name)
    ahk = find_autohotkey()

    if not clean:
        return {"ok": False, "error": "No announcement name was given"}

    if ahk is None:
        return {
            "ok": False,
            "error": "AutoHotkey was not found. Install AutoHotkey v2 or update AUTOHOTKEY_CANDIDATES.",
        }

    if not ANNOUNCEMENT_HUB.exists():
        return {"ok": False, "error": f"Announcement hub not found: {ANNOUNCEMENT_HUB}"}

    subprocess.Popen(
        [str(ahk), str(ANNOUNCEMENT_HUB), clean],
        cwd=str(TTS_STATION),
        creationflags=no_window_flags(),
    )

    return {
        "ok": True,
        "type": "kokoro_announcement",
        "name": clean,
        "ran": str(ANNOUNCEMENT_HUB),
    }


def run_say_text(text):
    speech = clean_text(text)

    if not speech:
        return {"ok": False, "error": "No speech text was given"}

    if not SAY_TEXT.exists():
        return {"ok": False, "error": f"say_text.ps1 not found: {SAY_TEXT}"}

    subprocess.Popen(
        [
            "powershell.exe",
            "-NoProfile",
            "-ExecutionPolicy",
            "Bypass",
            "-File",
            str(SAY_TEXT),
            "-Text",
            speech,
        ],
        cwd=str(ROOT),
        creationflags=no_window_flags(),
    )

    return {
        "ok": True,
        "type": "kokoro_say_text",
        "text": speech,
        "ran": str(SAY_TEXT),
    }


