        for filePath in files {
            SplitPath(filePath, &fileName)
            menuText .= "- " fileName "`n"
        }
        menuText .= "`n"
    }

    menuText .= "Built-in Kokoro aliases:`n"
    for key, phrase in aliases {
        menuText .= "- " key " = " phrase "`n"
    }

    menuText .= "`nWebhook examples:`n"
    menuText .= "http://10.0.2.2:8766/webhook/announcement-break`n"
    menuText .= "http://10.0.2.2:8766/webhook/say/Take a break Dell"

    MsgBox(menuText, "DK Kokoro Announcement Hub")
}


ResolveSpeechText(requested) {
    global aliases

    clean := NormalizeKey(requested)

    if aliases.Has(clean)
        return aliases[clean]

    if InStr(StrLower(requested), "say-") = 1
        return UrlToSpeech(SubStr(requested, 5))

    if InStr(StrLower(requested), "tts-") = 1
        return UrlToSpeech(SubStr(requested, 5))

    if InStr(StrLower(requested), "voice-") = 1
        return UrlToSpeech(SubStr(requested, 7))

    ; If it is not a known alias but has words, speak it as text.
    maybeText := UrlToSpeech(requested)
    if InStr(maybeText, " ")
        return maybeText

    return maybeText
}


ResolveAudioFile(requested) {
    global voiceFolder

    clean := NormalizeKey(requested)

    if FileExist(requested)
        return requested

    directPath := voiceFolder "\" requested
    if FileExist(directPath)
        return directPath

    for ext in [".mp3", ".wav", ".m4a", ".wma"] {
        tryPath := voiceFolder "\" requested ext
        if FileExist(tryPath)
            return tryPath
    }

    files := GetAudioFiles()

    for filePath in files {
        SplitPath(filePath, &fileName, , &fileExt, &fileNameNoExt)
        if (NormalizeKey(fileNameNoExt) = clean)
            return filePath
    }

    for filePath in files {
        SplitPath(filePath, &fileName, , &fileExt, &fileNameNoExt)
        if InStr(NormalizeKey(fileNameNoExt), clean)
            return filePath
    }

    return ""
}


GetAudioFiles() {
    global voiceFolder

    files := []

    for ext in ["mp3", "wav", "m4a", "wma"] {
        Loop Files voiceFolder "\*." ext, "F" {
            files.Push(A_LoopFileFullPath)
        }
    }

    return files
}


NormalizeKey(value) {
    key := StrLower(Trim(value))
    key := StrReplace(key, '"', "")
    key := StrReplace(key, "'", "")
    key := StrReplace(key, ".mp3", "")
    key := StrReplace(key, ".wav", "")
    key := StrReplace(key, ".m4a", "")
    key := StrReplace(key, ".wma", "")
    key := StrReplace(key, "announcement-", "")
    key := StrReplace(key, "announce-", "")
    key := StrReplace(key, "tts-", "")
    key := StrReplace(key, "voice-", "")
    key := StrReplace(key, "say-", "")
    key := StrReplace(key, "%20", "")
    key := StrReplace(key, "+", "")
    key := StrReplace(key, " ", "")
    key := StrReplace(key, "_", "")
    key := StrReplace(key, "-", "")
    key := StrReplace(key, ".", "")
    return key
}


UrlToSpeech(value) {
    text := Trim(value)
    text := StrReplace(text, "announcement-", "")
    text := StrReplace(text, "announce-", "")
    text := StrReplace(text, "tts-", "")
    text := StrReplace(text, "voice-", "")
    text := StrReplace(text, "say-", "")
    text := StrReplace(text, "%20", " ")
    text := StrReplace(text, "+", " ")
    text := StrReplace(text, "_", " ")
    text := StrReplace(text, "-", " ")
    return Trim(text)
}


SpeakKokoro(speechText) {
    global sayTextPs1, kokoroBat, voiceStation

    if (speechText = "")
        return

    if FileExist(sayTextPs1) {
        RunWait('powershell.exe -NoProfile -ExecutionPolicy Bypass -File "' sayTextPs1 '" -Text "' EscapeForCommand(speechText) '"', , "Hide")
        return
    }

    if FileExist(kokoroBat) {
        RunWait('"' kokoroBat '" "' EscapeForCommand(speechText) '"', voiceStation, "Hide")
        return
    }

    MsgBox("Kokoro voice files were not found.`n`nMissing:`n" sayTextPs1 "`n`nOr:`n" kokoroBat, "DK Kokoro Announcement Hub", "Iconx")
}


EscapeForCommand(value) {
    clean := StrReplace(value, '"', "'")
    return clean
}


PlayAudio(audioPath, volume := 100) {
    if PlayWithMCI(audioPath, volume)
        return

    if PlayWithWMP(audioPath, volume)
        return

    Run('"' audioPath '"')
}


PlayWithMCI(audioPath, volume := 100) {
    aliasName := "dk_announcement_" A_TickCount
    q := Chr(34)

    openCmd := "open " q audioPath q " alias " aliasName
    result := MciSend(openCmd)

    if (result != 0)
        return false

    vol := Round(Max(0, Min(volume, 100)) * 10)
    MciSend("setaudio " aliasName " volume to " vol)

    playResult := MciSend("play " aliasName " wait")
    MciSend("close " aliasName)

    return playResult = 0
}


PlayWithWMP(audioPath, volume := 100) {
    try {
        player := ComObject("WMPlayer.OCX")
        player.settings.volume := Max(0, Min(volume, 100))
        player.URL := audioPath
        player.controls.play()

        startTime := A_TickCount

        Loop {
            Sleep 250
            state := player.playState

            if (state = 1 && A_TickCount - startTime > 1000)
                break

            if (A_TickCount - startTime > 600000)
                break
        }

        player.controls.stop()
        return true
    } catch {
        return false
    }
}


