param(
    [switch]$QuietAtNight,
    [int]$StartHour = 7,
    [int]$EndHour = 23,
    [string]$Voice = "",
    [switch]$Stop
)

$ErrorActionPreference = "SilentlyContinue"

$Root = "~\Desktop\Automation Creation Station"
$ScriptsDir = Join-Path $Root "scripts"
$SayText = Join-Path $ScriptsDir "say_text.ps1"
$LogDir = Join-Path $Root "data\logs"
$LogFile = Join-Path $LogDir "hourly_time_chime.log"
$StopFile = Join-Path $Root "data\STOP_HOURLY_CHIME.txt"

New-Item -ItemType Directory -Force -Path $LogDir | Out-Null

function Log {
    param([string]$Message)
    Add-Content -Path $LogFile -Value "$(Get-Date -Format s) $Message"
}

if ($Stop) {
    New-Item -ItemType File -Force -Path $StopFile | Out-Null
    Log "Stop requested."
    Write-Host "Hourly chime stop requested."
    exit 0
}

if (Test-Path $StopFile) {
    Remove-Item $StopFile -Force
}

Log "Hourly time chime started with Kokoro. Voice=$Voice"
$lastAnnounced = ""

while ($true) {
    if (Test-Path $StopFile) {
        Log "Stop file detected. Exiting."
        Remove-Item $StopFile -Force
        exit 0
    }

    $now = Get-Date
    $key = $now.ToString("yyyy-MM-dd-HH")

    if ($now.Minute -eq 0 -and $key -ne $lastAnnounced) {
        if (!$QuietAtNight -or ($now.Hour -ge $StartHour -and $now.Hour -le $EndHour)) {
            [console]::beep(880, 160)
            Start-Sleep -Milliseconds 100
            [console]::beep(1175, 180)

            $spokenTime = "It is " + $now.ToString("h tt")

            if (Test-Path $SayText) {
                if ($Voice -ne "") {
                    & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $SayText -Text $spokenTime -Voice $Voice
                } else {
                    & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $SayText -Text $spokenTime
                }
                Log "Announced $spokenTime with Kokoro."
            } else {
                Log "say_text.ps1 not found: $SayText"
            }
        }

        $lastAnnounced = $key
    }

    Start-Sleep -Seconds 20
}

