if (-not (Test-Path -LiteralPath $nircmd)) {
  throw "Missing NirCmd: $nircmd"
}

$config = Get-Content -LiteralPath $configPath -Raw | ConvertFrom-Json
$profiles = $config.profiles
$match = $profiles.PSObject.Properties | Where-Object { $_.Name.ToLower() -eq $Profile.ToLower() } | Select-Object -First 1
if (-not $match) {
  $available = ($profiles.PSObject.Properties.Name -join ", ")
  throw "Unknown audio profile '$Profile'. Available: $available"
}

$profileData = $match.Value
$inputName = [string]$profileData.input
$outputName = [string]$profileData.output

function Set-DefaultSoundDevice([string]$name) {
  if (-not $name) { return }
  foreach ($role in 0, 1, 2) {
    & $nircmd setdefaultsounddevice "$name" $role | Out-Null
  }
}

Set-DefaultSoundDevice $outputName
Set-DefaultSoundDevice $inputName

$log = Join-Path $root "Audio Station\audio_profile.log"
New-Item -ItemType Directory -Force -Path (Split-Path $log) | Out-Null
"[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] $($match.Name): input='$inputName' output='$outputName'" | Add-Content -LiteralPath $log
Write-Host "Audio profile applied: $($match.Name)"

