import argparse
import json
import os
import pathlib
import time
import urllib.parse
import urllib.request


ROOT = pathlib.Path.home() / "Desktop" / "Automation Creation Station"
INBOX = ROOT / "Trigger Station" / "Inbox"
WEBHOOK = ROOT / "Nexus Automation Station" / "config" / "webhook_server.json"


def load_webhook():
    try:
        return json.loads(WEBHOOK.read_text(encoding="utf-8-sig"))
    except Exception:
        return {"host": "127.0.0.1", "port": 8765, "token": "change-me"}


def trigger_file(alias):
    INBOX.mkdir(parents=True, exist_ok=True)
    stamp = time.strftime("%Y%m%d_%H%M%S")
    path = INBOX / f"trigger_{stamp}.txt"
    path.write_text(alias.strip() + "\n", encoding="utf-8")
    return path


def trigger_http(alias):
    cfg = load_webhook()
    host = cfg.get("host", "127.0.0.1")
    port = int(cfg.get("port", 8765))
    token = ***
    query = {"alias": alias}
    if token and token != "change-me":
        query["token"] = token
    url = f"http://{host}:{port}/alias?{urllib.parse.urlencode(query)}"
    with urllib.request.urlopen(url, timeout=10) as response:
        return response.status, response.read().decode("utf-8", errors="replace")


def trigger_clipboard(alias):
    try:
        import tkinter as tk
        root = tk.Tk()
        root.withdraw()
        root.clipboard_clear()
        root.clipboard_append(alias)
        root.update()
        root.destroy()
        return True
    except Exception:
        return False


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("alias")
    parser.add_argument("--method", choices=["http", "file", "clipboard"], default="http")
    args = parser.parse_args()

    if args.method == "file":
        print(trigger_file(args.alias))
    elif args.method == "clipboard":
        print("clipboard ok" if trigger_clipboard(args.alias) else "clipboard failed")
    else:
        print(trigger_http(args.alias))


if __name__ == "__main__":
    main()

