import subprocess
import sys
import time
import socket
import ipaddress
import os

def get_local_subnet():
    """Get the local IPv4 subnet (e.g., 192.168.1.0/24)."""
    # Get the local IP by connecting to a public address (doesn't actually send data)
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        s.connect(("8.8.8.8", 80))
        local_ip = s.getsockname()[0]
        s.close()
    except Exception:
        return None
    # Assume /24 subnet (mask 255.255.255.0)
    parts = local_ip.split('.')
    return f"{parts[0]}.{parts[1]}.{parts[2]}.0/24"

def scan_ports(ip, ports):
    """Check if any of the given ports are open on the IP."""
    open_ports = []
    for port in ports:
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                s.settimeout(0.2)
                if s.connect_ex((ip, port)) == 0:
                    open_ports.append(port)
        except:
            pass
    return open_ports

def get_active_ips(subnet):
    """Get list of active IPs using arp -a (fast)."""
    result = subprocess.run(["arp", "-a"], capture_output=True, text=True)
    lines = result.stdout.splitlines()
    ips = []
    for line in lines:
        # arp -a output format: 192.168.1.1           xx-xx-xx-xx-xx-xx     dynamic
        if '(' in line and ')' in line:
            # Extract IP between '(' and ')'
            start = line.find('(')
            end = line.find(')')
            if start != -1 and end != -1:
                ip = line[start+1:end]
                # Check if IP is in our subnet
                if ipaddress.ip_address(ip) in ipaddress.ip_network(subnet):
                    ips.append(ip)
    return ips

def main():
    print("AutoADB Scanner started. Press Ctrl+C to stop.")
    subnet = get_local_subnet()
    if not subnet:
        print("Could not determine local subnet. Please check your network.")
        sys.exit(1)
    print(f"Scanning subnet: {subnet}")

    port_range = range(5555, 5586)  # 5555-5585
    known_ips = set()

    while True:
        # Get currently active IPs on the network
        active_ips = get_active_ips(subnet)
        # For each active IP, scan for ADB ports
        for ip in active_ips:
            if ip in known_ips:
                continue  # Already checked
            print(f"Checking {ip}...")
            open_ports = scan_ports(ip, port_range)
            if open_ports:
                for port in open_ports:
                    # Attempt connection
                    result = subprocess.run(
                        ["adb", "connect", f"{ip}:{port}"],
                        capture_output=True, text=True
                    )
                    output = result.stdout.strip()
                    print(output)
                    if "connected" in output.lower():
                        print(f"✅ Connected to {ip}:{port}")
                        known_ips.add(ip)
                        # After successful connection, we can keep scanning for other devices
            else:
                known_ips.add(ip)  # Remember we already scanned this IP, no need to rescan often
        # Wait a bit before scanning again (e.g., 10 seconds)
        time.sleep(10)

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\nScanner stopped.")

