const robot = require('robotjs'); // npm i robotjs
const { exec } = require('child_process');

module.exports = function initRecorder(host, opts = {}) {
  let recording = false;
  let events = [];
  let lastMouse = null;
  let lastKeys = [];

  function start() {
    recording = true;
    events = [];
    lastMouse = robot.getMousePos();
    lastKeys = [];
    // poll mouse/keyboard
    const interval = setInterval(() => {
      if (!recording) { clearInterval(interval); return; }
      const mouse = robot.getMousePos();
      if (mouse.x !== lastMouse.x || mouse.y !== lastMouse.y) {
        events.push({ type: 'mouseMove', x: mouse.x, y: mouse.y, ts: Date.now() });
        lastMouse = mouse;
      }
      // keyboard: robotjs doesn't have easy key down/up, so use global hook if available; placeholder
      // for simplicity, assume manual key events or extend with node-global-key-listener
    }, 100);
  }

  function stop() {
    recording = false;
    return events;
  }

  function recordClick(x, y) {
    if (!recording) return;
    events.push({ type: 'click', x, y, ts: Date.now() });
  }

  function recordKey(key) {
    if (!recording) return;
    events.push({ type: 'key', key, ts: Date.now() });
  }

  // detect UI element at pos (simple UIA via PowerShell)
  async function detectElement(x, y) {
    const ps = `
Add-Type -AssemblyName UIAutomationClient, UIAutomationTypes
$ae = [System.Windows.Automation.AutomationElement]::FromPoint([System.Windows.Point]::new(${x}, ${y}))
if ($ae) { @{ name=$ae.Current.Name; class=$ae.Current.ClassName; id=$ae.Current.AutomationId } | ConvertTo-Json }
`;
    try {
      const out = await new Promise((res,rej)=> exec(`powershell.exe -NoProfile -NonInteractive -Command "${ps.replace(/"/g,'\\"')}"`, (err,stdout)=> err?rej(err):res(stdout)));
      return JSON.parse(out.trim());
    } catch(e) { return null; }
  }

  // generate macro from events (simple: group moves, convert clicks to taps, keys to keystroke)
  function generateMacro(events, name = 'Recorded Macro') {
    const actions = [];
    let lastMove = null;
    events.forEach(e => {
      if (e.type === 'mouseMove') lastMove = e;
      else if (e.type === 'click') {
        if (lastMove) actions.push({ type: 'adb.tap', payload: { deviceId: 'default', x: lastMove.x, y: lastMove.y } }); // assume ADB for now
      } else if (e.type === 'key') {
        actions.push({ type: 'keystroke', payload: { keys: e.key } });
      }
    });
    return { name, trigger: {}, actions, variables: {} };
  }

  host.recorder = { start, stop, recordClick, recordKey, detectElement, generateMacro };

  return { start, stop, recordClick, recordKey, detectElement, generateMacro };
};

