{
  function createMacro(m) {
    const macro = Object.assign({ id, name: m.name || `macro-${id}`, trigger: m.trigger || {}, actions: m.actions || [], variables: m.variables || {}, conditions: m.conditions || [] }, m);
    return macro;
  }

  async function runMacro(m, context = {}) {
    const vars = Object.assign({}, m.variables || {}, context.vars || {});
    const results = [];
    for (const item of (m.actions || [])) {
      if (item.type === 'condition') {
        // evaluate condition: item.payload { op: 'if', expr: 'var1 == "value"', then: [actions], else: [actions] }
        const expr = item.payload.expr;
        let ok = false;
        try {
          // simple eval with vars (unsafe, sandbox later)
          const fn = new Function(...Object.keys(vars), `return ${expr}`);
          ok = fn(...Object.values(vars));
        } catch(e) { ok = false; }
        const branch = ok ? item.payload.then : item.payload.else;
        if (branch) {
          const subRes = await runMacro({ actions: branch }, { vars });
          results.push({ item, subResults: subRes });
        }
      } else if (item.type === 'loop') {
        // item.payload { count: 5, actions: [..] }
        const count = parseInt(item.payload.count) || 1;
        for (let i = 0; i < count; i++) {
          const subRes = await runMacro({ actions: item.payload.actions }, { vars });
          results.push({ item, loopIndex: i, subResults: subRes });
        }
      } else if (item.type === 'setVar') {
        // item.payload { varName: 'x', value: 'expr' or static }
        const val = item.payload.value;
        vars[item.payload.varName] = val.startsWith('=') ? eval(val.slice(1)) : val; // simple
        results.push({ item, set: vars[item.payload.varName] });
      } else {
        // ...existing action execution...
        // pass vars to actions if needed (e.g., interpolate in payload)
        const interpolated = JSON.parse(JSON.stringify(item.payload).replace(/\{\{(\w+)\}\}/g, (m,p1)=> vars[p1] || ''));
        // ...existing try/catch for action...
        res = await host.performAction({ type: item.type, payload: interpolated, id: item.actionId });
        // ...existing results push...
      }
    }
    return results;
  }
}

