const fs = require('fs');
const path = require('path');

module.exports = function initMacroEngine(host, opts = {}) {
  const dataPath = opts.dataPath || path.join(__dirname, '..', 'data');
  const file = path.join(dataPath, 'macros.json');
  if (!fs.existsSync(dataPath)) fs.mkdirSync(dataPath, { recursive: true });
  if (!fs.existsSync(file)) fs.writeFileSync(file, '[]', 'utf8');

  function load() {
    try { return JSON.parse(fs.readFileSync(file, 'utf8') || '[]'); } catch(e){ return []; }
  }
  function save(arr) { fs.writeFileSync(file, JSON.stringify(arr, null, 2), 'utf8'); }

  function listMacros() { return load(); }

  function createMacro(m) {
    const arr = load();
    const id = Date.now().toString(36);
    const macro = Object.assign({ id, name: m.name || `macro-${id}`, trigger: m.trigger || {}, actions: m.actions || [] }, m);
    arr.push(macro);
    save(arr);
    return macro;
  }

  async function runMacroById(id) {
    const arr = load();
    const m = arr.find(x=>x.id===id);
    if (!m) throw new Error('macro_not_found');
    return await runMacro(m);
  }

  async function runMacro(m) {
    const results = [];
    for (const a of (m.actions || [])) {
      try {
        let res;
        if (a.type.startsWith('adb.')) {
          const cmd = a.type.split('.')[1];
          if (!host.adb) throw new Error('adb_not_initialized');
          if (cmd === 'shell') res = await host.adb.shell(a.payload.deviceId, a.payload.cmd);
          else if (cmd === 'tap') res = await host.adb.inputTap(a.payload.deviceId, a.payload.x, a.payload.y);
          else if (cmd === 'text') res = await host.adb.inputText(a.payload.deviceId, a.payload.text);
          else if (cmd === 'screencap') res = await host.adb.screencap(a.payload.deviceId);
          else res = await host.adb[cmd](a.payload.deviceId, ...(a.payload.args || []));
        } else {
          // delegate to host.performAction (existing)
          if (!host.performAction) throw new Error('action_host_missing');
          res = await host.performAction({ type: a.type, payload: a.payload, id: a.actionId });
        }
        results.push({ action: a, ok: true, res });
      } catch (err) {
        results.push({ action: a, ok: false, error: String(err) });
        // stop on error
        break;
      }
    }
    return results;
  }

  // listen for triggers emitted by host
  if (host && host.on) {
    host.on('trigger', async (t) => {
      try {
        const macros = listMacros();
        for (const m of macros) {
          // simple matching: trigger.type equals m.trigger.type and optional matcher on payload.key==value
          if (!m.trigger || !m.trigger.type) continue;
          if (m.trigger.type !== t.trigger) continue;
          // optional simple payload match
          if (m.trigger.match) {
            let ok = true;
            for (const k of Object.keys(m.trigger.match)) {
              if (String((t.payload && t.payload[k]) || '') !== String(m.trigger.match[k])) { ok = false; break; }
            }
            if (!ok) continue;
          }
          // run macro (fire and forget)
          runMacro(m).then(res => host.emit && host.emit('macroRunResult', { macroId: m.id, result: res })).catch(()=>{});
        }
      } catch(e){}
    });
  } else {
    // fallback: listen for global emit via host.emit override not available; nothing to do
  }

  // attach to host
  host.macroEngine = { listMacros, createMacro, runMacro, runMacroById };

  return { listMacros, createMacro, runMacro, runMacroById };
};

