  // forward trigger events to clients using host.emit('trigger', {...})
  host.emit = function(type, payload) {
    const msg = JSON.stringify({ type, payload });
    for (const ws of clients) {
      if (ws.readyState === WebSocket.OPEN) ws.send(msg);
    }
  };
}

