scripts.content:
const { exec } = require('child_process');

module.exports = function initEventCollector(host, opts = {}) {
  const pollInterval = opts.pollIntervalMs || 10_000; // 10s
  const maxEvents = opts.maxEvents || 50;
  let seen = new Set();

  function runPS(cmd, cb) {
    exec(`powershell.exe -NoProfile -NonInteractive -Command "${cmd.replace(/"/g,'\\"')}"`, { windowsHide: true, timeout: 120000 }, (err, stdout, stderr) => {
      if (err) return cb(new Error(stderr || String(err)));
      cb(null, stdout);
    });
  }

  async function poll() {
    const ps = `
Get-WinEvent -MaxEvents ${maxEvents} | ForEach-Object {
  [PSCustomObject]@{
    RecordId = $_.RecordId
    LogName = $_.LogName
    TimeCreated = $_.TimeCreated.ToString("o")
    Id = $_.Id
    LevelDisplayName = $_.LevelDisplayName
    ProviderName = $_.ProviderName
    Message = $_.Message
  }
} | ConvertTo-Json -Depth 3
`;
    runPS(ps, (err, out) => {
      if (err) { host.log && host.log('eventCollector', 'ps_error', String(err)); return; }
      let parsed;
      try { parsed = JSON.parse(out); }
      catch (e) { try { parsed = [JSON.parse(`[${out.replace(/\r?\n/g,'')}]`)]; } catch(e2) { return; } }
      const arr = Array.isArray(parsed) ? parsed : [parsed];
      arr.forEach(item => {
        if (!item || !item.RecordId) return;
        if (seen.has(String(item.RecordId))) return;
        seen.add(String(item.RecordId));
        // attach LogName for queries (PowerShell might not always include LogName in some contexts)
        item.LogName = item.LogName || 'Unknown';
        host.db.insertEvent(item, (dberr) => {
          host.emit('event', item);
        });
      });
      // trim seen to avoid unbounded growth
      if (seen.size > 10000) {
        seen = new Set(Array.from(seen).slice(-5000));
      }
    });
  }

  // immediate first poll and then interval
  poll();
  const t = setInterval(poll, pollInterval);

  return {
    stop() { clearInterval(t); }
  };
};

