const http = require('http');
const WebSocket = require('ws');
const path = require('path');
const db = require('./db');

const PORT = process.env.PORT || 8080;
const AUTH_TOKEN = ***

const server = http.createServer();
const wss = new WebSocket.Server({ noServer: true });

const clients = new Set();

const host = {
  db,
  // simple emit to clients
  emit(type, payload) {
    const msg = JSON.stringify({ type, payload });
    for (const ws of clients) {
      if (ws.readyState === WebSocket.OPEN) ws.send(msg);
    }
  },
  // named emit alias used by plugin
  log(source, subtype, detail) {
    // lightweight logging to console
    console.log(`[${source}] ${subtype}:`, detail);
  }
};

server.on('upgrade', (request, socket, head) => {
  const url = new URL(request.url, `http://${request.headers.host}`);
  const token = ***
  if (token !== AUTH_TOKEN) {
    socket.write('HTTP/1.1 401 Unauthorized\r\n\r\n');
    socket.destroy();
    return;
  }
  wss.handleUpgrade(request, socket, head, (ws) => wss.emit('connection', ws, request));
});

wss.on('connection', (ws) => {
  clients.add(ws);
  ws.send(JSON.stringify({ type: 'ready', ts: Date.now() }));

  ws.on('message', (data) => {
    let msg;
    try { msg = JSON.parse(data.toString()); } catch (e) { ws.send(JSON.stringify({ type: 'error', error: 'invalid_json' })); return; }
    const id = msg.id;

    if (msg.type === 'listEvents') {
      const max = (msg.payload && msg.payload.max) ? parseInt(msg.payload.max,10) : 100;
      db.listEvents(max, (err, rows) => {
        ws.send(JSON.stringify({ type: 'listEventsResult', id, error: err ? String(err) : null, payload: rows }));
      });
      return;
    }

    if (msg.type === 'createMacro') {
      const name = (msg.payload && msg.payload.name) ? msg.payload.name : 'macro';
      const triggerRecordId = msg.payload && msg.payload.triggerRecordId;
      db.createMacro(name, triggerRecordId, (err, info) => {
        ws.send(JSON.stringify({ type: 'createMacroResult', id, error: err ? String(err) : null, payload: info }));
      });
      return;
    }

    if (msg.type === 'listMacros') {
      db.listMacros((err, rows) => {
        ws.send(JSON.stringify({ type: 'listMacrosResult', id, error: err ? String(err) : null, payload: rows }));
      });
      return;
    }

    ws.send(JSON.stringify({ type: 'error', id, error: 'unknown_type' }));
  });

  ws.on('close', () => clients.delete(ws));
});

// load plugins
try {
  const evPlugin = require('./plugins/event-collector')(host, { pollIntervalMs: 8000, maxEvents: 50 });
  console.log('EventCollector plugin loaded.');
} catch (e) {
  console.error('Failed to load plugin:', e);
}

server.listen(PORT, () => {
  console.log(`Agent listening on port ${PORT}. Use token param: ?token=***
});

