const sqlite3 = require('sqlite3').verbose();
const path = require('path');
const DB_PATH = path.resolve(__dirname, 'data.db');

const db = new sqlite3.Database(DB_PATH);

db.serialize(() => {
  db.run(`CREATE TABLE IF NOT EXISTS events (
    recordId TEXT PRIMARY KEY,
    logName TEXT,
    timeCreated TEXT,
    id INTEGER,
    level TEXT,
    provider TEXT,
    message TEXT
  )`);
  db.run(`CREATE TABLE IF NOT EXISTS macros (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT,
    triggerRecordId TEXT,
    createdAt TEXT DEFAULT (datetime('now'))
  )`);
});

module.exports = {
  insertEvent(e, cb) {
    const stmt = db.prepare(`INSERT OR IGNORE INTO events(recordId, logName, timeCreated, id, level, provider, message)
      VALUES(?,?,?,?,?,?,?)`);
    stmt.run(e.RecordId, e.LogName, e.TimeCreated, e.Id, e.LevelDisplayName, e.ProviderName, e.Message, function(err) {
      stmt.finalize();
      cb && cb(err, this.changes);
    });
  },
  listEvents(limit = 100, cb) {
    db.all(`SELECT * FROM events ORDER BY timeCreated DESC LIMIT ?`, [limit], (err, rows) => cb(err, rows));
  },
  createMacro(name, triggerRecordId, cb) {
    db.run(`INSERT INTO macros(name, triggerRecordId) VALUES(?,?)`, [name, triggerRecordId], function(err) {
      cb && cb(err, { id: this.lastID });
    });
  },
  listMacros(cb) {
    db.all(`SELECT * FROM macros ORDER BY createdAt DESC`, [], (err, rows) => cb(err, rows));
  }
};

