let ws;
const outEl = document.getElementById('out');
const statusEl = document.getElementById('status');
const logList = document.getElementById('log-list');

function out(s) { outEl.textContent += s + '\n'; outEl.scrollTop = outEl.scrollHeight; }

document.getElementById('connect').addEventListener('click', () => {
  const host = document.getElementById('host').value.trim();
  const token = ***
  if (ws) ws.close();
  const url = `${host}?token=***
  ws = new WebSocket(url);
  ws.onopen = () => statusEl.textContent = 'connected';
  ws.onclose = () => statusEl.textContent = 'closed';
  ws.onmessage = (ev) => {
    out('[RX] ' + ev.data);
    try {
      const msg = JSON.parse(ev.data);
      if (msg.type === 'listLogsResult' && msg.payload) {
        logList.innerHTML = '';
        const arr = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
        arr.forEach(n => { const opt = document.createElement('option'); opt.value = n; opt.textContent = n; logList.appendChild(opt); });
      }
      if (msg.type === 'queryResult' && msg.payload) {
        out(JSON.stringify(msg.payload, null, 2));
      }
    } catch (e) { /* ignore parse errors */ }
  };
  ws.onerror = (e) => out('[ERR] ' + e.message);
});

function sendCmd(obj) {
  if (!ws || ws.readyState !== WebSocket.OPEN) { out('Not connected'); return; }
  obj.id = Math.random().toString(36).slice(2);
  ws.send(JSON.stringify(obj));
  out('[TX] ' + JSON.stringify(obj));
}

document.getElementById('refresh-logs').addEventListener('click', () => sendCmd({ type: 'listLogs' }));
document.getElementById('query-log').addEventListener('click', () => {
  const sel = logList.value;
  const max = parseInt(document.getElementById('maxEvents').value, 10) || 50;
  if (!sel) { out('Select a log'); return; }
  sendCmd({ type: 'query', payload: { logName: sel, maxEvents: max } });
});
